var e={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`},UFMT:{nome:`UFMT`,cor:`#7C3AED`},UFBA:{nome:`UFBA`,cor:`#DC2626`},UFPE:{nome:`UFPE`,cor:`#059669`}},t={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},n={farmacocinetica:{nome:`Farmacocinética`,eixo:`pre`},farmacodinamica:{nome:`Farmacodinâmica`,eixo:`pre`},antimicrobianos:{nome:`Antimicrobianos`,eixo:`clin`},antiinflamatorios:{nome:`Anti-inflamatórios`,eixo:`clin`},analgesicos:{nome:`Analgésicos`,eixo:`clin`},anestesicos:{nome:`Anestésicos`,eixo:`clin`},antiparasitarios:{nome:`Antiparasitários`,eixo:`clin`},cardiovasculares:{nome:`Fármacos Cardiovasculares`,eixo:`clin`},respiratorios:{nome:`Fármacos Respiratórios`,eixo:`clin`},gastrointestinais:{nome:`Fármacos Gastrointestinais`,eixo:`clin`},endocrinos:{nome:`Fármacos Endócrinos`,eixo:`pre`},reprodutores:{nome:`Fármacos Reprodutivos`,eixo:`prod`},antineoplasicos:{nome:`Antineoplásicos`,eixo:`clin`},toxicologia:{nome:`Toxicologia`,eixo:`clin`},interacoes:{nome:`Interações Medicamentosas`,eixo:`pre`},especie:{nome:`Farmacologia por Espécie`,eixo:`clin`}},r=[{id:`farm-001`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Biodisponibilidade`,dificuldade:`medio`,enunciado:`A biodisponibilidade de um fármaco refere-se à fração da dose administrada que alcança a circulação sistêmica. Sobre esse conceito, assinale a alternativa CORRETA:`,alternativas:[`A biodisponibilidade de um fármaco administrado por via intravenosa é sempre inferior a 100%.`,`A biodisponibilidade oral é influenciada pelo efeito de primeira passagem hepática, que pode metabolizar parte do fármaco antes de atingir a circulação sistêmica.`,`Fármacos com alta biodisponibilidade oral necessariamente possuem baixa solubilidade em água.`,`O efeito de primeira passagem ocorre apenas em felinos e não em outras espécies.`,`A biodisponibilidade não é afetada pela formulação farmacêutica (comprimido, cápsula, solução).`],resposta_correta:`B`,explicacao:`A biodisponibilidade oral (F) é a fração da dose que chega à circulação sistêmica após absorção intestinal e passagem pelo fígado (via porta). O efeito de primeira passagem hepática pode metabolizar significativamente o fármaco, reduzindo F. Exemplo: lidocaina tem ~3% de biodisponibilidade oral devido à extensa primeira passagem. A via IV (opção A) tem 100% de biodisponibilidade. A formulação (opção E) afeta diretamente a absorção e, portanto, a biodisponibilidade.`},{id:`farm-002`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Meia-vida`,dificuldade:`dificil`,enunciado:`A meia-vida (t½) de um fármaco é o tempo necessário para que a concentração plasmática seja reduzida pela metade. Sobre esse parâmetro farmacocinético, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A meia-vida de eliminação de um fármaco é determinada pelo clearance (Cl) e pelo volume de distribuição (Vd), segundo a equação t½ = 0,693 × Vd/Cl. Fármacos com alto clearance renal possuem meia-vida mais curta, enquanto fármacos com grande volume de distribuição (acumulação em tecidos) tendem a ter meia-vida mais longa.`,explicacao:`A equação t½ = 0,693 × Vd/Cl é fundamental na farmacocinética. O clearance (Cl) representa a eficiência de eliminação do fármaco (mL/min/kg). O volume de distribuição (Vd) indica a extensão da distribuição tecidual. Exemplo: a digoxina tem Vd muito alto (~7 L/kg, acumula em músculo cardíaco) e Cl baixo, resultando em t½ longa (~40h em cães). Fármacos com alto Cl renal (como a amoxicilina) têm t½ curta (~1-2h).`},{id:`farm-003`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Vias de administração`,dificuldade:`facil`,enunciado:`Sobre as vias de administração de fármacos em animais domésticos, assinale a alternativa CORRETA:`,alternativas:[`A via oral é a mais rápida para atingir concentrações plasmáticas terapêuticas em situações de emergência.`,`A via intramuscular proporciona absorção mais rápida que a via subcutânea devido ao maior fluxo sanguíneo muscular.`,`A via intravenosa não permite o controle preciso da dose administrada.`,`A via transdérmica é amplamente utilizada em bovinos para administração de antibióticos.`,`A via retal é contraindicada em todas as espécies domésticas.`],resposta_correta:`B`,explicacao:`A via intramuscular (IM) proporciona absorção mais rápida que a subcutânea (SC) porque o músculo tem maior vascularização e fluxo sanguíneo. Em cães, a absorção IM pode ser 2-3x mais rápida que SC. A via oral (opção A) é mais lenta devido ao tempo de esvaziamento gástrico e absorção intestinal. A via IV (opção C) permite controle preciso. A via transdérmica (opção D) é usada em pequenos animais (fentanil). A via retal (opção E) é útil em equinos e pequenos animais.`},{id:`farm-004`,banca:`UNESP`,ano:2022,prova:`UNESP — Professor Farmacologia 2022`,tipo:`concurso`,topico:`farmacodinamica`,subtopico:`Receptores`,dificuldade:`dificil`,enunciado:`Sobre os mecanismos de ação dos fármacos e tipos de receptores, assinale a alternativa CORRETA:`,alternativas:[`Agonistas inversos produzem o mesmo efeito que agonistas plenos, mas com menor afinidade.`,`Antagonistas competitivos deslocam a curva dose-resposta do agonista para a esquerda, aumentando a potência.`,`Antagonistas não competitivos reduzem a eficácia máxima do agonista, independentemente da concentração deste.`,`Agonistas parciais produzem efeito máximo inferior ao de agonistas plenos apenas em receptores de reserva.`,`O índice terapêutico é a relação entre a dose tóxica mínima e a dose terapêutica máxima, sendo sempre menor que 1.`],resposta_correta:`C`,explicacao:`Antagonistas não competitivos (ex: fenoxybenzamina em receptores alfa) se ligam irreversivelmente ou em sítio alostérico, reduzindo o número de receptores funcionais. Isso diminui a eficácia máxima (Emax) do agonista, não podendo ser superado por aumento de concentração. Antagonistas competitivos (opção B) deslocam a curva para a DIREITA. Agonistas parciais (opção D) têm Emax inferior mesmo sem receptores de reserva. O IT (opção E) = DL50/DE50, geralmente >1.`},{id:`farm-005`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`farmacodinamica`,subtopico:`Índice terapêutico`,dificuldade:`medio`,enunciado:`O índice terapêutico (IT) é um parâmetro de segurança dos fármacos. Sobre esse conceito, é CORRETO afirmar:`,alternativas:[`Fármacos com IT alto (ex: penicilina) são mais perigosos que fármacos com IT baixo (ex: digoxina).`,`O IT é calculado pela fórmula IT = DL50/DE50, onde DL50 é a dose letal para 50% da população e DE50 é a dose efetiva para 50%.`,`O IT não varia entre espécies animais.`,`Fármacos com IT baixo não necessitam de monitoramento terapêutico.`,`O IT é sempre maior que 10 em fármacos veterinários.`],resposta_correta:`B`,explicacao:`O IT = DL50/DE50 é uma medida de segurança: quanto MAIOR o IT, mais seguro o fármaco. Penicilina (opção A) tem IT muito alto (>100), enquanto digoxina tem IT baixo (~2-3). O IT varia significativamente entre espécies (opção C) — ex: gatos são mais sensíveis ao paracetamol que cães. Fármacos com IT baixo (opção D) necessitam monitoramento (janela terapêutica). IT < 10 (opção E) indica necessidade de cuidado.`},{id:`farm-006`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Beta-lactâmicos`,dificuldade:`medio`,enunciado:`Os antibióticos beta-lactâmicos (penicilinas e cefalosporinas) atuam inibindo a síntese da parede celular bacteriana. Sobre seu mecanismo de ação, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Os beta-lactâmicos se ligam às proteínas ligadoras de penicilina (PBPs), que são transpeptidases responsáveis pela reticulação do peptidoglicano. A inibição das PBPs impede a formação das ligações cruzadas da parede celular, levando ao enfraquecimento osmótico e lise bacteriana. Este mecanismo é bactericida e dependente do tempo de exposição acima da CMI.`,explicacao:`O mecanismo está correto: beta-lactâmicos inibem PBPs (transpeptidases), impedindo a reticulação do peptidoglicano. A ação é bactericida e tempo-dependente (T>MIC é o parâmetro PK/PD mais importante). A parede celular bacteriana é essencial para resistir à pressão osmótica — sem ela, a bactéria lisa. Os beta-lactâmicos NÃO atuam em bactérias em fase estacionária (sem síntese de parede).`},{id:`farm-007`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Veterinário Prefeitura SP 2021`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Fluoroquinolonas`,dificuldade:`medio`,enunciado:`As fluoroquinolonas (enrofloxacina, marbofloxacina, ciprofloxacina) são antimicrobianos amplamente utilizados em medicina veterinária. Sobre suas características, assinale a alternativa INCORRETA:`,alternativas:[`Atuam inibindo a DNA girase (topoisomerase II) e a topoisomerase IV, impedindo a replicação do DNA bacteriano.`,`Possuem amplo espectro de ação, incluindo bactérias Gram-negativas e algumas Gram-positivas.`,`São contraindicadas em animais em crescimento por causarem lesões na cartilagem articular.`,`A enrofloxacina é contraindicada em gatos em altas doses por causar degeneração da retina.`,`Possuem ação bacteriostática, sendo necessária associação com outros antibióticos para efeito sinérgico.`],resposta_correta:`E`,explicacao:`A alternativa E é INCORRETA: fluoroquinolonas são BACTERICIDAS (não bacteriostáticas), atuando por inibição da DNA girase. Possuem concentração-dependente (Cmax/MIC é o parâmetro PK/PD). São contraindicadas em crescimento (opção C, lesão condral). Enrofloxacina em gatos (opção D) causa degeneração de fotorreceptores em doses >5 mg/kg/dia. O espectro (opção B) inclui Enterobacteriaceae, Pseudomonas, Staphylococcus.`},{id:`farm-008`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`enav`,topico:`antimicrobianos`,subtopico:`Aminoglicosídeos`,dificuldade:`dificil`,enunciado:`Os aminoglicosídeos (amicacina, gentamicina, estreptomicina) são antibióticos potentes, mas com toxicidade significativa. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`São absorvidos por via oral e amplamente utilizados em infecções gastrointestinais.`,`Atuam ligando-se à subunidade 30S do ribossomo, inibindo a síntese proteica de forma bactericida.`,`Não possuem nefrotoxicidade nem ototoxicidade em nenhuma espécie.`,`Seu mecanismo de ação é bacteriostático, sendo sinérgicos com beta-lactâmicos.`,`São eficazes contra bactérias anaeróbias obrigatórias.`],resposta_correta:`B`,explicacao:`Aminoglicosídeos ligam-se à subunidade 30S ribossomal, causando leitura errada do mRNA e inibição da síntese proteica. A ação é bactericida (concentração-dependente, Cmax/MIC). NÃO são absorvidos por via oral (opção A, exceto em infecções intestinais). Possuem nefrotoxicidade (acúmulo em células tubulares) e ototoxicidade (opção C). São bactericidas (opção D). NÃO atuam em anaeróbios obrigatórios (opção E, ausência de transporte ativo aeróbio).`},{id:`farm-009`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário CETESB 2020`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Tetraciclinas`,dificuldade:`facil`,enunciado:`As tetraciclinas (oxitetraciclina, doxiciclina, clortetraciclina) atuam:`,alternativas:[`Inibindo a síntese do ácido fólico bacteriano.`,`Ligando-se à subunidade 50S do ribossomo, bloqueando a translocação.`,`Ligando-se à subunidade 30S do ribossomo, impedindo a ligação do aminoacil-tRNA ao ribossomo.`,`Inibindo a DNA girase bacteriana.`,`Desestabilizando a membrana citoplasmática bacteriana.`],resposta_correta:`C`,explicacao:`Tetraciclinas ligam-se reversivelmente à subunidade 30S do ribossomo, impedindo a ligação do aminoacil-tRNA ao sítio A, inibindo a síntese proteica (bacteriostático). Sulfonamidas/trimetoprima (opção A) inibem o ácido fólico. Macrolídeos (opção B) ligam-se à 50S. Fluoroquinolonas (opção D) inibem DNA girase. Polimixinas (opção E) desestabilizam membrana.`},{id:`farm-010`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`enav`,topico:`antiinflamatorios`,subtopico:`AINEs`,dificuldade:`medio`,enunciado:`Os anti-inflamatórios não esteroidais (AINEs) inibem as enzimas cicloxigenases (COX). Sobre a seletividade dos AINEs veterinários, assinale a alternativa CORRETA:`,alternativas:[`O meloxicam é altamente seletivo para COX-1, sendo o AINE mais seguro para uso em cães.`,`O flunixin meglumine é inibidor não seletivo de COX-1 e COX-2, sendo indicado para cólica equina.`,`O carprofeno é altamente seletivo para COX-2 e não possui efeito sobre COX-1 em nenhuma espécie.`,`A fenilbutazona é segura para uso em gatos, sendo amplamente utilizada na clínica felina.`,`Todos os AINEs possuem o mesmo perfil de segurança em todas as espécies domésticas.`],resposta_correta:`B`,explicacao:`O flunixin meglumine é um AINE não seletivo (COX-1/COX-2) potente, indicado para dor visceral e cólica equina (0,25 mg/kg IV). O meloxicam (opção A) é preferencialmente COX-2. O carprofeno (opção C) é seletivo COX-2 em cães, mas a seletividade varia entre espécies. A fenilbutazona (opção D) é TÓXICA em gatos (metabolismo hepático deficiente). O perfil de segurança (opção E) varia muito entre espécies.`},{id:`farm-011`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário IBAMA 2022`,tipo:`concurso`,topico:`antiinflamatorios`,subtopico:`Corticosteroides`,dificuldade:`dificil`,enunciado:`Os corticosteroides são potentes anti-inflamatórios imunossupressores. Sobre seu uso em medicina veterinária, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A dexametasona é aproximadamente 25-30 vezes mais potente que a prednisolona como anti-inflamatório, possui longa duração de ação (36-54h) e não apresenta efeito mineralocorticoide significativo. É o corticosteroide de escolha para edema cerebral em cães devido à sua alta potência e penetração no SNC.`,explicacao:`A dexametasona tem potência anti-inflamatória ~25-30x superior à hidrocortisona, sem efeito mineralocorticoide (não retém Na⁺). Sua meia-vida biológica é longa (36-54h), permitindo doses em dias alternados. Para edema cerebral, a dexametasona é preferida pela alta penetração no SNC. Equivalências: dexametasona 0,75 mg ≈ prednisolona 5 mg ≈ hidrocortisona 20 mg.`},{id:`farm-012`,banca:`UFMG`,ano:2021,prova:`UFMG — Residência Clínica Pequenos Animais 2021`,tipo:`residencia`,topico:`analgesicos`,subtopico:`Opioides`,dificuldade:`medio`,enunciado:`Sobre o uso de opioides em medicina veterinária, assinale a alternativa CORRETA:`,alternativas:[`A morfina é contraindicada em gatos por causar excitação paradoxal em todas as doses.`,`O tramadol é um opioide sintético de ação central que também inibe a recaptação de serotonina e noradrenalina.`,`A buprenorfina é um agonista pleno dos receptores mu, sendo o opioide mais potente disponível.`,`O fentanil possui longa duração de ação (12-24h), sendo ideal para analgesia pós-cirúrgica de longo prazo.`,`Os opioides não causam depressão respiratória em nenhuma espécie animal.`],resposta_correta:`B`,explicacao:`O tramadol é um opioide atípico que, além de agonista fraco mu, inibe a recaptação de serotonina (5-HT) e noradrenalina (NE), contribuindo para analgesia descendente. A morfina (opção A) pode ser usada em gatos com cautela (excitação em altas doses). Buprenorfina (opção C) é agonista PARCIAL mu. Fentanil (opção D) tem curta duração (20-40 min IV). Opioides (opção E) causam depressão respiratória dose-dependente.`},{id:`farm-013`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Veterinário Prefeitura RJ 2020`,tipo:`concurso`,topico:`analgesicos`,subtopico:`Alfa-2 agonistas`,dificuldade:`medio`,enunciado:`Os agonistas alfa-2 adrenérgicos (xilazina, detomidina, dexmedetomidina) possuem propriedades sedativas, analgésicas e miorrelaxantes. Sobre seus efeitos, assinale a alternativa INCORRETA:`,alternativas:[`A xilazina causa bradicardia por aumento do tônus vagal e redução da liberação de noradrenalina.`,`O detomidina é amplamente utilizado em equinos para sedação e procedimentos diagnósticos.`,`A dexmedetomidina possui maior seletividade para receptores alfa-2 em relação à xilazina.`,`Os alfa-2 agonistas podem causar hiperglicemia por inibição da liberação de insulina.`,`A xilazina é segura para uso em bovinos gestantes sem risco de aborto.`],resposta_correta:`E`,explicacao:`A alternativa E é INCORRETA: a xilazina é CONTRAINDICADA em bovinos gestantes pois pode causar contração uterina e aborto (especialmente no último trimestre). Em bovinos, a xilazina causa bradicardia, salivação, ruminal e hiperglicemia. A dexmedetomidina (opção C) é ~8x mais seletiva alfa-2/alfa-1 que a xilazina. A hiperglicemia (opção D) ocorre por inibição da secreção de insulina pelas células beta pancreáticas.`},{id:`farm-014`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`enav`,topico:`anestesicos`,subtopico:`Quetamina`,dificuldade:`medio`,enunciado:`A quetamina é um anestésico dissociativo amplamente utilizado em medicina veterinária. Sobre suas características farmacológicas, assinale a alternativa CORRETA:`,alternativas:[`A quetamina é um agonista dos receptores GABA-A, produzindo sedação dose-dependente.`,`A quetamina bloqueia os receptores NMDA (N-metil-D-aspartato), produzindo estado de catalepsia com preservação dos reflexos faríngeo e palpebral.`,`A quetamina é contraindicada em felinos por causar depressão respiratória grave.`,`A quetamina não possui efeito analgésico, sendo necessária associação com opioides para qualquer tipo de dor.`,`A quetamina causa relaxamento muscular profundo, sendo ideal para procedimentos ortopédicos.`],resposta_correta:`B`,explicacao:`A quetamina é antagonista não competitiva dos receptores NMDA, produzindo dissociação tálamo-neocortical (catalepsia). Os reflexos faríngeo, palpebral e corneano são preservados. É amplamente usada em felinos (opção C é falsa). Possui analgesia visceral moderada (opção D é falsa). NÃO causa relaxamento muscular (opção E, causa rigidez muscular — necessita associação com alfa-2 agonista ou benzodiazepínico).`},{id:`farm-015`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`anestesicos`,subtopico:`Anestésicos inalatórios`,dificuldade:`dificil`,enunciado:`Os anestésicos inalatórios (isoflurano, sevoflurano) são fundamentais na anestesia geral veterinária. Sobre suas características, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O isoflurano possui coeficiente de partição sangue/gas de 1,46, o que confere início de ação intermediário e recuperação moderada. O sevoflurano (coeficiente 0,69) possui início de ação mais rápido e recuperação mais rápida que o isoflurano, sendo preferível para indução por máscara em pequenos animais. Ambos causam depressão cardiovascular dose-dependente, reduzindo a pressão arterial média por vasodilatação periférica.`,explicacao:`O coeficiente de partição sangue/gas determina a velocidade: menor coeficiente = início e recuperação mais rápidos. Sevoflurano (0,69) > isoflurano (1,46) em termos de velocidade. O sevoflurano é menos pungente, permitindo indução por máscara. Ambos causam depressão cardiovascular por vasodilatação e redução da contratilidade miocárdica. MAC isoflurano cão: ~1,3%; sevoflurano cão: ~2,3%.`},{id:`farm-016`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário Ministério Público 2023`,tipo:`concurso`,topico:`antiparasitarios`,subtopico:`Endectocidas`,dificuldade:`medio`,enunciado:`A ivermectina é um endectocida (antiparasitário de amplo espectro) da classe das lactonas macrocíclicas. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`A ivermectina é segura para uso em todas as raças de cães, incluindo Collie e Pastor-branco.`,`A ivermectina atua potencializando os canais de cloreto mediados por glutamato em nematódes e artrópodes, causando paralisia muscular.`,`A ivermectina é eficaz contra cestódes (vermes chatos) e trematódes.`,`A dose profilática de ivermectina para prevenção de Dirofilaria immitis em cães é de 0,5 mg/kg/dia.`,`A ivermectina não atravessa a barreira hematoencefálica em nenhuma espécie.`],resposta_correta:`B`,explicacao:`A ivermectina potencializa canais de cloreto mediados por glutamato (GluCl) em invertebrados, causando hiperpolarização e paralisia flácida. Em cães com mutação MDR1 (opção A, Collie, Pastor-branco), a ivermectina em doses terapêuticas pode causar neurotoxicidade (atravessa BHE). NÃO é eficaz contra cestódes/trematódes (opção C). A dose profilática para Dirofilaria (opção D) é 0,006 mg/kg/mês (6-12 mcg/kg).`},{id:`farm-017`,banca:`ENAV`,ano:2018,prova:`ENAV — Concurso 2018`,tipo:`enav`,topico:`antiparasitarios`,subtopico:`Benzimidazóis`,dificuldade:`facil`,enunciado:`Os benzimidazóis (albendazol, fenbendazol, mebendazol) são antiparasitários internos. Seu mecanismo de ação consiste em:`,alternativas:[`Inibir a enzima colinesterase, causando acúmulo de acetilcolina e paralisia do parasita.`,`Ligar-se à tubulina, inibindo a polimerização dos microtúbulos, prejudicando a absorção de glicose pelo parasita.`,`Bloquear os canais de cálcio musculares do parasita, causando paralisia espástica.`,`Inibir a síntese de DNA do parasita por intercalação nas bases nitrogenadas.`,`Potencializar os canais de cloreto mediados por GABA no sistema nervoso do parasita.`],resposta_correta:`B`,explicacao:`Benzimidazóis ligam-se à beta-tubulina dos parasitas, inibindo a polimerização de microtúbulos. Isso prejudica o transporte de glicose (fonte de energia) e funções celulares dependentes do citoesqueleto, levando à morte do parasita. Inibidores de colinesterase (opção A) = organofosforados. Bloqueadores de Ca²⁺ (opção C) = levamisol. Intercaladores de DNA (opção D) = não é mecanismo antiparasitário. Potencializadores de GABA (opção E) = ivermectina (em invertebrados).`},{id:`farm-018`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Residência Clínica Equinos 2022`,tipo:`residencia`,topico:`cardiovasculares`,subtopico:`Digitálicos`,dificuldade:`dificil`,enunciado:`A digoxina é o glicosídeo cardíaco mais utilizado em medicina veterinária. Sobre seu mecanismo de ação e uso clínico, assinale a alternativa CORRETA:`,alternativas:[`A digoxina aumenta a contratilidade miocárdica (efeito inotrópico positivo) inibindo a Na⁺/K⁺-ATPase, o que indiretamente aumenta o cálcio intracelular.`,`A digoxina é segura em gatos, sendo o fármaco de primeira escolha para cardiomiopatia hipertrófica.`,`A digoxina possui índice terapêutico alto, não necessitando de monitoramento dos níveis séricos.`,`A digoxina é exclusivamente excretada por via hepática, não sendo afetada por insuficiência renal.`,`A intoxicação por digoxina causa taquicardia como único efeito adverso.`],resposta_correta:`A`,explicacao:`A digoxina inibe a Na⁺/K⁺-ATPase, acumulando Na⁺ intracelular. Isso reduz a atividade do trocador Na⁺/Ca²⁺, resultando em acúmulo de Ca²⁺ intracelular → aumento da contratilidade (inotropismo positivo). Possui IT BAIXO (opção C, necessita monitoramento). É excretada renalmente (opção D). Em gatos (opção B), é usada com cautela. Intoxicação (opção E) causa bradicardia, arritmias, náusea.`},{id:`farm-019`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`cardiovasculares`,subtopico:`Diuréticos`,dificuldade:`medio`,enunciado:`Os diuréticos são fármacos que aumentam a excreção renal de água e eletrólitos. Sobre a classificação e uso, assinale a alternativa CORRETA:`,alternativas:[`A furosemida é um diurético poupador de potássio que atua no túbulo distal.`,`A espironolactona é um diurético de alça que inibe o cotransportador Na⁺/K⁺/2Cl⁻.`,`A furosemida é um diurético de alça que atua na porção espessa da alça ascendente de Henle, inibindo o cotransportador Na⁺/K⁺/2Cl⁻.`,`A hidroclorotiazida atua nos túbulos coletores, inibindo a reabsorção de água.`,`Os diuréticos osmóticos (manitol) atuam inibindo a secreção de ADH.`],resposta_correta:`C`,explicacao:`A furosemida é o diurético de alça mais potente, atuando na porção espessa da alça ascendente de Henle, inibindo o cotransportador NKCC2 (Na⁺/K⁺/2Cl⁻). Causa grande excreção de Na⁺, K⁺, Cl⁻, Ca²⁺, Mg²⁺. Espironolactona (opção B) é antagonista de aldosterona (poupadora de K⁺). Hidroclorotiazida (opção D) atua no túbulo distal inicial. Manitol (opção E) é osmótico (filtra-se mas não é reabsorvido).`},{id:`farm-020`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura RJ 2022`,tipo:`concurso`,topico:`gastrointestinais`,subtopico:`Antieméticos`,dificuldade:`medio`,enunciado:`Sobre os antieméticos utilizados em medicina veterinária, assinale a alternativa CORRETA:`,alternativas:[`A metoclopramida é um antagonista de receptores D2 no centro do vômito e possui efeito procinético gástrico.`,`O ondansetrona é um antagonista de receptores D2 que atua exclusivamente na zona gatilho quimiorreceptora.`,`O maropitant (Cerenia) é um antagonista de receptores NK1 (substância P) indicado para náusea e vômito em cães.`,`A metoclopramida atravessa a barreira hematoencefálica e não possui efeitos colaterais neurológicos.`,`O ondansetrona e o maropitant possuem o mesmo mecanismo de ação.`],resposta_correta:`C`,explicacao:`O maropitant é antagonista seletivo de receptores NK1 (substância P), atuando tanto no centro do vômito quanto na ZGCR e aferências viscerais. É indicado para vômito agudo em cães (e off-label em gatos). Metoclopramida (opção A) é D2 antagonista + procinética, mas pode causar efeitos extrapiramidais. Ondansetrona (opção B) é antagonista 5-HT3, não D2. Metoclopramida (opção D) pode causar efeitos neurológicos.`},{id:`farm-021`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`endocrinos`,subtopico:`Insulina`,dificuldade:`medio`,enunciado:`A insulina é o principal hormônio hipoglicemiante. Sobre as preparações de insulina veterinárias, assinale a alternativa CORRETA:`,alternativas:[`A insulina glargina (Lantus) é uma insulina de ação ultrarrápida, indicada para crises hiperglicêmicas.`,`A insulina NPH (isofana) possui ação intermediária (6-12h) e é amplamente utilizada no manejo do diabetes mellitus em cães e gatos.`,`A insulina regular (cristalina) possui ação prolongada (24-36h), sendo administrada uma vez ao dia.`,`Todas as preparações de insulina possuem a mesma duração de ação em todas as espécies.`,`A insulina lantus (glargina) é contraindicada em gatos por causar hipoglicemia severa.`],resposta_correta:`B`,explicacao:`A insulina NPH (isofana) é uma insulina intermediária com duração de 6-12h em cães e 4-8h em gatos. É a mais utilizada no diabetes canino. Insulina glargina (opção A) é de ação prolongada (24h), usada em gatos. Insulina regular (opção C) é de ação curta (4-6h) para uso IV. A duração varia entre espécies (opção D). Glargina (opção E) é segura em gatos.`},{id:`farm-022`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título Reprodução Animal 2022`,tipo:`concurso`,topico:`reprodutores`,subtopico:`Hormônios reprodutivos`,dificuldade:`medio`,enunciado:`Os protocolos de sincronização de estro em bovinos utilizam hormônios reprodutivos. Sobre o uso de prostaglandina F2α (PGF2α) e seus análogos, assinale a alternativa CORRETA:`,alternativas:[`A PGF2α causa lise do corpo lúteo (luteólise) em bovinos, sendo eficaz apenas do dia 5 ao 17 do ciclo estral.`,`A PGF2α é eficaz em qualquer fase do ciclo estral, inclusive nos primeiros 4 dias (corpo lúteo resistente).`,`O cloprostenol (análogo de PGF2α) é contraindicado em fêmeas gestantes por não possuir efeito luteolítico.`,`A PGF2α não possui efeitos colaterais em bovinos, sendo seguro em qualquer dose.`,`O protocolo Ovsynch utiliza apenas PGF2α sem GnRH.`],resposta_correta:`A`,explicacao:`A PGF2α e seus análogos (cloprostenol, dinoprost) causam lise do corpo lúteo, sendo eficazes apenas quando há corpo lúteo funcional (dia 5-17 do ciclo). Nos primeiros 4 dias, o CL é resistente à luteólise. É CONTRAINDICADA em gestantes (opção C é falsa — é contraindicada, mas pelo efeito abortivo, não por falta de eficácia). Pode causar efeitos colaterais (opção D, salivação, defecação). Ovsynch (opção E) usa GnRH + PGF2α + GnRH.`},{id:`farm-023`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`enav`,topico:`reprodutores`,subtopico:`Ocitocina`,dificuldade:`facil`,enunciado:`A ocitocina é um hormônio peptídico com múltiplas indicações em medicina veterinária. Sobre seus efeitos, assinale a alternativa CORRETA:`,alternativas:[`A ocitocina estimula a contração do músculo liso uterino e a ejeção do leite (reflexo de descida).`,`A ocitocina é contraindicada em todos os casos de distocia.`,`A ocitocina não possui efeito sobre o músculo liso uterino, atuando exclusivamente nas mamas.`,`A ocitocina é uma hormônio esteroide produzida pelo ovário.`,`A dose de ocitocina é a mesma para todas as espécies domésticas.`],resposta_correta:`A`,explicacao:`A ocitocina é um nonapeptídeo produzido no hipotálamo e armazenado na neuro-hipófise. Seus principais efeitos: (1) contração do miométrio (útero), essencial para o parto; (2) contração das células mioepiteliais da glândula mamária (ejeção do leite). Pode ser usada em distocia (opção B é falsa) para auxiliar na expulsão fetal. É peptídica (opção D), não esteroide. A dose varia por espécie (opção E).`},{id:`farm-024`,banca:`CESPE`,ano:2024,prova:`CESPE — Médico Veterinário IBAMA 2024`,tipo:`concurso`,topico:`toxicologia`,subtopico:`Organofosforados`,dificuldade:`dificil`,enunciado:`A intoxicação por organofosforados (diazinon, clorpirifós, malation) é uma das mais comuns em animais de produção. Sobre o mecanismo de intoxicação e tratamento, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`B`,vf:!0,vf_texto:`O tratamento da intoxicação por organofosforados inclui atropina (antagonista muscarínico) para controlar os efeitos parassimpáticos e pralidoxima (2-PAM) para reativar a acetilcolinesterase. A atropina é eficaz apenas nos efeitos muscarínicos (salivação, lacrimejamento, broncoespasmo, bradicardia), não revertendo os efeitos nicotínicos (fasciculações musculares) e centrais (convulsões).`,explicacao:`O item está parcialmente correto mas FALSO no detalhe: a atropina NÃO reverte os efeitos nicotínicos e centrais. O tratamento correto inclui: (1) Atropina para efeitos muscarínicos, (2) Pralidoxima (2-PAM) para reativar AChE (eficaz nas primeiras 24-48h), (3) Diazepam para convulsões, (4) Descontaminação (lavagem, carvão ativado). Os organofosforados inativam a AChE por fosforilação, causando acúmulo de ACh.`},{id:`farm-025`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário Prefeitura Campinas 2021`,tipo:`concurso`,topico:`toxicologia`,subtopico:`Intoxicação por plantas`,dificuldade:`medio`,enunciado:`A intoxicação por plantas é uma importante causa de morte em animais de produção no Brasil. Sobre as principais plantas tóxicas, assinale a alternativa CORRETA:`,alternativas:[`A Senecio spp. (crassina) causa hepatotoxicidade por alcaloides pirrolizidínicos, levando a fibrose hepática e cirrose.`,`A Brachiaria spp. causa fotossensibilização primária, sem lesão hepática.`,`O Palicourea marcgravii (café do mato) contém fluoroacetato de sódio, causando morte súbita por insuficiência cardíaca.`,`A Sorghum halepense (sorgo de Alepo) causa cistite enzoótica, sem relação com intoxicação por nitratos.`,`A Ricinus communis (mamona) é tóxica apenas para bovinos, não afetando outras espécies.`],resposta_correta:`A`,explicacao:`A Senecio spp. contém alcaloides pirrolizidínicos que são metabolizados no fígado em pirróis reativos, causando necrose hepatocelular, fibrose e cirrose. Brachiaria (opção B) causa fotossensibilização SECUNDÁRIA (por disfunção hepática). Palicourea (opção C) contém monofluoroacetato, inibindo o ciclo de Krebs. Sorghum (opção D) pode conter nitratos/cianetos. Mamona (opção E) é tóxica para múltiplas espécies (ricina).`},{id:`farm-026`,banca:`UNESP`,ano:2020,prova:`UNESP — Professor Adjunto Farmacologia 2020`,tipo:`concurso`,topico:`interacoes`,subtopico:`Sinergismo e antagonismo`,dificuldade:`dificil`,enunciado:`Sobre interações medicamentosas em veterinária, assinale a alternativa que descreve corretamente uma interação clinicamente relevante:`,alternativas:[`A associação de AINEs e corticosteroides é segura e recomendada para potencializar o efeito anti-inflamatório.`,`O uso concomitante de aminoglicosídeos e diuréticos de alça (furosemida) aumenta o risco de nefrotoxicidade e ototoxicidade.`,`A eritromicina e a rifampicina possuem sinergismo antimicrobiano, sendo frequentemente associadas.`,`O uso de metronidazol com álcool etílico não causa efeitos adversos em cães.`,`A associação de inibidores da MAO (selegilina) com tramadol é segura em cães.`],resposta_correta:`B`,explicacao:`A associação aminoglicosídeo + furosemida (diurético de alça) é classicamente potencializadora de toxicidade: ambos são nefrotóxicos e ototóxicos, e a furosemida potencia esses efeitos por alterar o fluxo sanguíneo renal e a concentração do antibiótico no ouvido interno. AINEs + corticosteroides (opção A) aumentam risco de úlcera GI. Eritromicina + rifampicina (opção C) são antagônicas. Metronidazol + etanol (opção D) causa efeito dissulfiram-like. Selegilina + tramadol (opção E) risco de síndrome serotoninérgica.`},{id:`farm-027`,banca:`UFMT`,ano:2021,prova:`UFMT — Residência Clínica Bovinos 2021`,tipo:`residencia`,topico:`especie`,subtopico:`Farmacologia em bovinos`,dificuldade:`dificil`,enunciado:`A farmacologia em bovinos possui particularidades importantes devido à fisiologia ruminal. Sobre o uso de fármacos nessa espécie, assinale a alternativa CORRETA:`,alternativas:[`Os bovinos possuem metabolismo hepático eficiente de fármacos, semelhante ao de cães e gatos.`,`A via intramuscular no músculo do pescoço é preferida em bovinos devido ao maior fluxo sanguíneo nessa região.`,`A via oral de fármacos em bovinos pode ser comprometida pela degradação ruminal e pelo pH ácido do rúmen.`,`Os bovinos não possuem variações interespecíficas no metabolismo de fármacos.`,`A administração subcutânea no flanco é a via de escolha para antibióticos em bovinos.`],resposta_correta:`C`,explicacao:`O rúmen de bovinos (pH 5,5-7,0, microorganismos) pode degradar fármacos antes da absorção. Antibióticos como penicilina G podem ser degradados pelas bactérias ruminais. A via oral em ruminantes requer fármacos resistentes à degradação ruminal ou formulações especiais. O metabolismo hepático de bovinos (opção A) é mais lento que em cães. A via IM no pescoço (opção B) não é necessariamente preferida. A via SC (opção E) não é ideal para antibióticos.`},{id:`farm-028`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`especie`,subtopico:`Farmacologia em felinos`,dificuldade:`medio`,enunciado:`Os gatos possuem deficiências metabólicas únicas que afetam a farmacologia. Sobre o uso de fármacos em felinos, assinale a alternativa CORRETA:`,alternativas:[`Os gatos possuem atividade normal de glucuronidação, semelhante a cães.`,`O paracetamol (acetaminofeno) é seguro em gatos na mesma dose utilizada em cães.`,`Os gatos possuem deficiência na enzima glucuronosiltransferase, tornando-os sensíveis a fármacos metabolizados por glucuronidação (ex: paracetamol, propilenoglicol).`,`Os gatos não metabolizam AINEs, sendo seguro o uso de qualquer AINE em altas doses.`,`Os gatos possuem mais receptores GABA que cães, sendo mais sensíveis a benzodiazepínicos.`],resposta_correta:`C`,explicacao:`Os gatos possuem deficiência na glucuronosiltransferase (UGT), enzima da fase II do metabolismo hepático. Isso torna-os sensíveis a fármacos dependentes dessa via: paracetamol (metabólito tóxico NAPQI não é glucuronidado → metemoglobinemia), propilenoglicol (excitante), aspirina (meia-vida ~38h em gatos vs 6h em cães). Paracetamol (opção B) é TÓXICO em gatos (dose >10 mg/kg). AINEs (opção D) requerem doses reduzidas.`},{id:`farm-029`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`especie`,subtopico:`Farmacologia em equinos`,dificuldade:`medio`,enunciado:`A farmacologia equina possui particularidades importantes. Sobre o uso de fármacos em equinos, assinale a alternativa INCORRETA:`,alternativas:[`Os equinos possuem refluxo ceco-cólico significativo, o que pode atrasar a absorção de fármacos administrados por via oral.`,`A fenilbutazona é amplamente utilizada como analgésico em equinos, com dose máxima de 4,4 mg/kg/dia.`,`Os equinos são extremamente sensíveis à lidocaina intravenosa, que pode causar excitação e convulsões.`,`A xilazina causa profunda sedação em equinos, sendo amplamente utilizada para procedimentos clínicos.`,`Os equinos possuem metabolismo hepático eficiente, sendo seguro o uso de qualquer fármaco em altas doses.`],resposta_correta:`E`,explicacao:`A alternativa E é INCORRETA: embora os equinos tenham metabolismo hepático relativamente eficiente, NÃO é seguro usar qualquer fármaco em altas doses. Exemplos: aminoglicosídeos podem causar nefrotoxicidade, e AINEs podem causar úlcera GI. O refluxo ceco-cólico (opção A) é real e afeta a farmacocinética oral. Fenilbutazona (opção B) é analgésica com dose limitada. Lidocaina IV (opção C) pode causar excitação. Xilazina (opção D) é excelente sedativa equina.`},{id:`farm-030`,banca:`FCC`,ano:2019,prova:`FCC — Veterinário Prefeitura SP 2019`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Sulfonamidas`,dificuldade:`medio`,enunciado:`As sulfonamidas e o trimetoprima atuam inibindo a síntese do ácido fólico bacteriano em etapas consecutivas. Sobre essa associação, assinale a alternativa CORRETA:`,alternativas:[`As sulfonamidas inibem a diidropteroato sintetase e o trimetoprima inibe a diidrofolato redutase, produzindo sinergismo bactericida.`,`As sulfonamidas e o trimetoprima atuam no mesmo alvo enzimático, produzindo efeito aditivo.`,`As sulfonamidas são bactericidas quando utilizadas isoladamente.`,`O trimetoprima é mais eficaz isoladamente do que em associação com sulfonamidas.`,`As sulfonamidas competem com a glicose pelo sítio ativo da diidropteroato sintetase.`],resposta_correta:`A`,explicacao:`A associação sulfonamida + trimetoprima (cotrimoxazol) atua em dois pontos da via do ácido fólico: sulfonamidas inibem a diidropteroato sintetase (competem com PABA) e trimetoprima inibe a diidrofolato redutase. O bloqueio sequencial produz sinergismo BACTERICIDA. Isoladamente (opção C), sulfonamidas são bacteriostáticas. A competição (opção E) é com PABA (ácido para-aminobenzoico), não glicose.`},{id:`farm-031`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Volume de distribuição`,dificuldade:`medio`,enunciado:`O volume de distribuição (Vd) é um parâmetro farmacocinético que indica a extensão da distribuição de um fármaco nos tecidos. Sobre esse conceito, assinale a alternativa CORRETA:`,alternativas:[`Fármacos com Vd alto (ex: digoxina) permanecem predominantemente no plasma.`,`Fármacos lipossolúveis tendem a possuir Vd menor que fármacos hidrossolúveis.`,`O Vd é calculado pela relação Vd = dose total administrada / concentração plasmática inicial, e valores acima de 1 L/kg sugerem extensa distribuição tecidual.`,`O Vd não é influenciado pela ligação proteica do fármaco.`,`Fármacos com Vd baixo são ideais para distribuição ao SNC.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Fármacos com Vd alto saem do plasma e se distribuem amplamente nos tecidos, como a digoxina (Vd ~7 L/kg) que se acumula no músculo cardíaco.`,B:`Fármacos lipossolúveis atravessam membranas facilmente e possuem Vd MAIOR, pois se distribuem em mais tecidos.`,C:`Correto. Vd = dose/C0. Valores >1 L/kg indicam que o fármaco está mais nos tecidos que no plasma. Digoxina (~7 L/kg) e cloranfenicol (~2 L/kg) são exemplos de alto Vd.`,D:`A ligação proteica reduz o Vd, pois fármacos ligados a proteínas plasmáticas permanecem no compartimento vascular.`,E:`Fármacos com Vd baixo permanecem no plasma e não distribuem bem ao SNC, que requer fármacos lipossolúveis com alto Vd.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Toutain PL, Bousquet-Mélou A`,titulo:`Volumes of distribution`,journal:`J Vet Pharmacol Ther`,ano:2004}]},{id:`farm-032`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Clearance`,dificuldade:`dificil`,enunciado:`O clearance (Cl) é o volume de plasma depurado de um fármaco por unidade de tempo. Sobre esse parâmetro, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O clearance total de um fármaco é a soma dos clearances renal, hepático e de outros órgãos (Cl total = Cl renal + Cl hepático + Cl outros). A meia-vida de eliminação é inversamente proporcional ao clearance: t½ = 0,693 × Vd/Cl. Fármacos com clearance hepático alto (ex: propranolol) são sensíveis às alterações do fluxo sanguíneo hepático, enquanto fármacos com clearance renal alto (ex: amicacina) necessitam ajuste de dose em pacientes com insuficiência renal.`,explicacoes_alternativas:{A:`Correto. O clearance total é aditivo. A equação t½ = 0,693 × Vd/Cl demonstra que clearance alto resulta em meia-vida curta. Fármacos com Cl hepático alto são flow-dependent (dependem do fluxo sanguíneo hepático), enquanto os de Cl renal alto requerem ajuste posológico na insuficiência renal.`,B:`O item está correto. O clearance é o parâmetro mais importante para determinar a dose de manutenção (dose = Cl × Css × intervalo).`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Toutain PL, Bousquet-Mélou A`,titulo:`Plasma clearance`,journal:`J Vet Pharmacol Ther`,ano:2004}]},{id:`farm-033`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Veterinário Prefeitura SP 2021`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Primeira passagem`,dificuldade:`medio`,enunciado:`O efeito de primeira passagem hepática é um fenômeno que reduz a biodisponibilidade de fármacos administrados por via oral. Sobre esse efeito, assinale a alternativa CORRETA:`,alternativas:[`A lidocaína possui alta biodisponibilidade oral (acima de 80%) por não sofrer metabolismo de primeira passagem.`,`O efeito de primeira passagem ocorre exclusivamente no fígado, sem contribuição de outros órgãos.`,`Fármacos com intenso metabolismo de primeira passagem podem ter sua biodisponibilidade oral aumentada em pacientes com insuficiência hepática ou shunts portossistêmicos.`,`A propranolol possui baixo metabolismo de primeira passagem, resultando em biodisponibilidade oral constante.`,`O efeito de primeira passagem é exclusivo de felinos e não ocorre em outras espécies.`],resposta_correta:`C`,explicacoes_alternativas:{A:`A lidocaína tem biodisponibilidade oral de apenas ~3% devido ao extenso metabolismo de primeira passagem hepática.`,B:`O metabolismo de primeira passagem também ocorre na parede intestinal (enzimas CYP3A4 intestinais) e no pulmão para alguns fármacos.`,C:`Correto. Em pacientes com shunt portossistêmico ou insuficiência hepática, o fármaco contorna o fígado, aumentando a biodisponibilidade. Isso é clinicamente relevante em cães com shunts congênitos.`,D:`A propranolol possui ALTO metabolismo de primeira passagem (biodisponibilidade oral ~25%), sendo um clássico exemplo desse fenômeno.`,E:`O efeito de primeira passagem ocorre em todas as espécies mamíferas, não sendo exclusivo de felinos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Toutain PL, Bousquet-Mélou A`,titulo:`Bioavailability and its assessment`,journal:`J Vet Pharmacol Ther`,ano:2004}]},{id:`farm-034`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário CETESB 2020`,tipo:`concurso`,topico:`farmacocinetica`,subtopico:`Absorção`,dificuldade:`facil`,enunciado:`Sobre os fatores que influenciam a absorção de fármacos no trato gastrointestinal, assinale a alternativa CORRETA:`,alternativas:[`Fármacos ionizados são mais facilmente absorvidos pela membrana celular que fármacos não ionizados.`,`O pH do trato gastrointestinal não influencia a absorção de fármacos ácidos e básicos.`,`A presença de alimentos no estômago sempre reduz a absorção de todos os fármacos.`,`Fármacos ácidos fracos (ex: aspirina) são melhor absorvidos no estômago (pH ácido), onde predominam na forma não ionizada, lipossolúvel.`,`A motilidade gastrointestinal não afeta a velocidade de absorção dos fármacos.`],resposta_correta:`D`,explicacoes_alternativas:{A:`Fármacos NÃO ionizados são mais lipossolúveis e atravessam mais facilmente as membranas celulares por difusão passiva (pH-partition hypothesis).`,B:`O pH é fundamental: fármacos ácidos se absorvem em meio ácido (estômago) e básicos em meio alcalino (intestino), conforme o pKa.`,C:`Alimentos podem aumentar a absorção de alguns fármacos (ex: lipossolúveis com gordura) ou diminuir de outros (ex: tetraciclinas com cálcio).`,D:`Correto. Pela equação de Henderson-Hasselbalch, em pH ácido (estômago), ácidos fracos como aspirina (pKa 3,5) predominam na forma não ionizada, facilitando a difusão transmembrana.`,E:`A motilidade afeta diretamente o tempo de trânsito intestinal e, portanto, a velocidade e extensão da absorção.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Martinez MN, Amidon GL`,titulo:`A mechanistic approach to understanding the factors affecting drug absorption`,journal:`Clin Pharmacokinet`,ano:2002}]},{id:`farm-035`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`farmacocinetica`,subtopico:`Biodisponibilidade`,dificuldade:`dificil`,enunciado:`A biodisponibilidade absoluta (F) de um fármaco é calculada comparando-se a AUC (área sob a curva) após administração extravascular com a AUC após administração intravenosa. Sobre esse cálculo, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A biodisponibilidade absoluta é calculada pela fórmula F = (AUC extravascular / AUC IV) × (dose IV / dose extravascular) × 100%. Quando se comparam duas formulações de um mesmo fármaco pela mesma via, utiliza-se a biodisponibilidade relativa, calculada pela razão entre as AUCs das duas formulações. A AUC reflete a exposição total ao fármaco ao longo do tempo.`,explicacoes_alternativas:{A:`Correto. A biodisponibilidade absoluta utiliza a via IV como referência (F=100%). A biodisponibilidade relativa compara formulações. A AUC é proporcional à quantidade de fármaco que alcança a circulação sistêmica.`,B:`O item está correto. A AUC é o parâmetro mais confiável para estimar a biodisponibilidade, pois integra a concentração ao longo de todo o tempo.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Toutain PL, Bousquet-Mélou A`,titulo:`Bioavailability and its assessment`,journal:`J Vet Pharmacol Ther`,ano:2004}]},{id:`farm-036`,banca:`UFMG`,ano:2020,prova:`UFMG — Residência Clínica Pequenos Animais 2020`,tipo:`residencia`,topico:`farmacocinetica`,subtopico:`Meia-vida`,dificuldade:`facil`,enunciado:`A meia-vida de eliminação (t½) é utilizada para determinar o intervalo de dosagem de um fármaco. Sobre sua aplicação clínica, assinale a alternativa CORRETA:`,alternativas:[`Para atingir o estado de equilíbrio (steady state), são necessárias aproximadamente 3-5 meias-vidas de administração regular.`,`A meia-vida não influencia o tempo para atingir o steady state.`,`O tempo de meia-vida é sempre o mesmo em todas as espécies animais.`,`Fármacos com meia-vida muito curta devem ser administrados uma vez ao dia.`,`O estado de equilíbrio é atingido após a primeira dose administrada.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. O steady state é atingido em ~4-5 meias-vidas. Após 3 t½, ~87,5% do steady state é atingido; após 5 t½, ~96,9%. Esse conceito é essencial para determinar quando avaliar concentrações plasmáticas.`,B:`A meia-vida é o principal determinante do tempo para atingir o steady state. Meia-vida longa = steady state mais demorado.`,C:`A meia-vida varia significativamente entre espécies (ex: aspirina t½ ~6h em cães, ~38h em gatos).`,D:`Fármacos com meia-vida curta necessitam administração mais frequente ou infusão contínua para manter concentrações terapêuticas.`,E:`O steady state requer múltiplas doses. A primeira dose atinge apenas o pico inicial.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Toutain PL`,titulo:`Antimicrobial drug action and pharmacokinetics`,journal:`J Vet Pharmacol Ther`,ano:2002}]},{id:`farm-037`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Veterinário Prefeitura RJ 2023`,tipo:`concurso`,topico:`farmacodinamica`,subtopico:`Receptores`,dificuldade:`medio`,enunciado:`Sobre os tipos de receptores e mecanismos de transdução de sinal, assinale a alternativa CORRETA:`,alternativas:[`Receptores canais iônicos (ex: receptor GABA-A) respondem lentamente, em minutos, à ligação do agonista.`,`Receptores acoplados a proteína G (GPCRs) são os mais numerosos na terapêutica veterinária e incluem receptores adrenérgicos, muscarínicos e opioides.`,`Receptores com atividade enzimática intrínseca (ex: receptor de insulina) não utilizam segundos mensageiros.`,`Receptores nucleares (ex: receptor de corticosteroides) atuam exclusivamente na membrana celular.`,`Todos os receptores possuem a mesma afinidade por diferentes ligantes.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Receptores canais iônicos (receptores ionotrópicos) respondem RAPIDAMENTE (milissegundos), pois a ligação do agonista abre diretamente o canal.`,B:`Correto. GPCRs são a maior família de alvos farmacológicos. Incluem receptores adrenérgicos (α e β), muscarínicos (M1-M5), opioides (μ, κ, δ), histamina (H1, H2) e muitos outros.`,C:`Receptores tirosina quinase (insulina, fatores de crescimento) utilizam cascatas de segundos mensageiros (PI3K/Akt, Ras/MAPK).`,D:`Receptores nucleares são intracitoplasmáticos ou intranucleares, não na membrana. Atuam como fatores de transcrição.`,E:`Cada receptor possui afinidade específica por diferentes ligantes, determinada pela constante de dissociação (Kd).`},referencias:[{autores:`Rang HP, Dale MM`,titulo:`Rang and Dale's Pharmacology`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-038`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`farmacodinamica`,subtopico:`Agonistas e antagonistas`,dificuldade:`medio`,enunciado:`Sobre agonistas e antagonistas farmacológicos, assinale a alternativa INCORRETA:`,alternativas:[`O naloxano é um antagonista pleno dos receptores opioides μ, sendo utilizado como antídoto em intoxicações por opioides.`,`A buprenorfina é um agonista parcial μ com alta afinidade, deslocando outros opioides do receptor.`,`O butorfanol é um agonista κ e antagonista μ, sendo utilizado como analgésico e antitussígeno.`,`Um antagonista competitivo desloca a curva dose-resposta do agonista para a esquerda, aumentando a potência.`,`A atropina é um antagonista competitivo dos receptores muscarínicos, bloqueando os efeitos parassimpáticos.`],resposta_correta:`D`,explicacoes_alternativas:{A:`Correto. Naloxano é antagonista pleno μ, reversível, utilizado para reverter depressão respiratória por opioides.`,B:`Correto. Buprenorfina tem alta afinidade pelo receptor μ (dissociação lenta), é agonista parcial com longa duração.`,C:`Correto. Butorfanol é agonista κ (analgesia) e antagonista μ (reverte efeitos de agonistas plenos).`,D:`INCORRETO. Antagonista competitivo desloca a curva para a DIREITA (não esquerda), pois é necessário mais agonista para competir pelo receptor.`,E:`Correto. Atropina compete com acetilcolina pelo receptor muscarínico, bloqueando efeitos como bradicardia, broncoespasmo e secreções.`},referencias:[{autores:`Rang HP, Dale MM`,titulo:`Rang and Dale's Pharmacology`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-039`,banca:`UNESP`,ano:2021,prova:`UNESP — Professor Farmacologia 2021`,tipo:`concurso`,topico:`farmacodinamica`,subtopico:`ED50 e DL50`,dificuldade:`dificil`,enunciado:`Os parâmetros DE50 (dose efetiva para 50% da população) e DL50 (dose letal para 50% da população) são fundamentais para avaliar a segurança de fármacos. Sobre esses conceitos, assinale a alternativa CORRETA:`,alternativas:[`A DL50 é sempre menor que a DE50 em fármacos terapêuticos seguros.`,`O índice terapêutico (IT = DL50/DE50) é um indicador absoluto de segurança, sendo válido para todas as espécies sem exceção.`,`A janela terapêutica define a faixa de concentrações plasmáticas entre a concentração mínima efetiva (CME) e a concentração mínima tóxica (CMT), sendo mais relevante clinicamente que o IT calculado em animais de laboratório.`,`O IT de um fármaco é sempre idêntico em cães, gatos, equinos e bovinos.`,`A DE50 é determinada exclusivamente em estudos clínicos, sem necessidade de modelos animais.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Em fármacos seguros, a DL50 é MUITO MAIOR que a DE50 (IT alto). Se DL50 < DE50, o fármaco seria letal antes de ser eficaz.`,B:`O IT é uma medida útil, mas relativa. Varia entre espécies, indivíduos e condições clínicas. Não é absoluto.`,C:`Correto. A janela terapêutica (CME-CMT) é mais clinicamente relevante que o IT experimental, pois considera concentrações plasmáticas reais no paciente.`,D:`O IT varia significativamente entre espécies (ex: paracetamol é seguro em cães mas letal em gatos).`,E:`A DE50 é determinada em estudos pré-clínicos com modelos animais, antes dos ensaios clínicos.`},referencias:[{autores:`Rang HP, Dale MM`,titulo:`Rang and Dale's Pharmacology`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-040`,banca:`UFRRJ`,ano:2020,prova:`UFRRJ — Residência Clínica Pequenos Animais 2020`,tipo:`residencia`,topico:`farmacodinamica`,subtopico:`Curva dose-resposta`,dificuldade:`medio`,enunciado:`A curva dose-resposta relaciona a concentração de um fármaco com seu efeito farmacológico. Sobre essa relação, assinale a alternativa CORRETA:`,alternativas:[`A potência de um fármaco é determinada pela altura máxima da curva dose-resposta (Emax).`,`A eficácia de um fármaco é determinada pela posição horizontal da curva no eixo das doses (DE50).`,`A eficácia (Emax) representa o efeito máximo que o fármaco pode produzir, enquanto a potência (DE50) representa a dose necessária para produzir 50% do efeito máximo.`,`Agonistas parciais e agonistas plenos possuem sempre a mesma eficácia máxima.`,`A curva dose-resposta não é influenciada pela presença de antagonistas.`],resposta_correta:`C`,explicacoes_alternativas:{A:`A altura máxima (Emax) determina a EFICÁCIA, não a potência. A potência é determinada pela posição horizontal (DE50).`,B:`A DE50 indica a POTÊNCIA (dose para 50% do efeito), não a eficácia. A eficácia é o Emax.`,C:`Correto. Eficácia (Emax) = efeito máximo possível. Potência (DE50) = dose necessária para 50% do Emax. Um fármaco pode ser potente (baixa DE50) mas pouco eficaz (baixo Emax).`,D:`Agonistas parciais têm Emax INFERIOR ao de agonistas plenos, mesmo com alta concentração.`,E:`Antagonistas deslocam a curva (competitivos) ou reduzem a Emax (não competitivos), alterando significativamente a curva dose-resposta.`},referencias:[{autores:`Rang HP, Dale MM`,titulo:`Rang and Dale's Pharmacology`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-041`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`farmacodinamica`,subtopico:`Índice terapêutico`,dificuldade:`facil`,enunciado:`Sobre o índice terapêutico (IT) e segurança dos fármacos, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`B`,vf:!0,vf_texto:`O índice terapêutico de um fármaco é calculado pela fórmula IT = DL50/DE50. Um IT alto indica maior segurança, enquanto um IT baixo indica risco de toxicidade. A penicilina possui IT muito alto (>100), enquanto a digoxina possui IT baixo (~2-3). Fármacos com IT baixo necessitam de monitoramento terapêutico (dosagem sérica) para manter concentrações dentro da janela terapêutica.`,explicacoes_alternativas:{A:`O item está correto em parte, mas o enunciado pede para julgar se está totalmente correto. O IT = DL50/DE50 é uma simplificação — na prática, utiliza-se CT50/CE50 (concentração tóxica/efetiva) ou a janela terapêutica. No entanto, o conceito apresentado é amplamente aceito.`,B:`CORRETO como resposta. Embora o conceito geral esteja correto, o IT é uma medida experimental simplificada. Na prática clínica, a janela terapêutica (CME-CMT) é mais útil. Além disso, IT = DL50/DE50 é calculado em animais de laboratório e pode não refletir a segurança em pacientes clínicos.`},referencias:[{autores:`Rang HP, Dale MM`,titulo:`Rang and Dale's Pharmacology`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-042`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Macrolídeos`,dificuldade:`medio`,enunciado:`Os macrolídeos (eritromicina, tilosina, tilmicosina, tulatromicina) são antibióticos que atuam inibindo a síntese proteica bacteriana. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`Os macrolídeos ligam-se à subunidade 30S do ribossomo, impedindo a translocação.`,`A tilmicosina é segura para uso em equinos, sendo amplamente utilizada nessa espécie.`,`Os macrolídeos ligam-se à subunidade 50S do ribossomo, inibindo a translocação do peptidil-tRNA, sendo bacteriostáticos em concentrações usuais e bactericidas em altas concentrações.`,`A tulatromicina possui curta meia-vida, necessitando de administração diária.`,`Os macrolídeos são eficazes contra bactérias Gram-negativas aeróbias de amplo espectro.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Macrolídeos ligam-se à subunidade 50S (não 30S). Tetraciclinas ligam-se à 30S.`,B:`Tilmicosina é CARDIOTÓXICA em equinos e suínos, causando morte súbita por edema pulmonar e arritmias. Contraindicada nessas espécies.`,C:`Correto. Macrolídeos ligam-se ao sítio peptidil transferase da 50S, bloqueando a translocação. São bacteriostáticos usualmente, bactericidas em altas concentrações e contra bactérias sensíveis.`,D:`Tulatromicina (Draxxin) possui meia-vida extremamente longa (~90h em bovinos), permitindo dose única.`,E:`Macrolídeos têm espectro predominante contra Gram-positivos e alguns Gram-negativos limitados (Pasteurella, Mycoplasma). Não são de amplo espectro para Gram-negativos aeróbios.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-043`,banca:`CESPE`,ano:2020,prova:`CESPE — Médico Veterinário MAPA 2020`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Cefalosporinas`,dificuldade:`dificil`,enunciado:`As cefalosporinas são antibióticos beta-lactâmicos classificados em gerações. Sobre sua classificação e uso veterinário, assinale a alternativa CORRETA:`,alternativas:[`As cefalosporinas de 1ª geração (cefazolina, cefalexina) possuem maior espectro contra Gram-negativos que as de 3ª geração.`,`A ceftiofur é uma cefalosporina de 3ª geração aprovada para uso veterinário, com amplo espectro incluindo Enterobacteriaceae e anaeróbios.`,`As cefalosporinas de 4ª geração (cefepime) possuem ação exclusivamente bacteriostática.`,`A cefovecina (Convenia) é uma cefalosporina de 1ª geração de ação curta, administrada diariamente.`,`As cefalosporinas não possuem atividade contra Staphylococcus spp. em nenhuma geração.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Cefalosporinas de 1ª geração têm melhor atividade contra Gram-positivos. As de 3ª geração têm maior espectro contra Gram-negativos.`,B:`Correto. Ceftiofur (Naxcel) é cefalosporina de 3ª geração veterinária, ativa contra Gram-negativos (E. coli, Salmonella, Pasteurella), Gram-positivos e alguns anaeróbios. Usada em bovinos, suínos e equinos.`,C:`Cefepime é bactericida (como todas as cefalosporinas), atuando na síntese da parede celular.`,D:`Cefovecina (Convenia) é cefalosporina de 4ª geração de ação prolongada (14 dias em cães), administrada por via SC.`,E:`Cefalosporinas de 1ª geração possuem excelente atividade contra Staphylococcus spp.`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-044`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário Ministério Público 2022`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Antifúngicos`,dificuldade:`dificil`,enunciado:`Os antifúngicos utilizados em medicina veterinária possuem mecanismos de ação e perfis de toxicidade variados. Sobre o uso de antifúngicos, assinale a alternativa CORRETA:`,alternativas:[`Anfotericina B liga-se ao ergosterol da membrana fúngica, formando poros que causam extravasamento de conteúdo intracelular. Possui nefrotoxicidade significativa.`,`Cetoconazol é o antifúngico de primeira escolha para tratamento de infecções sistêmicas em cães por possuir excelente penetração no SNC.`,`Itraconazol e fluconazol não possuem vantagens sobre cetoconazol em termos de segurança e espectro.`,`Griseofulvina é eficaz contra leveduras (Candida spp.) e fungos dimórficos.`,`Os antifúngicos azólicos atuam inibindo a síntese de quitina da parede celular fúngica.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Anfotericina B (polieno) liga-se ao ergosterol, formando canais iônicos na membrana fúngica. É nefrotóxica (acúmulo em células tubulares renais), devendo ser monitorada com dosagem de creatinina.`,B:`Cetoconazol possui penetração limitada no SNC e hepatotoxicidade significativa. Fluconazol é preferível para infecções do SNC.`,C:`Itraconazol tem espectro mais amplo (Aspergillus) e fluconazol melhor penetração no SNC e menor hepatotoxicidade que cetoconazol.`,D:`Griseofulvina é eficaz contra DERMATÓFITOS (Microsporum, Trichophyton), não contra leveduras ou fungos dimórficos.`,E:`Azólicos inibem a 14-α-desmetilase (CYP51), impedindo a síntese de ERGOSTEROL (não quitina). Quitina é alvo de equinocandinas.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-045`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Penicilinas`,dificuldade:`facil`,enunciado:`As penicilinas são os antibióticos beta-lactâmicos mais antigos e amplamente utilizados. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`A penicilina G procaína possui ação prolongada (12-24h) e é amplamente utilizada em bovinos por via intramuscular.`,`A amoxicilina é resistente às beta-lactamases bacterianas, sendo eficaz contra Staphylococcus produtores de penicilinase.`,`A penicilina G é estável em meio ácido gástrico, sendo efetiva por via oral.`,`Todas as penicilinas possuem o mesmo espectro de ação, sem variações entre os tipos.`,`A ampicilina possui menor espectro que a penicilina G, sendo ativa apenas contra Gram-positivos.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Penicilina G procaína é uma formulação de depósito com absorção lenta, mantendo concentrações terapêuticas por 12-24h. É amplamente usada em bovinos para infecções respiratórias e pododermatites.`,B:`Amoxicilina é sensível a beta-lactamases. Amoxicilina + ácido clavulânico (clavulanato) é que é resistente.`,C:`Penicilina G é lábil em meio ácido, sendo degradada no estômago. Penicilina V é resistente ao pH ácido.`,D:`Existem diferenças significativas: penicilina G (estreito, Gram-positivos), ampicilina/amoxicilina (mais amplo, Gram-negativos), oxacilina (anti-estafilocócica).`,E:`Ampicilina tem espectro EXPANDIDO em relação à penicilina G, incluindo alguns Gram-negativos (E. coli, Salmonella).`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-046`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Sulfonamidas`,dificuldade:`medio`,enunciado:`As sulfonamidas são antimicrobianos bacteriostáticos que atuam inibindo a síntese do ácido fólico. Sobre seus efeitos adversos, assinale a alternativa CORRETA:`,alternativas:[`As sulfonamidas não causam efeitos adversos renais em nenhuma espécie.`,`As sulfonamidas podem causar cristalúria (formação de cristais na urina) em pacientes desidratados ou com urina ácida, sendo recomendada hidratação adequada durante o tratamento.`,`As sulfonamidas são seguras em cavalos em qualquer dose, sem risco de laminitis.`,`As sulfonamidas não interagem com outros fármacos, sendo seguras em politerapia.`,`As sulfonamidas são contraindicadas em todas as espécies por causarem aplasia de medula óssea.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Sulfonamidas podem causar cristalúria e nefrotoxicidade, especialmente em desidratados.`,B:`Correto. Sulfonamidas pouco solúveis precipitam em urina ácida, formando cristais que causam obstrução renal. Hidratação e alcalinização da urina são preventivas.`,C:`Altas doses de sulfonamidas em equinos podem causar laminitis, diarreia e cólica.`,D:`Sulfonamidas interagem com vários fármacos: potencializam anticoagulantes, deslocam metotrexato de proteínas plasmáticas.`,E:`Aplasia de medula é um efeito raro, não uma contraindicação absoluta para todas as espécies.`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-047`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`enav`,topico:`antimicrobianos`,subtopico:`Fluoroquinolonas`,dificuldade:`dificil`,enunciado:`Sobre a relação farmacocinética/farmacodinâmica (PK/PD) dos antimicrobianos, assinale a alternativa que associa CORRETAMENTe o parâmetro PK/PD ao grupo de antimicrobianos:`,alternativas:[`Beta-lactâmicos: Cmax/MIC (concentração-dependente).`,`Fluoroquinolonas: T>MIC (tempo-dependente).`,`Aminoglicosídeos: AUC/MIC (exposição-dependente).`,`Fluoroquinolonas: Cmax/MIC (concentração-dependente) e AUC/MIC (exposição-dependente), sendo os parâmetros mais correlacionados com eficácia.`,`Macrolídeos: Cmax/MIC (concentração-dependente).`],resposta_correta:`D`,explicacoes_alternativas:{A:`Beta-lactâmicos são tempo-dependentes (T>MIC), não concentração-dependentes. A eficácia depende do tempo acima da CMI.`,B:`Fluoroquinolonas são concentração-dependentes e exposição-dependentes (Cmax/MIC e AUC/MIC), não tempo-dependentes.`,C:`Aminoglicosídeos são concentração-dependentes (Cmax/MIC), não AUC/MIC. A alta concentração de pico é o parâmetro mais importante.`,D:`Correto. Fluoroquinolonas exibem atividade concentração-dependente e exposição-dependente. Cmax/MIC >10 e AUC/MIC >100-125 são alvos para eficácia bactericida ótima.`,E:`Macrolídeos são tempo-dependentes (T>MIC) ou exposição-dependentes (AUC/MIC), não concentração-dependentes como os aminoglicosídeos.`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Toutain PL`,titulo:`Antimicrobial drug action and pharmacokinetics`,journal:`J Vet Pharmacol Ther`,ano:2002}]},{id:`farm-048`,banca:`UFMT`,ano:2022,prova:`UFMT — Residência Clínica Bovinos 2022`,tipo:`residencia`,topico:`antimicrobianos`,subtopico:`Aminoglicosídeos`,dificuldade:`medio`,enunciado:`A gentamicina e a amicacina são aminoglicosídeos utilizados em infecções graves por bactérias Gram-negativas. Sobre seu monitoramento terapêutico, assinale a alternativa CORRETA:`,alternativas:[`A monitorização dos níveis séricos de aminoglicosídeos não é necessária, pois possuem amplo índice terapêutico.`,`O pico sérico (Cmax) de gentamicina deve ser mantido acima de 8-10 μg/mL para eficácia ótima, enquanto o vale (Cmin) deve ser mantido abaixo de 2 μg/mL para minimizar nefrotoxicidade.`,`A amicacina possui maior nefrotoxicidade que a gentamicina, sendo menos segura.`,`Os aminoglicosídeos não apresentam efeito pós-antibiótico (EPA).`,`A dose de aminoglicosídeos não deve ser ajustada em pacientes com insuficiência renal.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Aminoglicosídeos possuem IT BAIXO e necessitam de monitoramento obrigatório dos níveis séricos.`,B:`Correto. A dosagem uma vez ao dia (DOD) de aminoglicosídeos visa Cmax/MIC >8-10 para eficácia e Cmin <2 μg/mL para evitar acúmulo e nefrotoxicidade.`,C:`Gentamicina é mais nefrotóxica que amicacina. Amicacina é preferida em pacientes com risco renal.`,D:`Aminoglicosídeos possuem significativo efeito pós-antibiótico (EPA de 2-6h), o que justifica a dosagem uma vez ao dia.`,E:`A dose DEVE ser ajustada na insuficiência renal, pois aminoglicosídeos são eliminados por filtração glomerular.`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-049`,banca:`CESPE`,ano:2019,prova:`CESPE — Analista MAPA 2019`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Beta-lactâmicos`,dificuldade:`medio`,enunciado:`A resistência bacteriana aos beta-lactâmicos é mediada principalmente pela produção de beta-lactamases. Sobre mecanismos de resistência, assinale a alternativa CORRETA:`,alternativas:[`As beta-lactamases de espectro estendido (BLEEs) hidrolisam apenas penicilinas, não afetando cefalosporinas.`,`O ácido clavulânico é um inibidor de beta-lactamase que protege a amoxicilina da degradação enzimática, sendo ativo contra BLEEs.`,`A resistência aos beta-lactâmicos é exclusivamente mediada por beta-lactamases, sem outros mecanismos.`,`A alteração das PBPs (ex: MRSA) não é um mecanismo relevante de resistência aos beta-lactâmicos.`,`Os inibidores de beta-lactamase (clavulanato, sulbactam, tazobactam) possuem atividade antibacteriana significativa quando utilizados isoladamente.`],resposta_correta:`B`,explicacoes_alternativas:{A:`BLEEs hidrolisam cefalosporinas de 3ª geração, além de penicilinas. São um problema crescente em Enterobacteriaceae.`,B:`Correto. Ácido clavulânico é um inibidor suicida de beta-lactamase que protege a amoxicilina. É eficaz contra beta-lactamases de espectro estendido (BLEEs) de plasmídeos.`,C:`Existem outros mecanismos: alteração de PBPs (MRSA), permeabilidade reduzida (porinas) e bombas de efluxo.`,D:`Alteração de PBPs é o principal mecanismo de resistência do MRSA (PBP2a/mecA), sendo clinicamente muito relevante.`,E:`Inibidores de beta-lactamase possuem atividade antibacteriana insignificante quando isolados; atuam apenas como protetores.`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-050`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`enav`,topico:`antimicrobianos`,subtopico:`Antifúngicos`,dificuldade:`medio`,enunciado:`O itraconazol é o antifúngico azólico mais utilizado em medicina veterinária para infecções sistêmicas. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`O itraconazol possui biodisponibilidade oral constante, não sendo afetada pela presença de alimentos.`,`O itraconazol é o azólico de escolha para blastomicose, coccidioidomicose e esporotricose em cães, possuindo amplo espectro contra fungos dimórficos e leveduras.`,`O itraconazol não interage com outros fármacos metabolizados pelo citocromo P450.`,`O itraconazol não possui hepatotoxicidade, sendo seguro em altas doses prolongadas.`,`O fluconazol é superior ao itraconazol para tratamento de Aspergillus spp.`],resposta_correta:`B`,explicacoes_alternativas:{A:`A biodisponibilidade do itraconazol é variável e aumenta significativamente com alimentos (absorção dependente de pH gástrico e gordura).`,B:`Correto. Itraconazol é o azólico de escolha para infecções fúngicas sistêmicas em cães, com amplo espectro contra Blastomyces, Coccidioides, Sporothrix, Histoplasma e Aspergillus.`,C:`Itraconazol é potente inibidor de CYP3A4, interagindo com muitos fármacos (ciclosporina, midazolam, etc).`,D:`Itraconazol possui hepatotoxicidade dose-dependente, requerendo monitoramento de enzimas hepáticas.`,E:`Itraconazol é SUPERIOR ao fluconazol para Aspergillus. Fluconazol não tem atividade significativa contra Aspergillus.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Legendre AM`,titulo:`Antifungal therapy in small animals`,journal:`Vet Clin North Am Small Anim Pract`,ano:2020}]},{id:`farm-051`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Veterinário Prefeitura RJ 2020`,tipo:`concurso`,topico:`antimicrobianos`,subtopico:`Tetraciclinas`,dificuldade:`medio`,enunciado:`A doxiciclina é a tetracicлина mais utilizada em medicina veterinária. Sobre sua farmacologia, assinale a alternativa CORRETA:`,alternativas:[`A doxiciclina deve ser administrada com leite ou antiácidos para melhorar sua absorção.`,`A doxiciclina possui menor incidência de efeitos adversos esofágicos que outras tetraciclinas, devendo ser administrada com alimento ou água abundante em pequenos animais.`,`As tetraciclinas podem causar hipoplasia do esmalte dental e descoloração em animais jovens em crescimento, sendo contraindicadas antes da troca de dentição.`,`A doxiciclina é exclusivamente excretada por via renal, não sendo afetada por insuficiência hepática.`,`A doxiciclina é contraindicada em gatos por causar hepatotoxicidade grave.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Cálcio (leite), ferro e antiácidos quelam tetraciclinas, REDUZINDO sua absorção. Devem ser evitados.`,B:`Doxiciclina pode causar esofagite/estenose esofágica em gatos e cães se administrada sem alimento ou água. Deve ser dada com alimento.`,C:`Correto. Tetraciclinas quelam cálcio em dentes e ossos em formação, causando hipoplasia do esmalte e descoloração amarelo-acastanhada. Contraindicadas em animais jovens em crescimento.`,D:`Doxiciclina é eliminada predominantemente por via FECAL (excreção biliar), sendo segura em insuficiência renal.`,E:`Doxiciclina é segura em gatos nas doses adequadas (5-10 mg/kg/dia).`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-052`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`antiinflamatorios`,subtopico:`COX-1 e COX-2`,dificuldade:`dificil`,enunciado:`As enzimas cicloxigenases (COX-1 e COX-2) possuem funções fisiológicas distintas. Sobre a seletividade dos AINEs veterinários, assinale a alternativa CORRETA:`,alternativas:[`A COX-1 é uma enzima induzível que é expressa apenas durante processos inflamatórios.`,`A COX-2 é constitutiva e presente em todos os tecidos, sendo responsável pela produção de prostaglandinas gastroprotetoras.`,`A COX-1 é constitutiva e produz prostaglandinas envolvidas em funções fisiológicas (proteção gástrica, agregação plaquetária, fluxo renal), enquanto a COX-2 é induzida pela inflamação, embora também seja constitutiva em alguns tecidos (rim, cérebro).`,`A inibição seletiva de COX-2 elimina completamente o risco de efeitos adversos renais.`,`O meloxicam é inibidor seletivo de COX-1, sendo o AINE mais seguro para uso em gatos.`],resposta_correta:`C`,explicacoes_alternativas:{A:`COX-1 é CONSTITUTIVA (expressa continuamente), não induzível. COX-2 é a forma induzida pela inflamação.`,B:`COX-1 (não COX-2) é constitutiva e produz prostaglandinas gastroprotetoras. COX-2 é predominantemente induzida.`,C:`Correto. COX-1 é constitutiva (proteção GI, agregação plaquetária, função renal). COX-2 é induzida na inflamação, mas também constitutiva em rim, cérebro e endotélio vascular.`,D:`A inibição de COX-2 pode causar efeitos renais, pois COX-2 é constitutiva no rim (regulação do fluxo sanguíneo renal).`,E:`Meloxicam é preferencialmente seletivo para COX-2 (não COX-1). É utilizado em cães e gatos com cautela.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Beretta C, et al.`,titulo:`COX-1/COX-2 selectivity of veterinary NSAIDs`,journal:`J Vet Pharmacol Ther`,ano:2005}]},{id:`farm-053`,banca:`CESPE`,ano:2023,prova:`CESPE — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`antiinflamatorios`,subtopico:`Corticosteroides`,dificuldade:`medio`,enunciado:`Sobre os efeitos adversos do uso prolongado de corticosteroides em animais, assinale a alternativa CORRETA:`,alternativas:[`O uso prolongado de corticosteroides causa iatrogenia de Cushing (hiperadrenocorticismo iatrogênico), com sinais clínicos incluindo poliúria, polidipsia, polifagia, obesidade abdominal e dermatite atrófica.`,`Os corticosteroides não afetam o metabolismo de glicose em nenhuma espécie.`,`O uso de corticosteroides é seguro em pacientes diabéticos, sem risco de descompensação.`,`A suspensão abrupta de corticosteroides após uso prolongado não causa efeitos adversos.`,`Os corticosteroides não causam imunossupressão, sendo seguros em pacientes com infecções.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. O uso prolongado de corticosteroides causa hipercortisolismo iatrogênico com sinais clássicos de Cushing: PU/PD, polifagia, obesidade, hepatomegalia, dermatite atrófica, fraqueza muscular.`,B:`Corticosteroides causam hiperglicemia significativa por aumentar a gliconeogênese e causar resistência à insulina.`,C:`Corticosteroides pioram significativamente o diabetes mellitus, sendo relativamente contraindicados em diabéticos.`,D:`A suspensão abrupta pode causar crise addisoniana (insuficiência adrenal aguda) por supressão do eixo HPA. A retirada deve ser gradual.`,E:`Corticosteroides são potentes imunossupressores, sendo contraindicados em infecções ativas (exceto em situações específicas como choque séptico).`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015}]},{id:`farm-054`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário Ministério Público 2023`,tipo:`concurso`,topico:`antiinflamatorios`,subtopico:`AINEs`,dificuldade:`facil`,enunciado:`O meloxicam é um AINE preferencialmente seletivo para COX-2, amplamente utilizado em cães e gatos. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`O meloxicam é contraindicado em gatos por causar nefrotoxicidade grave em qualquer dose.`,`O meloxicam pode ser utilizado em gatos para analgesia e anti-inflamação, com dose reduzida (0,05 mg/kg/dia) e monitoramento renal.`,`O meloxicam possui o mesmo perfil de segurança em todas as espécies domésticas.`,`O meloxicam é seguro para uso concomitante com corticosteroides.`,`O meloxicam não é metabolizado pelo fígado, sendo eliminado inalterado pelos rins.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Meloxicam PODE ser utilizado em gatos com dose reduzida e monitoramento. O meloxicam é um dos poucos AINEs aprovados para uso em felinos (na Europa e Austrália).`,B:`Correto. Meloxicam (0,05 mg/kg/dia SC ou VO) é utilizado em gatos para dor aguda e crônica (osteoartrite), com monitoramento de função renal.`,C:`O perfil de segurança varia significativamente entre espécies (gatos são mais sensíveis que cães a muitos AINEs).`,D:`AINEs + corticosteroides aumentam significativamente o risco de úlcera gastrointestinal e nefrotoxicidade.`,E:`Meloxicam é extensivamente metabolizado no fígado por CYP2C9, com excreção biliar e renal.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Lascelles BDX, et al.`,titulo:`Meloxicam in cats with osteoarthritis`,journal:`J Feline Med Surg`,ano:2018}]},{id:`farm-055`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`antiinflamatorios`,subtopico:`AINEs`,dificuldade:`medio`,enunciado:`O carprofeno é um AINE preferencialmente COX-2 amplamente utilizado em cães. Sobre suas características, assinale a alternativa INCORRETA:`,alternativas:[`O carprofeno é um AINE derivado do ácido propiônico com seletividade preferencial para COX-2 em cães.`,`O carprofeno é indicado para dor aguda pós-operatória e dor crônica musculoesquelética em cães.`,`O carprofeno possui hepatotoxicidade idiossincrática rara em cães, manifestando-se como hepatite necrosante.`,`O carprofeno é seguro para uso em gatos na mesma dose utilizada em cães, sem necessidade de ajuste.`,`O carprofeno deve ser utilizado com cautela em pacientes com doença renal ou hepática preexistente.`],resposta_correta:`D`,explicacoes_alternativas:{A:`Correto. Carprofeno (Rimadyl) é derivado do ácido propiônico com seletividade COX-2 em cães.`,B:`Correto. É indicado para dor pós-operatória (injeção única) e osteoartrite (uso crônico).`,C:`Correto. Hepatotoxicidade idiossincrática é rara mas potencialmente fatal, ocorrendo em cães sensíveis geneticamente.`,D:`INCORRETO. Carprofeno não é aprovado para gatos e requer doses muito reduzidas (1-2 mg/kg) quando utilizado off-label.`,E:`Correto. Como todos os AINEs, deve ser usado com cautela em pacientes com comprometimento renal ou hepático.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Lascelles BDX, et al.`,titulo:`Carprofen safety in dogs`,journal:`J Vet Intern Med`,ano:2005}]},{id:`farm-056`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Residência Clínica Equinos 2021`,tipo:`residencia`,topico:`antiinflamatorios`,subtopico:`AINEs`,dificuldade:`medio`,enunciado:`A fenilbutazona é o AINE mais utilizado em equinos para tratamento de dor musculoesquelética. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`A fenilbutazona é segura em gatos, sendo amplamente utilizada na clínica felina.`,`A fenilbutazona pode causar úlcera gástrica e right dorsal colite em equinos, especialmente em doses acima de 4,4 mg/kg/dia e uso prolongado.`,`A fenilbutazona possui índice terapêutico alto em equinos, não necessitando de monitoramento.`,`A fenilbutazona não interage com outros fármacos em equinos.`,`A fenilbutazona é contraindicada em equinos por ser extremamente tóxica.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Fenilbutazona é TÓXICA em gatos (metabolismo deficiente por glucuronidação), causando necrose renal e anemia aplásica.`,B:`Correto. Fenilbutazona causa úlcera gástrica e colite do cólon dorsal direito em equinos, especialmente acima de 4,4 mg/kg/dia ou com uso prolongado. É dose-limitante.`,C:`A fenilbutazona possui IT relativamente baixo em equinos, necessitando de monitoramento clínico e dose máxima.`,D:`Fenilbutazona desloca outros fármacos de proteínas plasmáticas (warfarina, sulfonamidas) e é um potente indutor/inibidor enzimático.`,E:`Fenilbutazona é amplamente utilizada em equinos, mas dentro dos limites de dose e duração.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`McConnico RS, et al.`,titulo:`Phenylbutazone toxicosis in horses`,journal:`J Am Vet Med Assoc`,ano:2008}]},{id:`farm-057`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`antiinflamatorios`,subtopico:`Corticosteroides`,dificuldade:`facil`,enunciado:`Sobre a classificação dos corticosteroides por potência anti-inflamatória, assinale a alternativa CORRETA:`,alternativas:[`A prednisolona possui a mesma potência anti-inflamatória que a dexametasona.`,`A hidrocortisona é o corticosteroide de referência (potência = 1), e a dexametasona é aproximadamente 25-30 vezes mais potente como anti-inflamatório.`,`A prednisona é ativa por si só, sem necessidade de conversão hepática.`,`Todos os corticosteroides possuem a mesma atividade mineralocorticoide.`,`A metilprednisolona possui menor potência anti-inflamatória que a hidrocortisona.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Dexametasona é ~25-30x mais potente que hidrocortisona, enquanto prednisolona é ~4-5x.`,B:`Correto. Equivalências anti-inflamatórias: hidrocortisona 20 mg = prednisolona 5 mg = dexametasona 0,75 mg.`,C:`Prednisona é um pró-fármaco que precisa ser convertida em prednisolona no fígado para ser ativa.`,D:`Corticosteroides variam em atividade mineralocorticoide: hidrocortisona > prednisolona > dexametasona (quase zero).`,E:`Metilprednisolona é ~5x mais potente que hidrocortisona, sendo mais potente.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015}]},{id:`farm-058`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`analgesicos`,subtopico:`Opioides`,dificuldade:`dificil`,enunciado:`A buprenorfina é um opioide agonista parcial μ amplamente utilizado em medicina veterinária. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`A buprenorfina é um agonista pleno μ com curta duração de ação (1-2h).`,`A buprenorfina possui alta afinidade pelo receptor μ, com dissociação lenta, resultando em longa duração de ação (6-12h) e efeito teto (ceiling effect) para depressão respiratória.`,`A buprenorfina é contraindicada em gatos por causar excitação paradoxal.`,`A naloxana não reverte os efeitos da buprenorfina por ser um agonista parcial.`,`A buprenorfina é mais potente que a morfina em doses equivalentes.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Buprenorfina é agonista PARCIAL μ (não pleno), com longa duração de ação (6-12h).`,B:`Correto. Buprenorfina tem alta afinidade pelo receptor μ, com cinética de dissociação lenta. Isso confere longa duração e ceiling effect para depressão respiratória (plateau acima de certa dose).`,C:`Buprenorfina é amplamente utilizada em gatos (0,01-0,02 mg/kg), sendo um dos opioides mais usados nessa espécie.`,D:`Naloxana PODE reverter buprenorfina, mas são necessárias doses maiores e repetidas devido à alta afinidade.`,E:`Buprenorfina é ~25-50x mais potente que morfina por via parenteral, mas como agonista parcial, seu efeito máximo é inferior.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Steagall PVM, et al.`,titulo:`Buprenorfine in cats`,journal:`J Feline Med Surg`,ano:2019}]},{id:`farm-059`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Veterinário Prefeitura SP 2021`,tipo:`concurso`,topico:`analgesicos`,subtopico:`Opioides`,dificuldade:`medio`,enunciado:`O tramadol é um opioide atípico utilizado para dor moderada a moderadamente intensa em pequenos animais. Sobre sua farmacologia, assinale a alternativa INCORRETA:`,alternativas:[`O tramadol e seu metabólito ativo (O-desmetiltramadol) agonizam receptores opioides μ.`,`O tramadol inibe a recaptação de serotonina e noradrenalina, contribuindo para analgesia descendente inibitória.`,`O tramadol é seguro em pacientes epilépticos, não alterando o limiar convulsivo.`,`O tramadol pode causar efeitos colaterais gastrointestinais (náusea, vômito) em cães.`,`A eficácia do tramadol é variável entre espécies devido a diferenças no metabolismo hepático.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Correto. O-desmetiltramadol (M1) é o metabólito ativo com afinidade μ. A produção de M1 varia entre espécies.`,B:`Correto. A inibição de recaptação de 5-HT e NE ativa vias descendentes inibitórias de dor.`,C:`INCORRETO. Tramadol pode reduzir o limiar convulsivo por seus efeitos serotoninérgicos e noradrenérgicos, devendo ser usado com cautela em epilépticos.`,D:`Correto. Náusea e vômito são efeitos adversos comuns, semelhantes a outros opioides.`,E:`Correto. Gatos produzem menos metabólito M1 que cães, resultando em eficácia variável.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`KuKanich B, Papich MG`,titulo:`Pharmacokinetics of tramadol in dogs`,journal:`J Vet Pharmacol Ther`,ano:2004}]},{id:`farm-060`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`analgesicos`,subtopico:`Alfa-2 agonistas`,dificuldade:`medio`,enunciado:`A dexmedetomidina é um agonista alfa-2 adrenérgico altamente seletivo, utilizado para sedação e analgesia. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`A dexmedetomidina possui seletividade alfa-2/alfa-1 semelhante à xilazina.`,`A dexmedetomidina pode ser revertida com atipamezol (Antisedan), um antagonista alfa-2 seletivo.`,`A dexmedetomidina não causa alterações cardiovasculares significativas.`,`A dexmedetomidina é contraindicada em cães por causar depressão respiratória grave.`,`A dexmedetomidina não possui efeito analgésico, atuando apenas como sedativo.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Dexmedetomidina é ~8x mais seletiva alfa-2/alfa-1 que xilazina (1620:1 vs 200:1).`,B:`Correto. Atipamezol é antagonista alfa-2 seletivo que reverte completamente os efeitos de dexmedetomidina e medetomidina em ~10-15 minutos.`,C:`Dexmedetomidina causa bradicardia significativa, redução do débito cardíaco e vasocon periférica.`,D:`Dexmedetomidina é amplamente utilizada em cães para sedação e pré-anestesia.`,E:`Dexmedetomidina possui efeito analgésico significativo via ativação de receptores alfa-2 no corno dorsal da medula espinhal.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Granholm M, et al.`,titulo:`Dexmedetomidine in dogs and cats`,journal:`J Vet Pharmacol Ther`,ano:2006}]},{id:`farm-061`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`analgesicos`,subtopico:`Paracetamol`,dificuldade:`facil`,enunciado:`O paracetamol (acetaminofeno) é um analgésico e antipirético amplamente utilizado em humanos, mas com toxicidade significativa em animais. Sobre seu uso em veterinária, assinale a alternativa CORRETA:`,alternativas:[`O paracetamol é seguro em gatos na mesma dose utilizada em cães.`,`O paracetamol é seguro em cães em doses de até 10-15 mg/kg, mas é extremamente tóxico em gatos mesmo em doses baixas, causando metemoglobinemia e necrose hepática.`,`O paracetamol não possui efeito analgésico em cães.`,`O antídoto para intoxicação por paracetamol em gatos é a naloxana.`,`O paracetamol é amplamente aprovado para uso veterinário em todas as espécies.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Paracetamol é EXTREMAMENTE TÓXICO em gatos (dose tóxica >10 mg/kg) por deficiência de glucuronosiltransferase.`,B:`Correto. Cães toleram 10-15 mg/kg com cautela. Gatos desenvolvem metemoglobinemia (hemácias oxidadas) e necrose hepática fulminante por acúmulo do metabólito tóxico NAPQI.`,C:`Paracetamol possui efeito analgésico e antipirético em cães, embora não seja o fármaco de primeira escolha.`,D:`O antídoto é N-acetilcisteína (NAC), que repleta glutationa e detoxifica NAPQI. Naloxana é para opioides.`,E:`Paracetamol NÃO é aprovado para uso veterinário no Brasil. É utilizado off-label com muita cautela.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Court MH, et al.`,titulo:`Acetaminophen toxicity in cats`,journal:`J Vet Pharmacol Ther`,ano:2001}]},{id:`farm-062`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`anestesicos`,subtopico:`Propofol`,dificuldade:`medio`,enunciado:`O propofol é um anestésico intravenoso de ação ultrarrápida amplamente utilizado em pequenos animais. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`O propofol é um barbitúrico de ação curta, pertencente ao grupo das hidantoínas.`,`O propofol causa excitação em gatos, sendo contraindicado nessa espécie.`,`O propofol ativa receptores GABA-A, causando depressão dose-dependente do SNC, com indução rápida (30-60 segundos) e recuperação suave.`,`O propofol não causa depressão cardiovascular, sendo seguro em pacientes hipotensos.`,`O propofol não é metabolizado pelo fígado, sendo excretado inalterado pelos rins.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Propofol é um fenol substituído (2,6-diisopropilfenol), NÃO um barbitúrico.`,B:`Propofol é amplamente utilizado em gatos, com recuperação suave. Pode causar mioclonia leve, não excitação.`,C:`Correto. Propofol potencializa receptores GABA-A, causando depressão do SNC. Indução rápida (30-60s IV), recuperação em 10-20 min (redistribuição).`,D:`Propofol causa depressão cardiovascular dose-dependente (vasodilatação, redução da contratilidade). Cautela em hipotensos.`,E:`Propofol é extensivamente metabolizado no fígado (glucuronidação), com metabólitos inativos excretados pelos rins.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Bufalari A, et al.`,titulo:`Propofol anesthesia in dogs and cats`,journal:`Vet Anaesth Analg`,ano:2007}]},{id:`farm-063`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário IBAMA 2022`,tipo:`concurso`,topico:`anestesicos`,subtopico:`Tiopental`,dificuldade:`dificil`,enunciado:`O tiopental é um barbitúrico ultracurto utilizado para indução anestésica. Sobre suas características, assinale a alternativa INCORRETA:`,alternativas:[`O tiopental é um ácido barbitúrico ultracurto que ativa receptores GABA-A, prolongando a abertura dos canais de cloreto.`,`O tiopental deve ser administrado lentamente por via IV para evitar apneia e hipotensão grave.`,`O tiopental é contraindicado em gatos por causar excitação paradoxal e recuperação prolongada.`,`O tiopental redistribui-se rapidamente do SNC para tecidos periféricos (músculo, gordura), o que explica o término do efeito após dose única.`,`O tiopental é seguro para administração perivascular, sem risco de necrose tecidual.`],resposta_correta:`E`,explicacoes_alternativas:{A:`Correto. Tiopental potencializa GABA-A, prolongando a abertura de canais de Cl⁻ e causando hiperpolarização neuronal.`,B:`Correto. Administração rápida causa depressão respiratória e cardiovascular acentuada.`,C:`Correto. Tiopental causa excitação e recuperação prolongada em gatos (acúmulo em gordura). Propofol é preferido.`,D:`Correto. O efeito termina por redistribuição (SNC → músculo → gordura), não por metabolismo.`,E:`INCORRETO. Tiopental é altamente ALCALINO (pH ~10-11) e causa NECROSE SEVERA se extravasar. Deve ser administrado estritamente por via IV.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Thurmon JC, et al.`,titulo:`Lumb & Jones' Veterinary Anesthesia and Analgesia`,ano:2015}]},{id:`farm-064`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário CETESB 2022`,tipo:`concurso`,topico:`anestesicos`,subtopico:`Isoflurano`,dificuldade:`facil`,enunciado:`O isoflurano é o anestésico inalatório mais utilizado em medicina veterinária. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`O isoflurano é metabolizado extensivamente pelo fígado, resultando em metabólitos hepatotóxicos.`,`O isoflurano possui coeficiente de partição sangue/gas de 1,46, com início de ação intermediário e recuperação moderada.`,`O isoflurano não causa depressão cardiovascular, sendo seguro em pacientes com cardiopatias.`,`O isoflurano é contraindicado em equinos por causar miopatias graves.`,`O MAC (Concentração Alveolar Mínima) do isoflurano é igual em todas as espécies.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Isoflurano é pouco metabolizado (<0,2%), sendo eliminado quase totalmente pelos pulmões. Seguro para fígado.`,B:`Correto. Coeficiente sangue/gas 1,46 confere velocidade intermediária. Sevoflurano (0,69) é mais rápido.`,C:`Isoflurano causa depressão cardiovascular dose-dependente (vasodilatação periférica, redução do DC).`,D:`Isoflurano é amplamente utilizado em equinos para anestesia geral.`,E:`MAC varia entre espécies: cão ~1,3%, gato ~1,6%, equino ~1,3%, bovino ~1,3%.`},referencias:[{autores:`Thurmon JC, et al.`,titulo:`Lumb & Jones' Veterinary Anesthesia and Analgesia`,ano:2015},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-065`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`anestesicos`,subtopico:`Lidocaína`,dificuldade:`medio`,enunciado:`A lidocaína é um anestésico local do tipo amida, amplamente utilizado em bloqueios nervosos e anestesia local. Sobre sua farmacologia, assinale a alternativa CORRETA:`,alternativas:[`A lidocaína é um éster, sendo metabolizada por pseudocolinesterases plasmáticas.`,`A lidocaína bloqueia os canais de sódio voltagem-dependentes, impedindo a geração e condução do potencial de ação em fibras nervosas.`,`A lidocaína possui baixa biodisponibilidade oral, não sendo utilizada por via sistêmica.`,`A lidocaína é contraindicada em felinos por causar toxicidade grave.`,`A lidocaína não possui efeito antiarrítmico, sendo utilizada exclusivamente como anestésico local.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Lidocaína é do tipo AMIDA (não éster), metabolizada no fígado por CYP1A2 e CYP3A4.`,B:`Correto. A lidocaína bloqueia canais de Na⁺ voltagem-dependentes na forma inativa, impedindo a despolarização e condução do impulso nervoso.`,C:`Lidocaína possui ~3% de biodisponibilidade oral (primeira passagem), mas é usada IV como antiarrítmico e analgésico sistêmico.`,D:`Lidocaína pode ser utilizada em felinos com cautela (dose reduzida), não sendo absolutamente contraindicada.`,E:`Lidocaína é antiarrítmico classe IB, sendo utilizada IV para arritmias ventriculares em cães.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Thurmon JC, et al.`,titulo:`Lumb & Jones' Veterinary Anesthesia and Analgesia`,ano:2015}]},{id:`farm-066`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Veterinário Prefeitura RJ 2023`,tipo:`concurso`,topico:`anestesicos`,subtopico:`Sevoflurano`,dificuldade:`medio`,enunciado:`O sevoflurano é o anestésico inalatório preferido para indução por máscara em pequenos animais. Sobre suas vantagens em relação ao isoflurano, assinale a alternativa CORRETA:`,alternativas:[`O sevoflurano é mais pungente que o isoflurano, causando mais tosse e broncoespasmo na indução.`,`O sevoflurano possui coeficiente de partição sangue/gas mais baixo (0,69) que o isoflurano (1,46), resultando em indução e recuperação mais rápidas.`,`O sevoflurano é mais potente que o isoflurano, necessitando de menor concentração inspirada.`,`O sevoflurano não causa depressão cardiovascular, sendo superior ao isoflurano nesse aspecto.`,`O sevoflurano é contraindicado em cães braquicéfalos.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Sevoflurano é MENOS pungente que isoflurano, sendo ideal para indução por máscara.`,B:`Correto. Menor coeficiente sangue/gas = mais rápido início e recuperação. Sevoflurano (0,69) é ~2x mais rápido que isoflurano (1,46).`,C:`Sevoflurano é MENOS potente (MAC ~2,3% cão) que isoflurano (MAC ~1,3%), necessitando MAIOR concentração inspirada.`,D:`Ambos causam depressão cardiovascular semelhante. Sevoflurano não é significativamente superior nesse aspecto.`,E:`Sevoflurano é frequentemente PREFERIDO em braquicéfalos pela indução suave por máscara.`},referencias:[{autores:`Thurmon JC, et al.`,titulo:`Lumb & Jones' Veterinary Anesthesia and Analgesia`,ano:2015},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-067`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`antiparasitarios`,subtopico:`Benzimidazóis`,dificuldade:`medio`,enunciado:`O albendazol e o fenbendazol são benzimidazóis amplamente utilizados em parasitologia veterinária. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`Os benzimidazóis possuem índice terapêutico baixo, sendo altamente tóxicos em doses terapêuticas.`,`O albendazol é teratogênico e embriotóxico, sendo contraindicado em fêmeas gestantes de todas as espécies.`,`Os benzimidazóis são eficazes apenas contra nematódes (vermes redondos), não possuindo atividade contra cestódes.`,`O fenbendazol é altamente tóxico em cães, sendo contraindicado nessa espécie.`,`Os benzimidazóis atuam bloqueando canais de cálcio musculares do parasita.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Benzimidazóis possuem IT ALTO em mamíferos (tubulina de mamíferos tem baixa afinidade).`,B:`Correto. Albendazol é teratogênico (inibe a polimerização de microtúbulos em células em divisão), sendo contraindicado em gestantes. Fenbendazol é mais seguro nesse aspecto.`,C:`Benzimidazóis possuem atividade contra NEMATÓDES e CESTÓDES (albendazol é eficaz contra Echinococcus).`,D:`Fenbendazol é seguro em cães, sendo amplamente utilizado (Panacur).`,E:`Benzimidazóis ligam-se à TUBULINA (não canais de cálcio), inibindo a polimerização de microtúbulos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Bowman DD`,titulo:`Georgis' Parasitology for Veterinarians`,ano:2021}]},{id:`farm-068`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`antiparasitarios`,subtopico:`Praziquantel`,dificuldade:`facil`,enunciado:`O praziquantel é o fármaco de escolha para tratamento de cestódes (vermes chatos) em cães e gatos. Sobre seu mecanismo de ação, assinale a alternativa CORRETA:`,alternativas:[`O praziquantel inibe a síntese de ácido fólico do cestódeo.`,`O praziquantel causa espasticidade e paralisia do cestódeo por aumento da permeabilidade da membrana aos íons cálcio, resultando em contração muscular e desprendimento do parasita.`,`O praziquantel atua inibindo a enzima colinesterase do parasita.`,`O praziquantel é eficaz apenas contra formas larvárias, não contra parasitas adultos.`,`O praziquantel é contraindicado em gatos por causar toxicidade hepática.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Inibição do ácido fólico é mecanismo de sulfonamidas/trimetoprima, não de praziquantel.`,B:`Correto. Praziquantel aumenta a permeabilidade da tegumento do cestódeo ao Ca²⁺, causando contração espástica, vacuolização do tegumento e desprendimento das escólex.`,C:`Inibição de colinesterase é mecanismo de organofosforados/carbamatos.`,D:`Praziquantel é eficaz contra parasitas ADULTOS (cestódes), sendo o fármaco de escolha.`,E:`Praziquantel é seguro em gatos, sendo amplamente utilizado (Droncit).`},referencias:[{autores:`Bowman DD`,titulo:`Georgis' Parasitology for Veterinarians`,ano:2021},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-069`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário CETESB 2020`,tipo:`concurso`,topico:`antiparasitarios`,subtopico:`Nitroscanato`,dificuldade:`medio`,enunciado:`O nitroscanato é um antiparasitário utilizado exclusivamente em cães para tratamento de cestódes e nematódes. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`O nitroscanato é amplamente utilizado em bovinos e equinos para controle de parasitas gastrointestinais.`,`O nitroscanato não possui efeitos adversos significativos em cães.`,`O nitroscanato é contraindicado em cães com menos de 6 meses de idade por causar vômito e diarreia graves.`,`O nitroscanato é eficaz contra Dirofilaria immitis (verme do coração).`,`O nitroscanato atua inibindo a fumarato redutase do parasita, além de causar desprendimento do tegumento dos cestódes.`],resposta_correta:`E`,explicacoes_alternativas:{A:`Nitroscanato é utilizado exclusivamente em CÃES (Lopatol), não em bovinos ou equinos.`,B:`Nitroscanato pode causar vômito e diarreia em cães, especialmente em altas doses.`,C:`Nitroscanato é utilizado em cães a partir de 3 meses de idade (não 6 meses).`,D:`Nitroscanato não é eficaz contra Dirofilaria. Ivermectina/milbemicina são utilizadas para profilaxia.`,E:`Correto. Nitroscanato inibe a fumarato redutase (metabolismo energético) e desorganiza o tegumento dos cestódes, sendo eficaz contra Dipylidium, Taenia e Echinococcus.`},referencias:[{autores:`Bowman DD`,titulo:`Georgis' Parasitology for Veterinarians`,ano:2021},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-070`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`antiparasitarios`,subtopico:`Milbemicina`,dificuldade:`dificil`,enunciado:`A milbemicina oxima é um endectocida da classe das lactonas macrocíclicas, utilizado para profilaxia de Dirofilaria immitis em cães. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`A milbemicina oxima e a ivermectina possuem o mesmo mecanismo de ação, potencializando canais de cloreto mediados por glutamato.`,`A milbemicina oxima não possui atividade contra nematódes gastrointestinais, atuando exclusivamente contra Dirofilaria.`,`A milbemicina oxima é contraindicada em cães com mutação MDR1 (Collie, Pastor-branco).`,`A milbemicina oxima não pode ser associada a outros antiparasitários.`,`A dose profilática de milbemicina para Dirofilaria é de 1 mg/kg/dia.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Ambas potencializam canais de cloreto mediados por glutamato (GluCl) em invertebrados. A milbemicina tem perfil de segurança semelhante, mas é comercializada em doses mais baixas.`,B:`Milbemicina é eficaz contra nematódes gastrointestinais (Ancylostoma, Toxocara, Trichuris) além de Dirofilaria.`,C:`Milbemicina em doses profiláticas é segura em cães MDR1, pois as concentrações atingidas são insuficientes para causar neurotoxicidade.`,D:`Milbemicina é frequentemente associada a praziquantel (Milbemax) para cobertura de cestódes e nematódes.`,E:`A dose profilática é 0,5 mg/kg via oral, administrada mensalmente (não diária).`},referencias:[{autores:`Bowman DD`,titulo:`Georgis' Parasitology for Veterinarians`,ano:2021},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-071`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`cardiovasculares`,subtopico:`Diuréticos`,dificuldade:`medio`,enunciado:`A espironolactona é um diurético poupador de potássio utilizado em cardiologia veterinária. Sobre seu mecanismo de ação, assinale a alternativa CORRETA:`,alternativas:[`A espironolactona inibe o cotransportador Na⁺/K⁺/2Cl⁻ na alça ascendente de Henle.`,`A espironolactona é um antagonista competitivo dos receptores de aldosterona nos túbulos coletores, promovendo excreção de sódio e retenção de potássio.`,`A espironolactona atua inibindo a anidrase carbônica nos túbulos proximais.`,`A espironolactona é contraindicada em pacientes com insuficiência cardíaca congestiva.`,`A espironolactona não possui efeitos anti-inflamatórios ou anti-fibróticos.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Inibição de NKCC2 é mecanismo da FUROSEMIDA (diurético de alça).`,B:`Correto. Espironolactona bloqueia receptores mineralocorticoides (aldosterona) no túbulo coletor cortical, reduzindo a reabsorção de Na⁺ e a secreção de K⁺. Em IC, reduz a fibrose miocárdica.`,C:`Inibição de anidrase carbônica é mecanismo da acetazolamida.`,D:`Espironolactona é INDICADA em IC por seus efeitos anti-aldosterona (RALES trial em humanos).`,E:`Espironolactona possui efeitos anti-fibróticos e anti-inflamatórios significativos no miocárdio, independentes do efeito diurético.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Kittleson MD, Kienle RD`,titulo:`Small Animal Cardiovascular Medicine`,ano:1998}]},{id:`farm-072`,banca:`CESPE`,ano:2020,prova:`CESPE — Médico Veterinário MAPA 2020`,tipo:`concurso`,topico:`cardiovasculares`,subtopico:`Antiarrítmicos`,dificuldade:`dificil`,enunciado:`Os antiarrítmicos são classificados segundo Vaughan-Williams em classes I-IV. Sobre essa classificação, assinale a alternativa CORRETA:`,alternativas:[`Classe I (bloqueadores de canais de Na⁺): inclui lidocaína (IB) e amiodarona (IC).`,`Classe II (betabloqueadores): inclui propranolol e atenolol, que reduzem a frequência cardíaca por bloqueio de receptores β1.`,`Classe III (bloqueadores de canais de K⁺): inclui propranolol e metoprolol.`,`Classe IV (bloqueadores de canais de Ca²⁺): inclui lidocaína e flecainida.`,`A amiodarona pertence exclusivamente à classe III, sem atividade em outras classes.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Amiodarona é classe III (bloqueador de K⁺), embora possua propriedades de múltiplas classes. Lidocaína é classe IB.`,B:`Correto. Betabloqueadores (classe II) bloqueiam receptores β1 cardíacos, reduzindo FC, contratilidade e automaticidade. Propranolol (não seletivo) e atenolol (β1 seletivo) são exemplos.`,C:`Propranolol e metoprolol são classe II (betabloqueadores). Classe III inclui amiodarona, sotalol.`,D:`Lidocaína é classe IB (Na⁺). Flecainida é classe IC (Na⁺). Classe IV inclui verapamil e diltiazem (Ca²⁺).`,E:`Amiodarona tem atividade multi-classe: I (Na⁺), II (β-bloqueio), III (K⁺), IV (Ca²⁺).`},referencias:[{autores:`Kittleson MD, Kienle RD`,titulo:`Small Animal Cardiovascular Medicine`,ano:1998},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-073`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Residência Clínica Pequenos Animais 2023`,tipo:`residencia`,topico:`cardiovasculares`,subtopico:`Vasodilatadores`,dificuldade:`medio`,enunciado:`Os vasodilatadores são utilizados no tratamento de insuficiência cardíaca congestiva (ICC). Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`O benazepril e o enalapril são inibidores da enzima conversora de angiotensina (ECA), reduzindo a pré-carga e pós-carga em pacientes com ICC.`,`Os inibidores da ECA não possuem efeitos adversos em cães e gatos.`,`O pimobendan é um vasodilatador exclusivo, sem efeito inotrópico positivo.`,`A hidralazina é um inibidor da ECA utilizado para redução de pós-carga.`,`Os vasodilatadores são contraindicados em todas as formas de ICC.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. IECA (enalapril, benazepril) inibem a conversão de angiotensina I em angiotensina II, reduzindo vasoconstricção (pós-carga) e secreção de aldosterona (retenção de Na⁺, pré-carga).`,B:`IECA podem causar hipotazemia, hiperpotassemia e insuficiência renal aguda (especialmente em estenose renal).`,C:`Pimobendan (Vetmedin) é inodilatador: inotrópico positivo (sensibilização ao Ca²⁺) + vasodilatador (inibição de PDE3).`,D:`Hidralazina é vasodilatador direto (não é IECA). Atua na musculatura lisa arteriolar.`,E:`Vasodilatadores são FUNDAMENTAIS no tratamento de ICC (redução de pré e pós-carga).`},referencias:[{autores:`Kittleson MD, Kienle RD`,titulo:`Small Animal Cardiovascular Medicine`,ano:1998},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-074`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`cardiovasculares`,subtopico:`Digitálicos`,dificuldade:`dificil`,enunciado:`A intoxicação por digoxina é uma emergência clínica em veterinária. Sobre os sinais de toxicidade e tratamento, assinale a alternativa CORRETA:`,alternativas:[`Os sinais de intoxicação por digoxina incluem apenas taquicardia e hipertensão.`,`Os sinais de intoxicação por digoxina incluem anorexia, vômito, diarreia, bradicardia, arritmias (bloqueio AV, taquicardia ventricular) e alterações visuais. A dosagem sérica de digoxina deve ser mantida entre 0,8-2 ng/mL em cães.`,`O antídoto para intoxicação por digoxina é a atropina.`,`A intoxicação por digoxina não pode ser potencializada por hipopotassemia.`,`A digoxina é eliminada exclusivamente pelo fígado, não sendo afetada por insuficiência renal.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Intoxicação por digoxina causa BRADICARDIA (não taquicardia), além de anorexia, vômito e arritmias.`,B:`Correto. Os sinais GI (anorexia, vômito, diarreia) são os primeiros. Bradicardia, arritmias (bloqueio AV, TV) e alterações visuais (humanos) são mais graves. Janela terapêutica: 0,8-2 ng/mL.`,C:`Atropina é para bradicardia sintomática. O antídoto específico é o DIGOXINA IMUNE FAB (Digibind), que liga e neutraliza digoxina.`,D:`Hipopotassemia POTENCIALIZA a toxicidade da digoxina, pois K⁺ compete com digoxina pela Na⁺/K⁺-ATPase.`,E:`Digoxina é eliminada predominantemente pelos RINS (60-80% inalterada), sendo essencial ajuste na insuficiência renal.`},referencias:[{autores:`Kittleson MD, Kienle RD`,titulo:`Small Animal Cardiovascular Medicine`,ano:1998},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-075`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`respiratorios`,subtopico:`Broncodilatadores`,dificuldade:`medio`,enunciado:`Os broncodilatadores são fundamentais no tratamento de doenças respiratórias obstrutivas em pequenos animais. Sobre o uso de teofilina e aminofilina, assinale a alternativa CORRETA:`,alternativas:[`A teofilina atua exclusivamente como antagonista de receptores de adenosina, sem efeito sobre a fosfodiesterase.`,`A teofilina e a aminofilina inibem a fosfodiesterase (PDE), aumentando o AMPc intracelular e causando relaxamento do músculo liso brônquico.`,`A teofilina não possui efeitos adversos significativos, sendo segura em altas doses.`,`A aminofilina é a forma pura de teofilina, sem adição de etilenodiamina.`,`A teofilina não é metabolizada pelo fígado, sendo excretada inalterada pelos rins.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Teofilina tem múltiplos mecanismos: inibição de PDE, antagonismo de adenosina e liberação de catecolaminas.`,B:`Correto. A inibição de PDE aumenta o AMPc → ativação de proteína quinase A → relaxamento do músculo liso brônquico. Aminofilina = teofilina + etilenodiamina (mais solúvel).`,C:`Teofilina possui IT baixo: causa taquicardia, vômito, convulsões em altas doses.`,D:`Aminofilina é teofilina + etilenodiamina (80% teofilina, 20% etilenodiamina).`,E:`Teofilina é extensivamente metabolizada no fígado por CYP1A2.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Padrid P`,titulo:`Canine and feline asthma`,journal:`Vet Clin North Am Small Anim Pract`,ano:2019}]},{id:`farm-076`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura RJ 2022`,tipo:`concurso`,topico:`respiratorios`,subtopico:`Mucolíticos`,dificuldade:`facil`,enunciado:`A acetilcisteína é um mucolítico e antídoto amplamente utilizado em medicina veterinária. Sobre suas ações, assinale a alternativa CORRETA:`,alternativas:[`A acetilcisteína atua como mucolítico por romper as ligações dissulfeto das glicoproteínas do muco, reduzindo sua viscosidade.`,`A acetilcisteína não possui ação como antídoto em intoxicações por paracetamol.`,`A acetilcisteína é contraindicada em gatos por causar broncoespasmo grave.`,`A acetilcisteína atua como oxidante, aumentando a produção de radicais livres.`,`A acetilcisteína não é eficaz por via inalatória, devendo ser administrada apenas por via oral.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. O grupamento tiol (-SH) da acetilcisteína reduz as ligações dissulfeto (-S-S-) das glicoproteínas do muco, fragmentando-as e reduzindo a viscosidade.`,B:`Acetilcisteína (NAC) é o antídoto de escolha para intoxicação por paracetamol, repleta glutationa.`,C:`Acetilcisteína é utilizada em gatos, embora com cautela por possível irritação das vias aéreas.`,D:`Acetilcisteína é ANTIOXIDANTE (precursora de glutationa), não oxidante.`,E:`Acetilcisteína pode ser administrada por via inalatória (nebulização), oral e IV.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Padrid P`,titulo:`Canine and feline asthma`,journal:`Vet Clin North Am Small Anim Pract`,ano:2019}]},{id:`farm-077`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`respiratorios`,subtopico:`Broncodilatadores`,dificuldade:`medio`,enunciado:`O butorfanol é utilizado como antitussígeno em cães. Sobre seu mecanismo de ação, assinale a alternativa CORRETA:`,alternativas:[`O butorfanol atua como antitussígeno por inibição direta da tosse no centro da tosse no bulbo, sendo agonista κ e antagonista μ.`,`O butorfanol é um agonista pleno μ, sendo contraindicado como antitussígeno.`,`O butorfanol não possui efeitos adversos, sendo seguro em altas doses.`,`O butorfanol é contraindicado em cães por causar depressão respiratória grave.`,`O butorfanol não pode ser utilizado em associação com outros opioides.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Butorfanol suprime o reflexo da tosse por ação central (centro da tosse no bulbo). É agonista κ (analgesia) e antagonista μ (reverte efeitos de morfina).`,B:`Butorfanol é agonista PARCIAL μ e agonista κ, não agonista pleno μ.`,C:`Butorfanol causa depressão respiratória dose-dependente, sedação e, em altas doses, excitação.`,D:`Butorfanol é amplamente utilizado em cães como antitussígeno e analgésico leve.`,E:`Butorfanol pode ser associado a agonistas plenos μ (morfina, fentanil), mas pode antagonizar seus efeitos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Padrid P`,titulo:`Canine and feline asthma`,journal:`Vet Clin North Am Small Anim Pract`,ano:2019}]},{id:`farm-078`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`respiratorios`,subtopico:`Antitussígenos`,dificuldade:`facil`,enunciado:`Sobre o uso de antitussígenos em medicina veterinária, assinale a alternativa CORRETA:`,alternativas:[`O dextrometorfano é um opioide pleno, sendo o antitussígeno mais potente disponível.`,`A codeína possui ação antitussígena por supressão do centro da tosse, além de efeito analgésico, sendo utilizada em cães com cautela.`,`Os antitussígenos devem ser utilizados em todos os casos de tosse, inclusive quando há secreção pulmonar ativa.`,`O dextrometorfano não possui efeitos adversos em nenhuma espécie.`,`A codeína não é metabolizada em morfina no organismo.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Dextrometorfano NÃO é opioide — é derivado da morfina sem atividade opioide significativa. Atua no centro da tosse.`,B:`Correto. Codeína (0,5-1 mg/kg VO) suprime o centro da tosse e possui efeito analgésico. É metabolizada parcialmente em morfina. Usar com cautela em cães.`,C:`Antitussígenos são CONTRAINDICADOS quando há secreção ativa, pois suprimem o mecanismo de clearance mucociliar.`,D:`Dextrometorfano pode causar sedação, ataxia e, raramente, excitação em cães.`,E:`Codeína é metabolizada em morfina e norcodeína no fígado, contribuindo para seus efeitos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Padrid P`,titulo:`Canine and feline asthma`,journal:`Vet Clin North Am Small Anim Pract`,ano:2019}]},{id:`farm-079`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`gastrointestinais`,subtopico:`Procinéticos`,dificuldade:`medio`,enunciado:`A metoclopramida é um procinético e antiemético amplamente utilizado em pequenos animais. Sobre seu mecanismo de ação, assinale a alternativa CORRETA:`,alternativas:[`A metoclopramida atua como antagonista de receptores 5-HT3 na zona gatilho quimiorreceptora.`,`A metoclopramida é antagonista de receptores D2 no centro do vômito e na ZGCR, além de possuir efeito procinético por aumentar a liberação de acetilcolina no plexo mioentérico.`,`A metoclopramida não atravessa a barreira hematoencefálica, não possuindo efeitos centrais.`,`A metoclopramida é contraindicada em cães por causar hepatotoxicidade grave.`,`A metoclopramida não pode ser utilizada em associação com opioides.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Antagonismo 5-HT3 é mecanismo de ondansetrona e granisetrona, não de metoclopramida.`,B:`Correto. Metoclopramida antagoniza D2 no centro do vômito e ZGCR, e aumenta a motilidade gástrica por facilitar a liberação de ACh no plexo mioentérico.`,C:`Metoclopramida ATRAVESSA a BHE, podendo causar efeitos extrapiramidais (inquietação, tremores).`,D:`Metoclopramida não é hepatotóxica. Efeitos adversos incluem sedação e efeitos extrapiramidais.`,E:`Metoclopramida pode ser associada a opioides, mas o efeito antiemético pode ser antagonizado pelos opioides.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Washabau RJ, Day MJ`,titulo:`Canine and Feline Gastroenterology`,ano:2013}]},{id:`farm-080`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Veterinário Prefeitura SP 2021`,tipo:`concurso`,topico:`gastrointestinais`,subtopico:`Antiácidos`,dificuldade:`facil`,enunciado:`Os antiácidos são fármacos que neutralizam o ácido gástrico ou reduzem sua secreção. Sobre seu uso em veterinária, assinale a alternativa CORRETA:`,alternativas:[`O omeprazol é um antiácido que neutraliza diretamente o ácido gástrico no lúmen.`,`O omeprazol é um inibidor da bomba de prótons (H⁺/K⁺-ATPase), reduzindo a secreção ácida gástrica por até 24 horas.`,`O omeprazol não é eficaz em cães e gatos por não inibir a bomba de prótons nessas espécies.`,`A ranitidina é um inibidor da bomba de prótons mais potente que o omeprazol.`,`Os antiácidos (hidróxido de alumínio) devem ser administrados junto com outros fármacos para melhorar sua absorção.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Omeprazol não neutraliza ácido — inibe a produção de ácido na bomba de prótons. Antiácidos (Mg, Al) neutralizam.`,B:`Correto. Omeprazol inibe irreversivelmente a H⁺/K⁺-ATPase parietal, reduzindo a secreção ácida basal e estimulada por até 24h. É seguro em cães e gatos.`,C:`Omeprazol é eficaz em cães e gatos, sendo o gastroprotetor de primeira escolha.`,D:`Ranitidina é antagonista de H2 (não inibidor de bomba de prótons). Foi descontinuada por impurezas de NDMA.`,E:`Antiácidos de alumínio e magnésio podem adsorver outros fármacos, REDUZINDO sua absorção. Devem ser administrados separadamente.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Washabau RJ, Day MJ`,titulo:`Canine and Feline Gastroenterology`,ano:2013}]},{id:`farm-081`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`gastrointestinais`,subtopico:`Laxantes`,dificuldade:`medio`,enunciado:`Os laxantes são utilizados para tratamento de constipação intestinal em pequenos animais. Sobre a classificação e uso, assinale a alternativa CORRETA:`,alternativas:[`O lactulose é um laxante osmótico que é fermentado no cólon, produzindo ácidos orgânicos que atraem água para o lúmen intestinal.`,`O lactulose não pode ser utilizado em gatos por causar toxicidade hepática.`,`Os laxantes estimulantes (bisacodilo) devem ser utilizados como primeira escolha para constipação crônica.`,`O óleo mineral é seguro para administração oral em todas as espécies, sem risco de aspiração.`,`O metilcelulose é um laxante osmótico que não requer ingestão de água adequada.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Lactulose é dissacarídeo sintético não absorvido, fermentado no cólon em ácidos orgânicos (lático, acético) que reduzem pH e atraem água osmoticamente.`,B:`Lactulose é seguro em gatos (0,5 mL/kg VO) e é utilizado para constipação e encefalopatia hepática.`,C:`Laxantes estimulantes causam dependência e hipomotilidade com uso crônico. Deve-se preferir laxantes formadores de massa ou osmóticos.`,D:`Óleo mineral pode causar pneumonia lipoaspiratória se aspirado, sendo contraindicado em pacientes com megaesôfago.`,E:`Metilcelulose é laxante FORMADOR DE MASSA (não osmótico), requerendo ingestão adequada de água.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Washabau RJ, Day MJ`,titulo:`Canine and Feline Gastroenterology`,ano:2013}]},{id:`farm-082`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`gastrointestinais`,subtopico:`Antieméticos`,dificuldade:`dificil`,enunciado:`Sobre a farmacologia comparada dos antieméticos em cães e gatos, assinale a alternativa CORRETA:`,alternativas:[`O maropitant (Cerenia) é eficaz apenas contra vômito de origem central, não atuando em aferências viscerais.`,`O ondansetrona antagoniza receptores 5-HT3 na ZGCR e em aferências vagais, sendo eficaz para vômito por quimioterapia e pós-operatório.`,`A metoclopramida é o antiemético de primeira escolha para vômito agudo em gatos.`,`O maropitant não pode ser utilizado em gatos por causar efeitos adversos graves.`,`O ondansetrona e o maropitant possuem o mesmo mecanismo de ação.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Maropitant atua no centro do vômito, ZGCR E em aferências viscerais (antagonista NK1).`,B:`Correto. Ondansetrona antagoniza 5-HT3 em ZGCR e aferências vagais, sendo eficaz para vômito induzido por quimioterápicos (cisplatina) e pós-operatório.`,C:`Maropitant é mais recomendado como primeira escolha. Metoclopramida pode causar efeitos extrapiramidais.`,D:`Maropitant é utilizado off-label em gatos com segurança (1 mg/kg SC).`,E:`Mecanismos diferentes: maropitant (NK1) vs ondansetrona (5-HT3).`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Washabau RJ, Day MJ`,titulo:`Canine and Feline Gastroenterology`,ano:2013}]},{id:`farm-083`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`endocrinos`,subtopico:`Insulina`,dificuldade:`dificil`,enunciado:`O manejo do diabetes mellitus em gatos difere significativamente do manejo em cães. Sobre a insulinoterapia felina, assinale a alternativa CORRETA:`,alternativas:[`A insulina NPH é a de primeira escolha para diabetes felino, com excelente controle glicêmico.`,`A insulina glargina (Lantus) e a insulina detemir (Levemir) são preferidas em gatos por apresentarem maior chance de remissão diabética quando utilizadas precocemente com protocolo de alimentação low-carb.`,`Os gatos não desenvolvem cetoacidose diabética, sendo desnecessário o monitoramento de corpos cetônicos.`,`A insulina regular é ideal para manutenção do diabetes felino por sua longa duração de ação.`,`A resistência à insulina não ocorre em gatos, sendo todos os casos de diabetes mellitus tipo I.`],resposta_correta:`B`,explicacoes_alternativas:{A:`NPH tem duração muito curta em gatos (4-8h), com pico abrupto. Glargina/detemir têm perfil mais adequado.`,B:`Correto. Glargina e detemir, associadas a dieta low-carb, oferecem maior taxa de remissão diabética em gatos (até 50% nos primeiros 6 meses).`,C:`Gatos podem desenvolver cetoacidose, embora menos frequentemente que cães.`,D:`Insulina regular é de ação CURTA (4-6h), usada para crises (cetoacidose), não para manutenção.`,E:`Muitos gatos apresentam diabetes tipo II (resistência à insulina), associado à obesidade.`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-084`,banca:`CESPE`,ano:2023,prova:`CESPE — Médico Veterinário MAPA 2023`,tipo:`concurso`,topico:`endocrinos`,subtopico:`Corticosteroides`,dificuldade:`medio`,enunciado:`Os corticosteroides exógenos podem causar supressão do eixo hipotálamo-hipófise-adrenal (HHA). Sobre esse efeito, assinale a alternativa CORRETA:`,alternativas:[`A supressão do eixo HHA ocorre apenas com corticosteroides tópicos, não com sistêmicos.`,`A supressão do eixo HHA é mais provável com uso prolongado (>2-4 semanas) de corticosteroides de ação longa (dexametasona, triancinolona) e pode causar insuficiência adrenal aguda na suspensão abrupta.`,`A prednisolona em doses alternadas (dia sim, dia não) não causa supressão do eixo HHA.`,`O teste de estímulo com ACTH não é útil para avaliar a função adrenal.`,`A supressão do eixo HHA é reversível imediatamente após a suspensão do corticosteroide.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Corticosteroides sistêmicos, tópicos potentes (betametasona) e até inalatórios podem suprimir o eixo HHA.`,B:`Correto. Uso prolongado de corticosteroides suprime CRH e ACTH endógenos, causando atrofia adrenal. Suspensão abrupta → crise addisoniana. Retirada gradual é obrigatória.`,C:`Doses alternadas reduzem mas NÃO eliminam a supressão do eixo HHA.`,D:`O teste de estímulo com ACTH (ACTH stimulation test) é o padrão-ouro para avaliar função adrenal.`,E:`A recuperação do eixo HHA pode levar SEMANAS a MESES após a suspensão, não sendo imediata.`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-085`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Residência Clínica Pequenos Animais 2022`,tipo:`residencia`,topico:`endocrinos`,subtopico:`Hormônios tireoidianos`,dificuldade:`medio`,enunciado:`O hipotireoidismo é a endocrinopatia mais comum em cães. Sobre a reposição hormonal, assinale a alternativa CORRETA:`,alternativas:[`A levotiroxina (T4 sintética) é o fármaco de escolha para reposição tireoidiana em cães, sendo convertida perifericamente em T3 ativa.`,`O liothyronine (T3 sintético) é preferido sobre a levotiroxina por possuir meia-vida mais longa.`,`A dose de levotiroxina é a mesma para todos os cães, independentemente do peso.`,`O hipotireoidismo é mais comum em gatos que em cães.`,`A levotiroxina não necessita de monitoramento laboratorial após o início da terapia.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Levotiroxina (T4) é o tratamento de escolha. É convertida em T3 nos tecidos periféricos (fígado, rins) por desiodases, mimetizando a fisiologia normal.`,B:`T3 tem meia-vida CURTA (horas), causando picos e vales. T4 tem meia-vida mais longa (12-16h em cães).`,C:`A dose é ajustada por peso (0,01-0,02 mg/kg VO a cada 12-24h).`,D:`Hipotireoidismo é mais comum em CÃES que em gatos. Hipertireoidismo é mais comum em gatos.`,E:`Monitoramento de T4 sérica é necessário (4-6 semanas após início) para ajuste de dose.`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-086`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`enav`,topico:`endocrinos`,subtopico:`Insulina`,dificuldade:`facil`,enunciado:`Sobre as preparações de insulina veterinárias, assinale a alternativa CORRETA:`,alternativas:[`A insulina regular (cristalina) é utilizada para manutenção do diabetes mellitus em cães.`,`A insulina NPH possui duração de ação intermediária (6-12h em cães) e é amplamente utilizada para manutenção do diabetes canino.`,`A insulina glargina possui ação ultrarrápida, sendo ideal para crises hiperglicêmicas.`,`A insulina PZI (protamina-zinco-insulina) é a de primeira escolha para cães.`,`Todas as insulinas possuem a mesma duração de ação em cães e gatos.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Insulina regular é de ação CURTA (4-6h), usada IV para crises, não para manutenção.`,B:`Correto. NPH (isofana) é intermediária (6-12h cães, 4-8h gatos). É a mais utilizada para manutenção do diabetes canino.`,C:`Gargina é de ação PROLONGADA (24h), não ultrarrápida.`,D:`PZI é utilizada preferencialmente em GATOS, não em cães.`,E:`A duração varia significativamente entre espécies (gatos metabolizam mais rapidamente).`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-087`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`reprodutores`,subtopico:`GnRH`,dificuldade:`medio`,enunciado:`Os análogos de GnRH (gonadorelina, buserelina) são utilizados em protocolos reprodutivos em bovinos. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`A GnRH e seus análogos causam liberação de LH e FSH da hipófise, induzindo ovulação e luteinização de folículos dominantes.`,`A GnRH não pode ser utilizada em protocolos de IATF (inseminação artificial em tempo fixo).`,`A buserelina não induz ovulação em bovinos, sendo ineficaz em protocolos reprodutivos.`,`A dose de GnRH é a mesma para todas as espécies domésticas.`,`A GnRH não possui efeito sobre o corpo lúteo, atuando apenas sobre folículos ovarianos.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. GnRH estimula a liberação pulsátil de LH e FSH. Em protocolos IATF (Ovsynch, CoSynch), induz ovulação do folículo dominante e luteinização.`,B:`GnRH é COMPONENTE ESSENCIAL dos protocolos IATF (1ª e 3ª aplicação no Ovsynch).`,C:`Buserelina (análogo de GnRH) induz ovulação em bovinos, sendo amplamente utilizada.`,D:`A dose varia entre espécies (bovinos: 10-25 mcg buserelina; equinos: doses diferentes).`,E:`A GnRH indiretamente afeta o corpo lúteo via LH (luteinização e manutenção).`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Pursley JR, et al.`,titulo:`Ovsynch protocol in dairy cows`,journal:`J Dairy Sci`,ano:1997}]},{id:`farm-088`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`reprodutores`,subtopico:`Progesterona`,dificuldade:`dificil`,enunciado:`A progesterona é essencial para a manutenção da gestação em todas as espécies domésticas. Sobre seu uso farmacológico, assinale a alternativa CORRETA:`,alternativas:[`A altrenogest (Regumate) é um progestágeno sintético utilizado para sincronização de estro em equinos e suínos.`,`A progesterona natural pode ser administrada por via oral em todas as espécies com alta biodisponibilidade.`,`A progesterona não possui efeitos sobre o sistema nervoso central.`,`O uso de progestágenos em cães não apresenta riscos de piometra.`,`A progesterona é contraindicada em todas as espécies durante a gestação.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Altrenogest (Regumate) é progestágeno oral eficaz em éguas (sincronização de estro) e porcas (supressão do estro). É altamente biodisponível por via oral.`,B:`Progesterona natural possui baixa biodisponibilidade oral (extenso metabolismo de primeira passagem), sendo necessárias formulações injetáveis ou intravaginais.`,C:`Progesterona e seus metabólitos (alopregnanolona) atuam em receptores GABA-A no SNC, causando sedação.`,D:`Progestágenos em cães aumentam significativamente o risco de piometra (hiperplasia cística endometrial).`,E:`Progesterona é ESSENCIAL para manutenção da gestação, sendo utilizada em risco de aborto.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Arthur GH, et al.`,titulo:`Veterinary Reproduction and Obstetrics`,ano:2019}]},{id:`farm-089`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`reprodutores`,subtopico:`Prostaglandinas`,dificuldade:`facil`,enunciado:`Sobre o uso de análogos de prostaglandina F2α (cloprostenol, dinoprost) em protocolos reprodutivos, assinale a alternativa CORRETA:`,alternativas:[`O cloprostenol é eficaz para luteólise em equinos e bovinos, sendo utilizado para sincronização de estro e tratamento de piometra em cadelas.`,`A PGF2α não causa efeitos colaterais em equinos.`,`O cloprostenol é contraindicado em fêmeas gestantes por não possuir efeito luteolítico.`,`A PGF2α não pode ser utilizada para indução de parto em bovinos.`,`O cloprostenol não possui vantagens sobre a PGF2α natural em termos de potência e duração.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Cloprostenol (prostaglandina sintética) causa luteólise em bovinos e equinos. Em cadelas com piometra, induz contração miometrial e luteólise.`,B:`PGF2α em equinos pode causar cólica, sudorese, taquicardia e defecação.`,C:`É contraindicada em gestantes pelo efeito ABORTIVO (não por falta de eficácia).`,D:`PGF2α é utilizada para indução de parto em bovinos (dia 270+ de gestação).`,E:`Cloprostenol é mais potente e de mais longa duração que PGF2α natural.`},referencias:[{autores:`Arthur GH, et al.`,titulo:`Veterinary Reproduction and Obstetrics`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-090`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Veterinário Prefeitura RJ 2023`,tipo:`concurso`,topico:`reprodutores`,subtopico:`Ocitocina`,dificuldade:`medio`,enunciado:`A ocitocina é utilizada para indução e condução do parto em diversas espécies. Sobre seu uso clínico, assinale a alternativa INCORRETA:`,alternativas:[`A ocitocina pode ser utilizada para auxiliar na expulsão fetal quando há dilatação cervical completa e feto em posição normal.`,`A ocitocina é utilizada para tratamento de atonia uterina pós-parto e retenção de placenta.`,`A ocitocina é segura em doses ilimitadas, sem risco de tetania uterina ou ruptura.`,`A ocitocina em doses baixas (5-10 UI) causa contrações uterinas rítmicas semelhantes às do parto normal.`,`A ocitocina estimula a ejeção do leite ao contrair as células mioepiteliais da glândula mamária.`],resposta_correta:`C`,explicacoes_alternativas:{A:`Correto. Ocitocina é utilizada em distocia com dilatação completa e feto normal.`,B:`Correto. Ocitocina auxilia na contração uterina pós-parto e retenção de placenta.`,C:`INCORRETO. Altas doses de ocitocina causam tetania uterina (contração sustentada), comprometendo o fluxo sanguíneo placentário e podendo causar ruptura uterina.`,D:`Correto. Doses baixas causam contrações rítmicas; doses altas causam tetania.`,E:`Correto. A ocitocina é o hormônio da "descida do leite" por contração mioepitelial.`},referencias:[{autores:`Arthur GH, et al.`,titulo:`Veterinary Reproduction and Obstetrics`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-091`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`toxicologia`,subtopico:`Rodenticidas`,dificuldade:`medio`,enunciado:`A intoxicação por rodenticidas anticoagulantes (warfarina, bromadiolona, brodifacum) é uma das mais comuns em cães. Sobre o mecanismo de intoxicação e tratamento, assinale a alternativa CORRETA:`,alternativas:[`Os rodenticidas anticoagulantes inibem a síntese de fatores de coagulação dependentes de vitamina K (II, VII, IX, X), causando hemorragia em 24-48 horas.`,`Os rodenticidas anticoagulantes são de ação curta, com efeito limitado a 24 horas.`,`O antídoto para intoxicação por rodenticidas anticoagulantes é a vitamina K1 (filoquinona), administrada por via oral ou parenteral.`,`A vitamina K3 (menadiona) é mais eficaz que a vitamina K1 para tratamento de intoxicação por anticoagulantes.`,`Os rodenticidas anticoagulantes de 2ª geração (brodifacum) possuem meia-vida curta, necessitando de tratamento por apenas 3-5 dias.`],resposta_correta:`C`,explicacoes_alternativas:{A:`O mecanismo está correto (inibição de vitamina K epóxido redutase), mas a hemorragia pode ocorrer em 2-5 dias (não 24-48h).`,B:`Rodenticidas de 2ª geração (brodifacum, bromadiolona) possuem meia-vida MUITO LONGA (semanas-meses), exigindo tratamento prolongado.`,C:`Correto. Vitamina K1 (5 mg/kg/dia) é o antídoto. Deve ser administrada por via SC ou oral (não IV, risco de anafilaxia). Tratamento: 2ª geração = 4-6 semanas.`,D:`Vitamina K3 (menadiona) é MENOS eficaz e pode causar hemólise em cães. K1 é preferida.`,E:`Brodifacum (2ª geração) requer tratamento de 4-6 semanas devido à longa meia-vida.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Means C`,titulo:`Rodenticide poisoning in dogs and cats`,journal:`Vet Med`,ano:2018}]},{id:`farm-092`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário IBAMA 2022`,tipo:`concurso`,topico:`toxicologia`,subtopico:`Plantas tóxicas`,dificuldade:`dificil`,enunciado:`A intoxicação por Senecio spp. (crassina) é endêmica em bovinos no Brasil. Sobre a toxicologia dessa planta, assinale a alternativa CORRETA:`,alternativas:[`Os alcaloides pirrolizidínicos da Senecio spp. são metabolizados no fígado em pirróis reativos, que formam ligações cruzadas com DNA e proteínas, causando necrose hepatocelular, megalocitose e fibrose.`,`A intoxicação por Senecio é aguda, com sinais clínicos em 24-48 horas.`,`A Senecio causa fotossensibilização primária, sem lesão hepática.`,`O antídoto para intoxicação por Senecio é a atropina.`,`A Senecio é tóxica apenas para bovinos, não afetando equinos ou ovinos.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Alcaloides pirrolizidínicos são bioativados no fígado em pirróis reativos (dehidroalcaloides), que cross-linkam DNA e proteínas, causando necrose, megalocitose e fibrose hepática progressiva.`,B:`A intoxicação é CRÔNICA (semanas-meses de ingestão), com sinais de insuficiência hepática progressiva.`,C:`Senecio causa fotossensibilização SECUNDÁRIA (por disfunção hepática), não primária.`,D:`Não há antídoto específico. Tratamento é de suporte (evitar exposição).`,E:`Senecio é tóxica para bovinos, equinos, ovinos e caprinos, embora haja variação interespecífica.`},referencias:[{autores:`Riet-Correa F, et al.`,titulo:`Plantas tóxicas do Brasil`,ano:2016},{autores:`Tokarnia CH, et al.`,titulo:`Plantas tóxicas da Amazônia`,ano:2012}]},{id:`farm-093`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário CETESB 2022`,tipo:`concurso`,topico:`toxicologia`,subtopico:`Antídotos`,dificuldade:`facil`,enunciado:`Sobre o uso de antídotos em toxicologia veterinária, assinale a alternativa que associa CORRETAMENTe o antídoto à intoxicação:`,alternativas:[`N-acetilcisteína (NAC) para intoxicação por organofosforados.`,`Atropina para intoxicação por paracetamol.`,`Vitamina K1 para intoxicação por rodenticidas anticoagulantes.`,`Pralidoxima (2-PAM) para intoxicação por metais pesados.`,`D-penicilamina para intoxicação por plantas hepatotóxicas.`],resposta_correta:`C`,explicacoes_alternativas:{A:`NAC é antídoto para PARACETAMOL (repleta glutationa). Para organofosforados: atropina + 2-PAM.`,B:`Atropina é para ORGANOFOSFORADOS/CARBAMATOS (efeitos muscarínicos). Para paracetamol: NAC.`,C:`Correto. Vitamina K1 (filoquinona) é o antídoto para rodenticidas anticoagulantes (warfarina, brodifacum), restaurando a síntese de fatores de coagulação dependentes de vitamina K.`,D:`Pralidoxima (2-PAM) reativa a acetilcolinesterase inibida por organofosforados. Para metais pesados: EDTA, DMSA, D-penicilamina.`,E:`D-penicilamina é quelante para metais pesados (chumbo, cobre). Não há antídoto específico para plantas hepatotóxicas.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Osweiler GD`,titulo:`Toxicology`,ano:2020}]},{id:`farm-094`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`toxicologia`,subtopico:`Organofosforados`,dificuldade:`dificil`,enunciado:`A intoxicação por organofosforados e carbamatos é comum em animais de produção. Sobre a diferenciação clínica, assinale a alternativa CORRETA:`,alternativas:[`Organofosforados e carbamatos inibem a acetilcolinesterase de forma reversível, com duração de efeito semelhante.`,`Organofosforados inibem a AChE por fosforilação (irreversível na prática), enquanto carbamatos inibem por carbamoilação (reversível em horas).`,`A pralidoxima (2-PAM) é eficaz para reativar AChE inibida por carbamatos, sendo utilizada rotineiramente.`,`A atropina reverte os efeitos nicotínicos (fasciculações musculares) da intoxicação.`,`Carbamatos e organofosforados não possuem efeito cumulativo.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Organofosforados (fosforilação) são IRREVERSÍVEIS (envelhecimento do complexo). Carbamatos (carbamoilação) são reversíveis em 24-48h.`,B:`Correto. Organofosforados inativam AChE por fosforilação (envelhecimento = irreversível). Carbamatos inibem por carbamoilação (reversível). Isso determina a gravidade e duração do tratamento.`,C:`2-PAM é mais eficaz para organofosforados (antes do envelhecimento). Para carbamatos, atropina é suficiente.`,D:`Atropina reverte apenas efeitos MUSCARÍNICOS. Não reverte nicotínicos (fasciculações) nem centrais (convulsões).`,E:`Ambos podem ter efeito cumulativo com exposições repetidas.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Osweiler GD`,titulo:`Toxicology`,ano:2020}]},{id:`farm-095`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`interacoes`,subtopico:`Interações comuns`,dificuldade:`medio`,enunciado:`As interações medicamentosas podem aumentar ou reduzir a eficácia de fármacos. Sobre interações clinicamente relevantes em veterinária, assinale a alternativa CORRETA:`,alternativas:[`O uso concomitante de fenobarbital (indutor enzimático) com outros fármacos metabolizados pelo fígado pode reduzir suas concentrações plasmáticas e eficácia.`,`O uso de AINEs com corticosteroides é seguro e recomendado para potencializar o efeito anti-inflamatório.`,`A eritromicina (inibidor de CYP3A4) não interage com outros fármacos metabolizados pelo citocromo P450.`,`O uso de tramadol com inibidores de MAO (selegilina) é seguro em cães.`,`A fenitoína e o fenobarbital possuem sinergismo antiepiléptico, sendo sempre mais eficazes em associação.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Fenobarbital induz CYP3A4 e outras isoformas, aumentando o metabolismo de fármacos coadministrados (ciclosporina, corticosteroides, etc), reduzindo seus níveis plasmáticos.`,B:`AINEs + corticosteroides aumentam significativamente o risco de úlcera GI e nefrotoxicidade.`,C:`Eritromicina é potente inibidor de CYP3A4, aumentando concentrações de ciclosporina, midazolam, etc.`,D:`Selegilina (IMAO-B) + tramadol = risco de SÍNDROME SEROTONINÉRGICA (hipertermia, convulsões).`,E:`Fenitoína + fenobarbital possuem interação complexa, com indução mútua e redução de níveis.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Martinez M, Modric S`,titulo:`Drug interactions in veterinary medicine`,journal:`J Vet Pharmacol Ther`,ano:2010}]},{id:`farm-096`,banca:`UNESP`,ano:2022,prova:`UNESP — Professor Farmacologia 2022`,tipo:`concurso`,topico:`interacoes`,subtopico:`Sinergismo e antagonismo`,dificuldade:`dificil`,enunciado:`O sinergismo antimicrobiano é utilizado para tratar infecções graves. Sobre exemplos de sinergismo clinicamente relevante, assinale a alternativa CORRETA:`,alternativas:[`A associação de penicilina G + aminoglicosídeo (amicacina) é sinérgica contra Enterococcus spp., pois a penicilina danifica a parede celular, facilitando a entrada do aminoglicosídeo.`,`A associação de dois bactericidas sempre produz sinergismo.`,`A associação de bactericida + bacteriostático é sempre sinérgica.`,`A sulfonamida + trimetoprima possuem efeito antagônico por atuarem na mesma via metabólica.`,`A associação de cefalosporina + metronidazol não possui indicação clínica.`],resposta_correta:`A`,explicacoes_alternativas:{A:`Correto. Penicilina (beta-lactâmico) danifica a parede → facilita penetração de aminoglicosídeo → sinergismo bactericida contra Enterococcus. Clássico exemplo de sinergismo.`,B:`Nem sempre. Dois bactericidas podem competir pelo mesmo alvo ou não ter sinergismo.`,C:`Bactericida + bacteriostático pode ser antagônico (ex: penicilina + cloranfenicol). O bacteriostático inibe a divisão, reduzindo o alvo do bactericida.`,D:`Sulfonamida + trimetoprima possuem SINERGISMO (bloqueio sequencial da via do ácido fólico).`,E:`Cefalosporina + metronidazol é indicada para infecções mistas (aeróbios + anaeróbios).`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-097`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`interacoes`,subtopico:`Interações comuns`,dificuldade:`medio`,enunciado:`Sobre a interação entre fármacos e alimentos em medicina veterinária, assinale a alternativa CORRETA:`,alternativas:[`A tetracicлина (doxiciclina) tem sua absorção aumentada quando administrada com leite ou antiácidos.`,`A absorção de levotiroxina é reduzida quando administrada com alimentos ou cálcio, devendo ser administrada em jejum.`,`O metronidazol tem sua absorção completamente inibida pela presença de alimentos.`,`Todos os fármacos devem ser administrados em jejum para melhor biodisponibilidade.`,`A absorção de fenobarbital não é afetada pela presença de alimentos.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Cálcio (leite), ferro e antiácidos QUELAM tetraciclinas, REDUZINDO absorção. Administração separada.`,B:`Correto. Cálcio, ferro e alimentos reduzem absorção de levotiroxina por quelation. Deve ser administrada 30-60 min antes das refeições.`,C:`Alimentos podem reduzir a velocidade de absorção de metronidazol, mas não a eliminam completamente.`,D:`Alguns fármacos têm absorção AUMENTADA com alimentos (ex: itraconazol, griseofulvina).`,E:`Fenobarbital tem absorção mais lenta com alimentos, embora a extensão não seja significativamente alterada.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Martinez M, Modric S`,titulo:`Drug interactions in veterinary medicine`,journal:`J Vet Pharmacol Ther`,ano:2010}]},{id:`farm-098`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`interacoes`,subtopico:`Sinergismo e antagonismo`,dificuldade:`facil`,enunciado:`Sobre os tipos de interações farmacológicas, assinale a alternativa CORRETA:`,alternativas:[`Sinergismo ocorre quando o efeito combinado de dois fármacos é igual à soma dos efeitos individuais.`,`Antagonismo ocorre quando o efeito combinado de dois fármacos é MENOR que o esperado pela soma dos efeitos individuais, como no caso de naloxana revertendo os efeitos de morfina.`,`O sinergismo é sempre benéfico na terapêutica veterinária.`,`O antagonismo ocorre apenas entre fármacos da mesma classe.`,`A adição ocorre quando o efeito combinado é superior à soma dos efeitos individuais.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Sinergismo é quando o efeito combinado é MAIOR que a soma. Efeito igual à soma é ADIÇÃO.`,B:`Correto. Antagonismo = efeito combinado < soma. Exemplo: naloxana (antagonista μ) reverte morfina (agonista μ).`,C:`Sinergismo pode ser prejudicial quando aumenta toxicidade (ex: nefrotoxicidade de aminoglicosídeo + furosemida).`,D:`Antagonismo pode ocorrer entre fármacos de classes diferentes (ex: atropina antagoniza acetilcolina).`,E:`Efeito superior à soma é SINERGISMO. Adição = efeito igual à soma.`},referencias:[{autores:`Rang HP, Dale MM`,titulo:`Rang and Dale's Pharmacology`,ano:2019},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-099`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`especie`,subtopico:`Farmacologia em suínos`,dificuldade:`medio`,enunciado:`A farmacologia em suínos possui particularidades importantes. Sobre o uso de fármacos nessa espécie, assinale a alternativa CORRETA:`,alternativas:[`Os suínos possuem metabolismo hepático idêntico ao de cães, não havendo necessidade de ajustes de dose.`,`A via oral é a mais utilizada em suínos de produção, pois permite medicação em massa pela ração ou água.`,`Os suínos não apresentam variações interespecíficas na sensibilidade a antibióticos.`,`A xilazina é segura em suínos, sendo amplamente utilizada para sedação.`,`Os suínos não desenvolvem resistência antimicrobiana, sendo seguro o uso de antibióticos como promotores de crescimento.`],resposta_correta:`B`,explicacoes_alternativas:{A:`Suínos possuem metabolismo hepático diferente de cães, com diferenças em CYP450 e glucuronidação.`,B:`Correto. A via oral (medicação em massa via ração/água) é a mais prática e utilizada em suínos de produção, permitindo tratamento de grandes lotes.`,C:`Suínos apresentam variações de sensibilidade e resistência antimicrobiana, especialmente em Salmonella e E. coli.`,D:`Xilazina em suínos causa vômito profundo e excitação, sendo de utilidade limitada. Detomidina/medetomidina são mais seguras.`,E:`A resistência antimicrobiana em suínos é crescente, levando à proibição de promotores de crescimento em muitos países.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Bollen P, et al.`,titulo:`The Laboratory Swine`,ano:2010}]},{id:`farm-100`,banca:`UFMT`,ano:2023,prova:`UFMT — Residência Clínica Bovinos 2023`,tipo:`residencia`,topico:`especie`,subtopico:`Farmacologia em bovinos`,dificuldade:`dificil`,enunciado:`A via ruminal em bovinos afeta significativamente a farmacocinética de fármacos administrados por via oral. Sobre as particularidades da farmacologia ruminal, assinale a alternativa CORRETA:`,alternativas:[`O pH ruminal (5,5-7,0) e a microbiota ruminal não afetam a biodisponibilidade de fármacos orais.`,`A penicilina G oral é eficaz em bovinos por ser resistente à degradação ruminal.`,`A degradação ruminal de antibióticos como penicilina G e eritromicina base é significativa, sendo preferidas formulações resistentes ou vias parenterais para esses fármacos.`,`O rúmen funciona como um reservatório que sempre aumenta a absorção de fármacos.`,`A via intraruminal é a via de escolha para administração de antibióticos em bovinos.`],resposta_correta:`C`,explicacoes_alternativas:{A:`O pH ruminal e a microbiota (bactérias, protozoários) degradam significativamente muitos fármacos.`,B:`Penicilina G oral é rapidamente degradada pelas bactérias ruminais, sendo ineficaz por via oral em ruminantes adultos.`,C:`Correto. Bactérias ruminais degradam beta-lactâmicos (penicilina G), eritromicina base e outros antibióticos. Formulações resistentes (ex: penicilina V, ceftiofur) ou via parenteral são preferidas.`,D:`O rúmen pode RETARDAR a absorção (pooling) ou DEGRADAR fármacos, não necessariamente aumentando a absorção.`,E:`A via intraruminal não é utilizada para antibióticos. A via IM ou SC é preferida.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-101`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`antimicrobianos_avancados`,subtopico:`Mecanismos de resistência bacteriana`,dificuldade:`dificil`,enunciado:`A respeito dos mecanismos de resistência bacteriana aos antimicrobianos, assinale a opção correta.`,alternativas:[`A produção de betalactamases é o principal mecanismo de resistência aos aminoglicosídeos nas bactérias Gram-negativas.`,`A resistência mediada por bombas de efluxo afeta exclusivamente as fluorquinolonas e não pode ser revertida por inibidores específicos.`,`A alteração do sítio de ligação da penicilina (PBPs alteradas) é o mecanismo principal de resistência do Staphylococcus aureus resistente à meticilina (MRSA).`,`A resistência por permeabilidade reduzida é mais frequente em bactérias Gram-positivas devido à presença de lipopolissacarídeos na parede celular.`,`A produção de enzimas clorafenicol-acetiltransferase confere resistência ao cloranfenicol por hidrólise da molécula.`],resposta_correta:`C`,explicacao:`O MRSA adquire resistência mediante a produção de uma PBP2a (proteína ligadora de penicilina 2a) codificada pelo gene mecA, que possui baixa afinidade por todos os betalactâmicos. As demais alternativas contêm imprecisões: (A) betalactamases atuam sobre betalactâmicos, não aminoglicosídeos; (B) bombas de efluxo afetam múltiplas classes e podem ser inibidas; (D) permeabilidade reduzida é mais relevante em Gram-negativas (membrana externa); (E) a acetiltransferase acetila o cloranfenicol, mas o termo "hidrólise" está incorreto.`,explicacoes_alternativas:{A:`Incorreto. Betalactamases hidrolisam o anel betalactâmico de penicilinas, cefalosporinas e carbapenêmicos. A resistência aos aminoglicosídeos ocorre por enzimas modificadoras (acetiltransferases, fosfotransferases, nucleotidiltransferases).`,B:`Incorreto. Bombas de efluxo como as da família RND (ex.: AcrAB-TolC em Enterobacteriaceae) conferem resistência a múltiplas classes (fluorquinolonas, tetraciclinas, cloranfenicol). Inibidores de efluxo estão em desenvolvimento.`,C:`Correto. O gene mecA codifica a PBP2a com baixa afinidade por betalactâmicos, sendo este o mecanismo clássico de resistência do MRSA.`,D:`Incorreto. A permeabilidade reduzida é característica de Gram-negativas, que possuem membrana externa com porinas. Gram-positivas não possuem LPS.`,E:`Incorreto. A cloranfenicol-acetiltransferase acetila o grupo hidroxila do cloranfenicol, inativando-o. O mecanismo é acetilação, não hidrólise.`},referencias:[{autores:`Prescott JF`,titulo:`Antimicrobial Resistance`,ano:2020},{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-102`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`antimicrobianos_avancados`,subtopico:`Uso profilático de antimicrobianos`,dificuldade:`medio`,enunciado:`Sobre o uso profilático de antimicrobianos em Medicina Veterinária, é CORRETO afirmar:`,alternativas:[`A profilaxia antimicrobiana é indicada em todas as cirurgias limpas realizadas em pequenos animais, independentemente do tempo cirúrgico.`,`Na profilaxia cirúrgica, a primeira dose deve ser administrada no início da indução anestésica, garantindo concentração tecidual adequada no momento da incisão.`,`O uso de antimicrobianos como promotores de crescimento é amplamente recomendado pela OMS para todas as espécies de produção.`,`A profilaxia com fluorquinolonas é a primeira escolha para cirurgias ortopédicas em equinos devido ao seu amplo espectro e baixo custo.`,`A duração ideal da profilaxia antimicrobiana cirúrgica é de 7 a 14 dias em todos os procedimentos.`],resposta_correta:`B`,explicacao:`A administração do antimicrobiano profilático deve ocorrer 30-60 minutos antes da incisão (cefalosporinas) ou na indução anestésica, para que haja concentração tecidual adequada no momento da contaminação potencial.`,explicacoes_alternativas:{A:`Incorreto. Nem toda cirurgia limpa necessita profilaxia. Fatores como tempo cirúrgico >90 min, implantes de material estranho e condições do paciente devem ser considerados.`,B:`Correto. O timing da administração é crucial para garantir concentrações séricas e teciduais adequadas no momento da potencial contaminação bacteriana.`,C:`Incorreto. A OMS e órgãos regulatórios como a ANVISA e o EMA recomendam a restrição do uso de antimicrobianos como promotores de crescimento.`,D:`Incorreto. Fluorquinolonas são reservadas para infecções específicas. Cefalosporinas de primeira e segunda geração são mais indicadas para profilaxia cirúrgica.`,E:`Incorreto. A profilaxia antimicrobiana deve ser de curta duração, idealmente limitada a 24 horas perioperatórias para evitar resistência.`},referencias:[{autores:`Weese JS, Giguère S`,titulo:`Antimicrobial Prophylaxis in Veterinary Surgery`,ano:2019},{autores:`Radlinsky MAG`,titulo:`Surgical Infections and Antimicrobial Use`,ano:2018}]},{id:`farm-103`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`antimicrobianos_avancados`,subtopico:`Terapia combinada com antimicrobianos`,dificuldade:`medio`,enunciado:`A terapia combinada de antimicrobianos pode ser utilizada em situações específicas na clínica veterinária. Analise as afirmativas e assinale a alternativa CORRETA:`,alternativas:[`A combinação de penicilina G com aminoglicosídeos apresenta efeito sinérgico em infecções por Enterococcus spp., pois a penicilina facilita a penetração do aminoglicosídeo.`,`A associação de duas bactericidas de diferentes mecanismos sempre resulta em antagonismo, sendo contra-indicada na prática veterinária.`,`A combinação de trimetoprima com sulfametoxazola atua de forma antagônica, pois ambos competem pelo mesmo sítio enzimático na via do folato.`,`O uso de eritromicina associada à clindamicina resulta em sinergismo por atuarem em sítios ribossomais distintos.`,`A combinação de metronidazol com amoxicilina é ineficaz contra infecções periodontais em cães e gatos.`],resposta_correta:`A`,explicacao:`A penicilina G, ao inibir a síntese da parede celular, facilita a penetração dos aminoglicosídeos através da membrana, resultando em sinergismo bactericida.`,explicacoes_alternativas:{A:`Correto. A penicilina G compromete a integridade da parede celular bacteriana, facilitando a entrada intracelular dos aminoglicosídeos, resultando em sinergismo bactericida.`,B:`Incorreto. Nem toda combinação de bactericidas resulta em antagonismo. A penicilina com aminoglicosídeos é um exemplo clássico de sinergismo entre bactericidas.`,C:`Incorreto. Trimetoprima e sulfametoxazola atuam em etapas sequenciais da via do folato, resultando em sinergismo, não antagonismo.`,D:`Incorreto. Eritromicina e clindamicina competem pelo sítio 50S do ribossomo, resultando em antagonismo.`,E:`Incorreto. Metronidazol associado à amoxicilina é uma combinação eficaz para infecções periodontais complexas.`},referencias:[{autores:`Giguère S, Prescott JF, Bhowmick PM`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013},{autores:`Levinson W`,titulo:`Review of Medical Microbiology and Immunology`,ano:2020}]},{id:`farm-104`,banca:`CONSULPLAN`,ano:2023,prova:`CONSULPLAN — Técnico MAPA 2023`,tipo:`concurso`,topico:`antimicrobianos_avancados`,subtopico:`Resistência a carbapenêmicos`,dificuldade:`dificil`,enunciado:`A resistência bacteriana aos carbapenêmicos tem se tornado um problema crescente em Medicina Veterinária. Sobre esse tema, assinale a alternativa CORRETA:`,alternativas:[`As metalobetalactamases (MBLs) do tipo NDM-1 são inibidas pelo ácido clavulânico, permitindo a restauração da atividade dos carbapenêmicos.`,`Os carbapenêmicos (imipenem, meropenem) devem ser considerados antimicrobianos de primeira escolha para infecções urinárias não complicadas em cães.`,`A produção de carbapenemases do tipo KPC é mediada por plasmídeos, facilitando a disseminação horizontal entre diferentes espécies bacterianas.`,`O uso rotineiro de carbapenêmicos em animais de produção é recomendado pelas diretrizes do MAPA para controle de mastite bovina.`,`A resistência aos carbapenêmicos em Pseudomonas aeruginosa ocorre exclusivamente por produção de betalactamases.`],resposta_correta:`C`,explicacao:`As carbapenemases KPC são codificadas por genes plasmidiais (blaKPC), facilitando a transferência horizontal entre bactérias.`,explicacoes_alternativas:{A:`Incorreto. As metalobetalactamases (MBLs) requerem zinco como cofator e NÃO são inibidas pelo ácido clavulânico.`,B:`Incorreto. Carbapenêmicos são antimicrobianos de último recurso, reservados para infecções graves multirresistentes.`,C:`Correto. O gene blaKPC é frequentemente carregado em transposons plasmidiais, permitindo transferência horizontal.`,D:`Incorreto. Carbapenêmicos são classificados como antimicrobianos de importância crítica e seu uso em produção animal é altamente restrito.`,E:`Incorreto. Pseudomonas pode apresentar resistência por múltiplos mecanismos: carbapenemases, perda de porina OprD, bombas de efluxo.`},referencias:[{autores:`Nordmann P, Poirel L`,titulo:`Epidemiology and Diagnostics of Carbapenem Resistance`,ano:2019},{autores:`MAPA`,titulo:`Plano de Ação Nacional de Resistência aos Antimicrobianos`,ano:2021}]},{id:`farm-105`,banca:`IBFC`,ano:2022,prova:`IBFC — Analista Agropecuário 2022`,tipo:`concurso`,topico:`antimicrobianos_avancados`,subtopico:`Antimicrobianos de importância crítica`,dificuldade:`facil`,enunciado:`De acordo com a classificação da OMS sobre antimicrobianos de importância crítica, é CORRETO afirmar:`,alternativas:[`Os antimicrobianos de importância crítica são aqueles utilizados exclusivamente em Medicina Humana e sem aplicação veterinária.`,`Os carbapenêmicos, fluorquinolonas de 3ª e 4ª geração e polimixinas são classificados como antimicrobianos de importância crítica.`,`A penicilina G é classificada como antimicrobiano de baixa importância, sendo seu uso irrestrito em todas as espécies animais.`,`Os aminoglicosídeos não constam na lista de antimicrobianos de importância crítica da OMS.`,`O uso de antimicrobianos de importância crítica em animais não influencia a resistência bacteriana em humanos.`],resposta_correta:`B`,explicacao:`A OMS classifica carbapenêmicos, fluorquinolonas de 3ª/4ª geração e polimixinas como de importância crítica (HPCIA).`,explicacoes_alternativas:{A:`Incorreto. Antimicrobianos de importância crítica podem ser utilizados em Medicina Veterinária com restrições e critérios de uso prudente.`,B:`Correto. Estes fármacos são classificados como HPCIA pela OMS por serem a última opção terapêutica em infecções multirresistentes.`,C:`Incorreto. Penicilinas são antimicrobianos importantes, devendo ser utilizadas com critério para preservar eficácia.`,D:`Incorreto. Aminoglicosídeos (gentamicina, amicacina) estão na lista de antimicrobianos de importância crítica da OMS.`,E:`Incorreto. O conceito "One Health" reconhece a interligação entre resistência em animais e humanos.`},referencias:[{autores:`WHO`,titulo:`Critically Important Antimicrobials for Human Medicine`,ano:2019},{autores:`OIE`,titulo:`OIE List of Antimicrobial Agents of Veterinary Importance`,ano:2021}]},{id:`farm-106`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário MAPA 2023`,tipo:`concurso`,topico:`quimioterapicos`,subtopico:`Metronidazol`,dificuldade:`medio`,enunciado:`O metronidazol é um quimioterápico amplamente utilizado na clínica veterinária. Sobre suas características farmacológicas, assinale a alternativa CORRETA:`,alternativas:[`O metronidazol é ativo exclusivamente contra bactérias aeróbicas, sendo ineficaz contra protozoários.`,`Seu mecanismo de ação envolve a redução do grupo nitro por enzimas anaeróbicas, gerando radicais tóxicos que danificam o DNA bacteriano.`,`O metronidazol é contraindicado em cães com epilepsia, pois apresenta efeito anticonvulsivante que pode mascarar crises.`,`A hepatotoxicidade é o efeito adverso mais comum em cães, ocorrendo em doses terapêuticas convencionais.`,`O metronidazol não atravessa a barreira hematoencefálica, sendo ineficaz para infecções do sistema nervoso central.`],resposta_correta:`B`,explicacao:`O metronidazol é um pró-fármaco ativado em ambientes anaeróbicos. O grupo nitro é reduzido por nitrorredutases, gerando radicais livres que causam quebras no DNA.`,explicacoes_alternativas:{A:`Incorreto. Metronidazol é ativo contra bactérias anaeróbicas obrigatórias e protozoários (Giardia, Trichomonas, Entamoeba).`,B:`Correto. O mecanismo depende da redução do grupo nitro por enzimas anaeróbicas, gerando intermediários reativos que danificam o DNA.`,C:`Incorreto. Metronidazol não possui efeito anticonvulsivante. Pode causar neurotoxicidade em doses altas.`,D:`Incorreto. Hepatotoxicidade é incomum em doses terapêuticas. Efeitos mais frequentes são gastrointestinais e neurotoxicidade em doses altas.`,E:`Incorreto. Metronidazol possui excelente penetração tecidual, incluindo a barreira hematoencefálica.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Giguère S, Prescott JF`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-107`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBGE 2022`,tipo:`concurso`,topico:`quimioterapicos`,subtopico:`Cloranfenicol`,dificuldade:`medio`,enunciado:`Sobre o cloranfenicol e sua utilização em Medicina Veterinária, assinale a alternativa INCORRETA:`,alternativas:[`O cloranfenicol inibe a síntese proteica bacteriana ao se ligar à subunidade 50S do ribossomo.`,`O cloranfenicol possui excelente penetração tecidual, incluindo o sistema nervoso central.`,`A anemia aplástica idiossincrática é um efeito adverso grave em humanos, sendo motivo de restrição em animais de produção.`,`O cloranfenicol é metabolizado principalmente pelo fígado, e seus metabólitos são responsáveis pela toxicidade medular em gatos.`,`O cloranfenicol é amplamente recomendado como antimicrobiano de primeira escolha para infecções urinárias não complicadas em cães.`],resposta_correta:`E`,explicacao:`Cloranfenicol NÃO é primeira escolha para infecções urinárias — há opções mais seguras como amoxicilina e TMS.`,explicacoes_alternativas:{A:`Correto. Cloranfenicol liga-se reversivelmente à subunidade 50S, inibindo a peptidil transferase.`,B:`Correto. Lipofílico, atinge concentrações terapêuticas em praticamente todos os tecidos, incluindo SNC.`,C:`Correto. Anemia aplástica é rara porém grave em humanos, motivando restrições regulatórias.`,D:`Correto. Gatos possuem deficiência de glucoronidase, aumentando o risco de toxicidade.`,E:`Incorreto. Cloranfenicol não é primeira escolha para infecções urinárias.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-108`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Analista CEASA 2023`,tipo:`concurso`,topico:`quimioterapicos`,subtopico:`Rifampicina`,dificuldade:`dificil`,enunciado:`A rifampicina é um antimicrobiano utilizado em protocolos específicos. Analise as afirmativas e assinale a CORRETA:`,alternativas:[`A rifampicina atua inibindo a RNA polimerase dependente de DNA bacteriana, impedindo a transcrição do RNA mensageiro.`,`A rifampicina é classificada como antimicrobiano bacteriostático, sendo ineficaz contra micobactérias em replicação ativa.`,`O principal mecanismo de resistência envolve alteração na permeabilidade da membrana externa bacteriana.`,`A rifampicina não interage com outros fármacos, sendo segura para uso concomitante.`,`Em equinos, a rifampicina é contraindicada devido ao risco de hepatotoxicidade fulminante.`],resposta_correta:`A`,explicacao:`A rifampicina liga-se à subunidade beta da RNA polimerase dependente de DNA, bloqueando a elongação do RNA. É bactericida contra micobactérias.`,explicacoes_alternativas:{A:`Correto. A rifampicina liga-se à subunidade β da RNA polimerase, bloqueando a síntese de RNA mensageiro.`,B:`Incorreto. A rifampicina é bactericida, especialmente contra micobactérias em replicação ativa.`,C:`Incorreto. A resistência ocorre por mutações no gene rpoB, que altera o sítio de ligação na RNA polimerase.`,D:`Incorreto. A rifampicina é potente indutor do CYP450, reduzindo a concentração de muitos fármacos.`,E:`Incorreto. A rifampicina é utilizada em equinos, especialmente para Rhodococcus equi em potros.`},referencias:[{autores:`Giguère S`,titulo:`Rhodococcus equi Infections in Foals`,ano:2019},{autores:`Prescott JF`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-109`,banca:`AOCP`,ano:2023,prova:`AOCP — Veterinário SUS 2023`,tipo:`concurso`,topico:`quimioterapicos`,subtopico:`Dapsona`,dificuldade:`medio`,enunciado:`A dapsona é um quimioterápico com uso específico na Medicina Veterinária. Sobre esse fármaco, é CORRETO afirmar:`,alternativas:[`A dapsona atua inibindo a síntese do ácido diidrofólico, sendo classificada como uma sulfonamida de ação prolongada.`,`A dapsona é o fármaco de primeira escolha para leishmaniose visceral canina.`,`O principal efeito adverso é a metemoglobinemia, que pode ser revertida com azul de metileno.`,`A dapsona é contraindicada em gatos devido à extrema nefrotoxicidade nessa espécie.`,`A dapsona possui atividade exclusivamente antibacteriana, sem efeito sobre protozoários.`],resposta_correta:`C`,explicacao:`A dapsona oxida hemoglobina a metemoglobina. O azul de metileno (1-2 mg/kg IV) é o antídoto.`,explicacoes_alternativas:{A:`Incorreto. A dapsona inibe a diidropteroato sintetase (como as sulfonamidas), não a diidrofolato redutase.`,B:`Incorreto. Tratamento de escolha para leishmaniose canina envolve milglumina antimoniat e alopurinol.`,C:`Correto. Metemoglobinemia é o efeito adverso significativo. Azul de metileno é o antídoto.`,D:`Incorreto. Gatos são sensíveis por risco de metemoglobinemia, não por nefrotoxicidade.`,E:`Incorreto. Dapsona possui atividade contra bactérias, protozoários e Leishmania.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-110`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`quimioterapicos`,subtopico:`Nitrofuranos e nitroimidazóis`,dificuldade:`facil`,enunciado:`Sobre os nitrofuranos e nitroimidazóis em Medicina Veterinária, assinale a alternativa CORRETA:`,alternativas:[`A furazolidona e a nitrofurantoína são nitrofuranos amplamente recomendados para uso em animais de produção no Brasil.`,`Os nitrofuranos e seus metabólitos (AMOZ, AHD, AOZ, SEM) são proibidos em animais de abate devido ao potencial carcinogênico.`,`O dimetridazol é um nitrofurano utilizado exclusivamente em aves para controle de coccidiose.`,`Os nitroimidazóis como metronidazol e tinidazol são aprovados para uso em animais de abate no Brasil.`,`Os nitrofuranos atuam inibindo a síntese de ergosterol na membrana fúngica.`],resposta_correta:`B`,explicacao:`Os nitrofuranos e seus metabólitos são proibidos em animais destinados ao consumo devido ao potencial carcinogênico e mutagênico.`,explicacoes_alternativas:{A:`Incorreto. Nitrofuranos são proibidos em animais de produção no Brasil.`,B:`Correto. Metabólitos residuais de nitrofuranos possuem potencial carcinogênico e mutagênico.`,C:`Incorreto. Dimetridazol é um nitroimidazol, não nitrofurano.`,D:`Incorreto. Nitroimidazóis são proibidos em animais de abate no Brasil e na UE.`,E:`Incorreto. Nitrofuranos atuam sobre DNA bacteriano, não ergosterol.`},referencias:[{autores:`MAPA — IN 77/2018`,titulo:`Planos Nacionais de Controle de Resíduos`,ano:2018},{autores:`Veach BT et al.`,titulo:`Nitrofuran Residues in Food Animals`,ano:2019}]},{id:`farm-111`,banca:`FUNDATEC`,ano:2022,prova:`FUNDATEC — Veterinário RS 2022`,tipo:`concurso`,topico:`farmacos_respiratorios`,subtopico:`Mucolíticos e expectorantes`,dificuldade:`facil`,enunciado:`A bromexina e o ambroxol são mucolíticos utilizados na clínica veterinária. Assinale a alternativa CORRETA:`,alternativas:[`A bromexina é um metabólito ativo do ambroxol, sendo este o pró-fármaco.`,`A bromexina atua estimulando a síntese de surfactante pulmonar e promovendo a hidratação do muco por aumento da secreção de fluido seroso.`,`O ambroxol possui apenas atividade mucolítica, sem efeitos anti-inflamatórios ou antioxidantes.`,`A bromexina é contraindicada em equinos por causar broncoespasmo paradoxal.`,`Ambos os fármacos são derivados da vasicina, alcaloide obtido da planta Adhatoda vasica.`],resposta_correta:`B`,explicacao:`Bromexina e ambroxol estimulam a produção de surfactante pelos pneumócitos tipo II e aumentam a secreção do componente seroso, fluidificando o muco.`,explicacoes_alternativas:{A:`Incorreto. A relação está invertida: bromexina é metabolizada gerando ambroxol como metabólito ativo.`,B:`Correto. Estimulam produção de surfactante e aumentam secreção serosa, fluidificando o muco.`,C:`Incorreto. Ambroxol possui propriedades anti-inflamatórias, antioxidantes e anestésicas locais.`,D:`Incorreto. Bromexina e ambroxol são seguros e utilizados em equinos.`,E:`Parcialmente correto, mas B é a resposta mais completa e precisa.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Malcolmson L`,titulo:`Respiratory Pharmacology in Veterinary Medicine`,ano:2019}]},{id:`farm-112`,banca:`CESGRANRIO`,ano:2023,prova:`CESGRANRIO — Médico Veterinário INCRA 2023`,tipo:`concurso`,topico:`farmacos_respiratorios`,subtopico:`Broncodilatadores metilxantínicos`,dificuldade:`medio`,enunciado:`A aminofilina é um broncodilatador da classe das metilxantinas. Sobre seu uso, analise as afirmativas e assinale a CORRETA:`,alternativas:[`A aminofilina inibe a fosfodiesterase (PDE), aumentando os níveis intracelulares de AMPc, resultando em relaxamento do músculo liso brônquico.`,`A aminofilina é composta por 80% de teofilina e 20% de etilenodiamina, sendo esta última responsável pela melhoria da solubilidade.`,`O uso de aminofilina é seguro em gatos em qualquer dose, sem risco de toxicidade.`,`A aminofilina é contraindicada em ICC por causar vasoconstrição coronariana.`,`O índice terapêutico da aminofilina é amplo, sendo rara a ocorrência de efeitos adversos.`],resposta_correta:`A`,explicacao:`A aminofilina inibe a fosfodiesterase, aumentando AMPc intracelular, causando relaxamento da musculatura lisa brônquica.`,explicacoes_alternativas:{A:`Correto. Inibição da PDE aumenta AMPc, causando relaxamento do músculo liso brônquico.`,B:`Parcialmente correto, mas A descreve o mecanismo principal.`,C:`Incorreto. Gatos são mais sensíveis à toxicidade das metilxantinas.`,D:`Incorreto. Pode ser utilizada em ICC com cautela e monitoramento.`,E:`Incorreto. O índice terapêutico é estreito, com margem pequena entre doses terapêuticas e tóxicas.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Padrid P`,titulo:`Canine and Feline Respiratory Pharmacology`,ano:2018}]},{id:`farm-113`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`farmacos_respiratorios`,subtopico:`Agonistas beta-2`,dificuldade:`medio`,enunciado:`O salbutamol é um agonista beta-2 adrenérgico seletivo. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`O salbutamol possui seletividade absoluta para receptores beta-2, sem efeitos sobre beta-1 em doses terapêuticas.`,`O salbutamol é recomendado como tratamento de manutenção isolado em bronquite crônica canina.`,`O salbutamol promove broncodilatação por ativação da adenilato ciclase, aumento de AMPc e relaxamento do músculo liso brônquico.`,`O uso crônico por via inalatória não leva à taquifilaxia.`,`O salbutamol é contraindicado em gatos asmáticos por causar broncoespasmo paradoxal.`],resposta_correta:`C`,explicacao:`O salbutamol ativa adenilato ciclase via receptor beta-2, aumentando AMPc e causando relaxamento do músculo liso brônquico.`,explicacoes_alternativas:{A:`Incorreto. Possui seletividade relativa; em doses altas pode estimular beta-1, causando taquicardia.`,B:`Incorreto. Não é recomendado como monoterapia de manutenção.`,C:`Correto. Mecanismo: ativação da adenilato ciclase → aumento de AMPc → relaxamento.`,D:`Incorreto. Uso crônico pode levar à dessensibilização dos receptores (taquifilaxia).`,E:`Incorreto. É utilizado em gatos com asma/bronquite.`},referencias:[{autores:`Padrid P`,titulo:`Feline Asthma: Diagnosis and Treatment`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-114`,banca:`IESES`,ano:2022,prova:`IESES — Veterinário SC 2022`,tipo:`concurso`,topico:`farmacos_respiratorios`,subtopico:`Anticolinérgicos respiratórios`,dificuldade:`medio`,enunciado:`O brometo de ipratrópio é um anticolinérgico quaternário. Sobre esse fármaco, é CORRETO afirmar:`,alternativas:[`O ipratrópio atua bloqueando receptores muscarínicos M3 na musculatura lisa brônquica, reduzindo a broncoconstrição vagal.`,`O ipratrópio é um anticolinérgico terciário com alta lipofilia, atravessando a barreira hematoencefálica.`,`O ipratrópio é primeira escolha para crise asmática aguda em cães e gatos.`,`O uso sistêmico é preferível à via inalatória devido à maior biodisponibilidade.`,`O ipratrópio não apresenta efeitos anticolinérgicos sistêmicos.`],resposta_correta:`A`,explicacao:`Ipratrópio bloqueia receptores muscarínicos M3 na musculatura lisa brônquica, reduzindo broncoconstrição mediada pelo vago.`,explicacoes_alternativas:{A:`Correto. Antagonista muscarínico que bloqueia M3, inibindo broncoconstrição mediada pelo vago.`,B:`Incorreto. É cátion quaternário com baixa lipofilia e mínima passagem pela BHE.`,C:`Incorreto. Agonistas beta-2 de curta duração são primeira escolha para crise aguda.`,D:`Incorreto. Utilizado por via inalatória/nebulização.`,E:`Incorreto. Pode causar efeitos anticolinérgicos sistêmicos em doses elevadas.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Johnson LR`,titulo:`Canine and Feline Respiratory Medicine`,ano:2020}]},{id:`farm-115`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`farmacos_respiratorios`,subtopico:`Terapia inalatória em pequenos animais`,dificuldade:`facil`,enunciado:`Sobre a terapia inalatória em Medicina Veterinária, assinale a alternativa CORRETA:`,alternativas:[`A terapia inalatória permite a deposição do fármaco diretamente nas vias aéreas, com menores doses sistêmicas e redução de efeitos adversos.`,`Corticosteroides inalatórios devem ser utilizados apenas para crises agudas de asma felina.`,`O uso de espaçadores é desnecessário em Medicina Veterinária.`,`A terapia inalatória apresenta biodisponibilidade sistêmica de 100%.`,`Aerossolização de mucolíticos não pode ser associada a broncodilatadores.`],resposta_correta:`A`,explicacao:`A via inalatória deposita o fármaco diretamente nas vias aéreas, atingindo altas concentrações locais com mínima absorção sistêmica.`,explicacoes_alternativas:{A:`Correto. Permite deposição direta nas vias aéreas, reduzindo dose sistêmica e efeitos adversos.`,B:`Incorreto. Corticosteroides inalatórios são para manutenção a longo prazo.`,C:`Incorreto. Espaçadores são essenciais em Medicina Veterinária.`,D:`Incorreto. Biodisponibilidade sistêmica é baixa, justamente por ser vantagem.`,E:`Incorreto. Mucolíticos e broncodilatadores podem ser associados em nebulização.`},referencias:[{autores:`Johnson LR`,titulo:`Canine and Feline Respiratory Medicine`,ano:2020},{autores:`Padrid P`,titulo:`Inhaled Therapy in Veterinary Medicine`,ano:2019}]},{id:`farm-116`,banca:`AOCP`,ano:2022,prova:`AOCP — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`farmacos_renais`,subtopico:`Diuréticos de alça`,dificuldade:`medio`,enunciado:`A furosemida é o diurético de alça mais utilizado. Sobre seu mecanismo de ação, assinale a alternativa CORRETA:`,alternativas:[`A furosemida atua no túbulo distal, inibindo o cotransportador NaCl.`,`A furosemida inibe o cotransportador Na-K-2Cl na porção espessa ascendente da alça de Henle.`,`A furosemida possui efeito diurético fraco, sendo classificada como poupadora de potássio.`,`O uso crônico não altera o equilíbrio ácido-base.`,`A furosemida é contraindicada em ICC por causar retenção hídrica.`],resposta_correta:`B`,explicacao:`A furosemida inibe o cotransportador NKCC2 na porção espessa ascendente da alça de Henle, promovendo excreção de Na+, K+, Cl- e água.`,explicacoes_alternativas:{A:`Incorreto. Furosemida atua na alça de Henle. Tiazidas atuam no túbulo distal.`,B:`Correto. Cotransportador NKCC2 na alça de Henle é o alvo da furosemida.`,C:`Incorreto. Furosemida é diurético de alta potência.`,D:`Incorreto. Pode causar alcalose hipoclorêmica e hipocalemia.`,E:`Incorreto. Furosemida é diurético de primeira escolha em ICC.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Polzin DJ`,titulo:`Chronic Kidney Disease in Small Animals`,ano:2020}]},{id:`farm-117`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`farmacos_renais`,subtopico:`Diuréticos poupadores de potássio`,dificuldade:`medio`,enunciado:`A espironolactona é um diurético poupador de potássio. Sobre seu mecanismo, é CORRETO afirmar:`,alternativas:[`A espironolactona é antagonista competitivo da aldosterona, bloqueando seus receptores no túbulo coletor cortical.`,`A espironolactona inibe diretamente a anidrase carbônica nos túbulos renais.`,`A espironolactona é indicada como diurético de primeira linha para edema agudo pulmonar.`,`O uso não apresenta risco de hipercalemia mesmo em insuficiência renal.`,`A espironolactona não possui efeitos anti-fibróticos.`],resposta_correta:`A`,explicacao:`Espironolactona compete com aldosterona pelos receptores mineralocorticoides no túbulo coletor cortical.`,explicacoes_alternativas:{A:`Correto. Antagonista competitivo da aldosterona no túbulo coletor cortical.`,B:`Incorreto. Inibidores da anidrase carbônica são acetazolamida.`,C:`Incorreto. Para edema agudo, furosemida é primeira escolha.`,D:`Incorreto. Pode causar hipercalemia potencialmente fatal em insuficiência renal.`,E:`Incorreto. Possui efeitos anti-fibróticos documentados.`},referencias:[{autores:`Kittleson MD`,titulo:`Small Animal Cardiovascular Medicine`,ano:2016},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-118`,banca:`CONSULPLAN`,ano:2023,prova:`CONSULPLAN — Técnico MAPA 2023`,tipo:`concurso`,topico:`farmacos_renais`,subtopico:`Diuréticos tiazídicos`,dificuldade:`facil`,enunciado:`A hidroclorotiazida é um diurético tiazídico. Sobre suas características, assinale a alternativa CORRETA:`,alternativas:[`A hidroclorotiazida atua no túbulo proximal, inibindo a reabsorção de glicose.`,`A hidroclorotiazida inibe o cotransportador NaCl no túbulo distal contornado.`,`A hidroclorotiazida é diurético de primeira escolha para edema agudo pulmonar.`,`As tiazidas não possuem efeito sobre o metabolismo do cálcio.`,`A hidroclorotiazida é contraindicada em diabetes por causar hipoglicemia.`],resposta_correta:`B`,explicacao:`As tiazidas inibem o cotransportador NaCl (NCC) na porção inicial do túbulo distal contornado.`,explicacoes_alternativas:{A:`Incorreto. Tiazidas atuam no túbulo distal, não no proximal.`,B:`Correto. Cotransportador NCC no túbulo distal é o alvo das tiazidas.`,C:`Incorreto. Furosemida é primeira escolha para edema agudo.`,D:`Incorreto. Tiazidas aumentam reabsorção de cálcio, podendo prevenir urolitíase cálcica.`,E:`Incorreto. Tiazidas podem causar hiperglicemia, não hipoglicemia.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`DiBartola SP`,titulo:`Fluid, Electrolyte, and Acid-Base Disorders`,ano:2012}]},{id:`farm-119`,banca:`IBFC`,ano:2023,prova:`IBFC — Analista Agropecuário 2023`,tipo:`concurso`,topico:`farmacos_renais`,subtopico:`Diuréticos osmóticos`,dificuldade:`medio`,enunciado:`O manitol é um diurético osmótico. Sobre esse fármaco, assinale a alternativa INCORRETA:`,alternativas:[`O manitol atua no túbulo proximal e alça de Henle, permanecendo no lúmen tubular.`,`O manitol é utilizado para redução da pressão intracraniana em edema cerebral.`,`O manitol é indicado para profilaxia de insuficiência renal aguda em mioglobinúria.`,`O manitol é contraindicado em anúria estabelecida por piorar a sobrecarga hídrica.`,`O manitol é completamente reabsorvido nos túbulos renais, sendo classificado como poupador de sódio.`],resposta_correta:`E`,explicacao:`Alternativa E é INCORRETA. O manitol NÃO é reabsorvido — permanece no lúmen tubular exercendo efeito osmótico.`,explicacoes_alternativas:{A:`Correto. Manitol é filtrado no glomérulo e permanece no lúmen tubular.`,B:`Correto. Reduz pressão intracraniana por gradiente osmótico.`,C:`Correto. Mantém fluxo tubular, diluindo pigmentos nefrotóxicos.`,D:`Correto. Em anúria, manitol não pode ser excretado, piorando sobrecarga.`,E:`Incorreto. Manitol NÃO é reabsorvido — é excretado inalterado na urina.`},referencias:[{autores:`DiBartola SP`,titulo:`Fluid, Electrolyte, and Acid-Base Disorders`,ano:2012},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-120`,banca:`ANATEC`,ano:2023,prova:`ANATEC — Analista CEASA 2023`,tipo:`concurso`,topico:`farmacos_renais`,subtopico:`Inibidores da anidrase carbônica`,dificuldade:`dificil`,enunciado:`A acetazolamida é um inibidor da anidrase carbônica. Sobre suas características, é CORRETO afirmar:`,alternativas:[`A acetazolamida inibe a anidrase carbônica no túbulo proximal, reduzindo a reabsorção de bicarbonato e produzindo diurese alcalina.`,`A acetazolamida é utilizada para redução da pressão intraocular em glaucoma por aumentar a produção de humor aquoso.`,`A acetazolamida não possui efeito sobre a função respiratória.`,`O uso crônico não leva a acidose metabólica.`,`A acetazolamida é contraindicada em gatos por causar insuficiência renal aguda.`],resposta_correta:`A`,explicacao:`Acetazolamida inibe anidrase carbônica no túbulo proximal, bloqueando reabsorção de bicarbonato, resultando em diurese alcalina.`,explicacoes_alternativas:{A:`Correto. Inibição da anidrase carbônica impede formação de H+ e HCO3-, causando excreção urinária de bicarbonato.`,B:`Incorreto. Acetazolamida reduz (não aumenta) produção de humor aquoso.`,C:`Incorreto. Estimula ventilação por acidose metabólica e é usada para mal da altitude.`,D:`Incorreto. Uso crônico leva a acidose metabólica hiperclorêmica.`,E:`Incorreto. Pode ser utilizada em gatos para glaucoma com monitoramento.`},referencias:[{autores:`Gelatt KN`,titulo:`Veterinary Ophthalmology`,ano:2021},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-121`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`farmacos_gastro`,subtopico:`Procinéticos`,dificuldade:`medio`,enunciado:`A metoclopramida é um procinético amplamente utilizado. Sobre seu mecanismo, assinale a alternativa CORRETA:`,alternativas:[`A metoclopramida é antagonista de receptores D2 no CTZ e no TGI, além de possuir atividade agonista 5-HT4.`,`A metoclopramida aumenta o tônus do EEI e retarda o esvaziamento gástrico.`,`A metoclopramida é contraindicada em cães e gatos por hepatotoxicidade.`,`O uso em cavalos é recomendado como procinético de primeira escolha.`,`A metoclopramida não atravessa a barreira hematoencefálica.`],resposta_correta:`A`,explicacao:`Metoclopramida antagoniza D2 no CTZ (antiemético) e TGI (procinético), e possui atividade agonista 5-HT4.`,explicacoes_alternativas:{A:`Correto. Antagoniza D2 e estimula 5-HT4, promovendo efeito antiemético e procinético.`,B:`Incorreto. Acelera (não retarda) esvaziamento gástrico.`,C:`Incorreto. É segura e amplamente utilizada em cães e gatos.`,D:`Incorreto. Pode causar sedação em equinos, não sendo primeira escolha.`,E:`Incorreto. Atravessa a BHE, podendo causar efeitos no SNC.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Washabau RJ, Day MJ`,titulo:`Canine and Feline Gastroenterology`,ano:2013}]},{id:`farm-122`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBGE 2022`,tipo:`concurso`,topico:`farmacos_gastro`,subtopico:`Antieméticos serotoninérgicos`,dificuldade:`medio`,enunciado:`A ondansetrona é antagonista de receptores 5-HT3. Sobre seu uso, é CORRETO afirmar:`,alternativas:[`A ondansetrona bloqueia receptores 5-HT3 no CTZ e nos nervos vagais aferentes do TGI.`,`A ondansetrona é antagonista de receptores D2, classificada como antiemético de ação central.`,`A ondansetrona não é eficaz para vômito pós-operatório em cães e gatos.`,`O uso é contraindicado em pacientes com síndrome de QT longo.`,`A ondansetrona deve ser administrada exclusivamente por via oral.`],resposta_correta:`A`,explicacao:`Ondansetrona bloqueia 5-HT3 centralmente (CTZ) e perifericamente (nervos vagais).`,explicacoes_alternativas:{A:`Correto. Antagoniza 5-HT3 no CTZ (central) e nervos vagais (periférico).`,B:`Incorreto. É antagonista 5-HT3, não D2.`,C:`Incorreto. É eficaz para vômito pós-operatório.`,D:`Incorreto. Segura em doses terapêuticas.`,E:`Incorreto. Disponível em formulações oral e injetável (IV).`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Washabau RJ`,titulo:`Gastrointestinal Pharmacology`,ano:2019}]},{id:`farm-123`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Analista CEASA 2023`,tipo:`concurso`,topico:`farmacos_gastro`,subtopico:`Inibidores de bomba de prótons`,dificuldade:`facil`,enunciado:`O omeprazol é um inibidor da bomba de prótons. Sobre seu mecanismo, assinale a alternativa CORRETA:`,alternativas:[`O omeprazol inibe irreversivelmente a H+/K+-ATPase nas células parietais gástricas.`,`O omeprazol atua como antagonista de receptores H2 de histamina.`,`O omeprazol é rapidamente degradado pelo ácido gástrico, devendo ser administrado apenas por via endovenosa.`,`O omeprazol não interage com outros fármacos.`,`O omeprazol é contraindicado em equinos por causar cólica severa.`],resposta_correta:`A`,explicacao:`Omeprazol inibe irreversivelmente a H+/K+-ATPase (bomba de prótons) nas células parietais.`,explicacoes_alternativas:{A:`Correto. Inibe irreversivelmente a bomba de prótons, reduzindo secreção ácida.`,B:`Incorreto. Antagonistas H2 são ranitidina e famotidina.`,C:`Incorreto. Possui revestimento entérico e pode ser administrado oralmente.`,D:`Incorreto. Inibe CYP2C19, interagindo com outros fármacos.`,E:`Incorreto. Amplamente utilizado em equinos para úlceras gástricas.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Merritt AM`,titulo:`Equine Gastric Ulcer Syndrome`,ano:2019}]},{id:`farm-124`,banca:`AOCP`,ano:2023,prova:`AOCP — Veterinário SUS 2023`,tipo:`concurso`,topico:`farmacos_gastro`,subtopico:`Protetores de mucosa gástrica`,dificuldade:`medio`,enunciado:`O sucralfato é um agente citoprotetor. Sobre suas características, é CORRETO afirmar:`,alternativas:[`O sucralfato forma complexo aderente com proteínas do leito da úlcera, criando barreira protetora.`,`O sucralfato é solúvel em água e neutraliza o ácido gástrico em todo o lúmen.`,`O sucralfato não interfere na absorção de outros fármacos.`,`O sucralfato não é eficaz para úlceras em equinos em treinamento.`,`O sucralfato não estimula a produção de prostaglandinas E2.`],resposta_correta:`A`,explicacao:`Sucralfato reage com proteínas do leito ulcerado formando barreira física protetora contra ácido, pepsina e sais biliares.`,explicacoes_alternativas:{A:`Correto. Forma complexo com proteínas expostas, criando barreira protetora duradoura.`,B:`Incorreto. Insolúvel em água; mecanismo é formação de barreira física.`,C:`Incorreto. Pode quelar e reduzir absorção de fluorquinolonas, tetraciclinas e digoxina.`,D:`Incorreto. Eficaz na prevenção e tratamento de úlceras em equinos.`,E:`Incorreto. Estimula produção de PGE2 na mucosa gástrica.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Merritt AM`,titulo:`Equine Gastric Ulcer Syndrome`,ano:2019}]},{id:`farm-125`,banca:`FUNDATEC`,ano:2022,prova:`FUNDATEC — Veterinário RS 2022`,tipo:`concurso`,topico:`farmacos_gastro`,subtopico:`Antidiarreicos`,dificuldade:`facil`,enunciado:`A loperamida é um antidiarreico opioide. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`A loperamida é agonista de receptores mu-opioides no intestino, reduzindo motilidade e secreção de fluidos.`,`A loperamida é segura para uso em cães Collie com mutação MDR1.`,`A loperamida é contraindicada em todos os cães.`,`A loperamida não possui efeito sobre a secreção intestinal.`,`A loperamida é primeira escolha para diarreia por toxinas bacterianas.`],resposta_correta:`A`,explicacao:`Loperamida é agonista mu-opioides que reduz motilidade intestinal e secreção de fluidos.`,explicacoes_alternativas:{A:`Correto. Ativa receptores mu-opioides, reduzindo peristaltismo e secreção.`,B:`Incorreto. Cães com mutação MDR1 podem desenvolver depressão respiratória grave.`,C:`Incorreto. Pode ser utilizada em cães sem mutação MDR1.`,D:`Incorreto. Reduz tanto motilidade quanto secreção.`,E:`Incorreto. Pode prolongar exposição à toxina por redução da motilidade.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Mealey KL`,titulo:`MDR1 Mutation and Drug Sensitivity in Dogs`,ano:2018}]},{id:`farm-126`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário MAPA 2023`,tipo:`concurso`,topico:`farmacos_endocrinos_avancados`,subtopico:`Corticosteroides potentes`,dificuldade:`dificil`,enunciado:`A dexametasona é um corticosteroide de alta potência. Sobre suas características, assinale a alternativa INCORRETA:`,alternativas:[`A dexametasona possui potência anti-inflamatória 25-30 vezes superior à hidrocortisona.`,`Apresenta efeito mineralocorticóide mínimo.`,`O LDDST é utilizado para diagnóstico de hiperadrenocorticismo canino.`,`A dexametasona não suprime o eixo HPA, sendo segura para uso crônico sem descontinuação gradual.`,`É utilizada em protocolos de quimioterapia como antiemético.`],resposta_correta:`D`,explicacao:`Alternativa D é INCORRETA. Dexametasona suprime o eixo HPA e descontinuação abrupta pode causar crise addisoniana.`,explicacoes_alternativas:{A:`Correto. ~25-30x mais potente que hidrocortisona.`,B:`Correto. Atividade mineralocorticóide desprezível.`,C:`Correto. LDDST (0,01 mg/kg IV) é teste padrão para Cushing.`,D:`Incorreto. Suprime eixo HPA por feedback negativo sobre ACTH e CRH.`,E:`Correto. Utilizada como antiemético em protocolos de quimioterapia.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015}]},{id:`farm-127`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`farmacos_endocrinos_avancados`,subtopico:`Corticosteroides imunossupressores`,dificuldade:`medio`,enunciado:`A prednisolona em doses imunossupressoras (2-4 mg/kg/dia) atua:`,alternativas:[`A prednisolona é pró-fármaco que necessita conversão hepática para prednisona.`,`Inibe produção de citocinas pró-inflamatórias, reduz migração de leucócitos e diminui expressão de moléculas de adesão.`,`Não aumenta risco de infecções oportunistas.`,`O uso prolongado não leva a supressão do eixo HPA.`,`É contraindicada em gatos por causar diabetes irreversível.`],resposta_correta:`B`,explicacao:`Em doses imunossupressoras, prednisolona inibe citocinas (IL-1, IL-6, TNF-α), reduz migração leucocitária e diminui moléculas de adesão.`,explicacoes_alternativas:{A:`Incorreto. Prednisona é pró-fármaco convertido em prednisolona. A relação está invertida.`,B:`Correto. Inibe múltiplos mecanismos inflamatórios e imunológicos por modulação transcricional.`,C:`Incorreto. Aumenta significativamente risco de infecções oportunistas.`,D:`Incorreto. Suprime eixo HPA; descontinuação deve ser gradual.`,E:`Incorreto. Pode ser utilizada em gatos com monitoramento da glicemia.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Trepanier LA`,titulo:`Immunosuppressive Therapy in Veterinary Medicine`,ano:2019}]},{id:`farm-128`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`farmacos_endocrinos_avancados`,subtopico:`Mineralocorticoides`,dificuldade:`medio`,enunciado:`A fludrocortisona é um mineralocorticoide sintético. Sobre suas características, assinale a CORRETA:`,alternativas:[`A fludrocortisona é utilizada no tratamento de hipoadrenocorticismo (doença de Addison) em cães.`,`Possui apenas atividade glicocorticóide, sem efeito mineralocorticóide.`,`É contraindicada em hipoadrenocorticismo por causar hiponatremia.`,`Não necessita de monitoramento dos níveis de sódio e potássio.`,`Não pode ser utilizada por via oral.`],resposta_correta:`A`,explicacao:`Fludrocortisona é utilizada como reposição mineralocorticóide no hipoadrenocorticismo canino.`,explicacoes_alternativas:{A:`Correto. Mineralocorticóide de escolha para manutenção do hipoadrenocorticismo primário.`,B:`Incorreto. Possui atividade mineralocorticóide potente E glicocorticóide moderada.`,C:`Incorreto. Causa hipernatremia (retenção de sódio), indicada para tratar hiponatremia.`,D:`Incorreto. Monitoramento de Na+ e K+ é essencial para ajuste de dose.`,E:`Incorreto. Administrada por via oral.`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-129`,banca:`CONSULPLAN`,ano:2022,prova:`CONSULPLAN — Técnico MAPA 2022`,tipo:`concurso`,topico:`farmacos_endocrinos_avancados`,subtopico:`Hormônios tireoidianos`,dificuldade:`facil`,enunciado:`A levotiroxina (L-T4) é utilizada para hipotireoidismo canino. Sobre esse fármaco, é CORRETO:`,alternativas:[`A levotiroxina é a forma ativa do hormônio tireoidiano, não necessitando de conversão.`,`A levotiroxina é convertida perifericamente em T3 por desiodases, que é a forma biologicamente ativa.`,`O hipotireoidismo canino é raro, não justificando reposição frequente.`,`A levotiroxina não interage com outros fármacos.`,`A dose é fixa e não necessita de ajuste.`],resposta_correta:`B`,explicacao:`Levotiroxina (T4) é convertida em T3 por desiodases nos tecidos periféricos. T3 é a forma ativa.`,explicacoes_alternativas:{A:`Incorreto. T4 é pró-hormônio que necessita de conversão a T3.`,B:`Correto. Conversão de T4 em T3 é essencial para atividade biológica.`,C:`Incorreto. Hipotireoidismo é a endocrinopatia mais comum em cães.`,D:`Incorreto. Interage com antiácidos, fenobarbital e corticosteroides.`,E:`Incorreto. Requer ajuste baseado nos níveis séricos de T4.`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Scott-Moncrieff JCR`,titulo:`Canine Hypothyroidism`,ano:2019}]},{id:`farm-130`,banca:`IBFC`,ano:2022,prova:`IBFC — Analista Agropecuário 2022`,tipo:`concurso`,topico:`farmacos_endocrinos_avancados`,subtopico:`Corticosteroides — efeitos adversos`,dificuldade:`dificil`,enunciado:`Sobre efeitos adversos do uso prolongado de corticosteroides, analise as afirmativas e assinale a CORRETA:`,alternativas:[`O uso prolongado pode causar síndrome de Cushing iatrogênica com poliúria, polidipsia, polifagia e obesidade.`,`Os corticosteroides não afetam o metabolismo do cálcio, sem risco de osteoporose.`,`A supressão do eixo HPA é exclusiva da prednisona.`,`Em gatos, não aumenta o risco de diabetes mellitus.`,`Os corticosteroides não afetam a mucosa protetora gástrica.`],resposta_correta:`A`,explicacao:`Uso prolongado causa síndrome de Cushing iatrogênica com sinais clássicos.`,explicacoes_alternativas:{A:`Correto. Síndrome de Cushing iatrogênica é efeito adverso bem documentado.`,B:`Incorreto. Causam osteoporose por inibição de absorção de cálcio e redução de atividade osteoblástica.`,C:`Incorreto. Todos os corticosteroides sistêmicos podem suprimir o eixo HPA.`,D:`Incorreto. Gatos são susceptíveis à diabetes mellitus induzida por corticosteroides.`,E:`Incorreto. Reduzem produção de prostaglandinas citoprotetoras e síntese de muco.`},referencias:[{autores:`Feldman EC, Nelson RW`,titulo:`Canine and Feline Endocrinology and Reproduction`,ano:2015},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-131`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`farmacos_reprodutivos`,subtopico:`Prostaglandinas sintéticas`,dificuldade:`medio`,enunciado:`O cloprostenol é análogo sintético da PGF2α. Sobre seu uso, assinale a alternativa CORRETA:`,alternativas:[`O cloprostenol induz luteólise em bovinos e equinos, sendo utilizado para sincronização de estros e indução de parto.`,`O cloprostenol não possui efeitos sobre a musculatura lisa uterina.`,`O cloprostenol é seguro para uso em fêmeas gestantes em qualquer fase.`,`O cloprostenol não apresenta efeitos adversos como sialorreia e sudorese.`,`O cloprostenol é contraindicado em bovinos por causar infertilidade permanente.`],resposta_correta:`A`,explicacao:`Cloprostenol é potente luteolítico que promove regressão do corpo lúteo em bovinos e equinos.`,explicacoes_alternativas:{A:`Correto. Potente luteolítico amplamente usado em programas reprodutivos e IATF.`,B:`Incorreto. Estimula contração da musculatura lisa uterina.`,C:`Incorreto. É abortivo em gestantes após formação do corpo lúteo gestacional.`,D:`Incorreto. Pode causar sialorreia, sudoreta e desconforto abdominal.`,E:`Incorreto. Não causa infertilidade permanente; retorno ao estro em 2-5 dias.`},referencias:[{autores:`Roberts SJ`,titulo:`Veterinary Obstetrics and Genital Diseases`,ano:2017},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-132`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBGE 2022`,tipo:`concurso`,topico:`farmacos_reprodutivos`,subtopico:`Análogos de GnRH`,dificuldade:`dificil`,enunciado:`Buserelina e deslorelina são análogos de GnRH. Sobre seus usos, é CORRETO:`,alternativas:[`A buserelina é utilizada para induzir ovulação, mimetizando o pico pré-ovulatório de LH em protocolos de IATF.`,`A deslorelina em doses baixas causa supressão do eixo gonadal para castração química.`,`Os análogos de GnRH de longa ação são exclusivamente para fêmeas.`,`Buserelina e deslorelina possuem a mesma meia-vida e potência.`,`Os análogos de GnRH não apresentam efeito rebote.`],resposta_correta:`A`,explicacao:`Buserelina induz pico de LH similar ao fisiológico, promovendo ovulação em protocolos de IATF.`,explicacoes_alternativas:{A:`Correto. Induz liberação de LH, essencial em protocolos de IATF.`,B:`Incorreto. Deslorelina em doses altas causa supressão; doses baixas estimulam.`,C:`Incorreto. Utilizada em machos e fêmeas.`,D:`Incorreto. Possuem diferentes meias-vidas e potências.`,E:`Incorreto. Causam efeito flare inicial antes da supressão.`},referencias:[{autores:`Roberts SJ`,titulo:`Veterinary Obstetrics and Genital Diseases`,ano:2017},{autores:`Ginther OJ`,titulo:`Reproductive Biology of the Mare`,ano:2018}]},{id:`farm-133`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Analista CEASA 2023`,tipo:`concurso`,topico:`farmacos_reprodutivos`,subtopico:`Progestágenos em equinos`,dificuldade:`medio`,enunciado:`O altrenogest é um progestágeno sintético utilizado em equinos. Assinale a CORRETA:`,alternativas:[`O altrenogest é administrado por via oral para supressão do estro, manutenção da gestação e sincronização de ciclos em éguas.`,`É contraindicado em éguas gestantes por causar malformações fetais.`,`Não apresenta riscos ao manipulador.`,`Não interage com outros hormônios.`,`É aprovado para uso em bovinos como sincronizador.`],resposta_correta:`A`,explicacao:`Altrenogest é progestágeno oral de alta biodisponibilidade em equinos, com múltiplas indicações reprodutivas.`,explicacoes_alternativas:{A:`Correto. Progestágeno oral com múltiplas indicações reprodutivas em equinos.`,B:`Incorreto. Seguro em éguas gestantes para manutenção de gestação.`,C:`Incorreto. Pode ser absorvido por via cutânea em humanos; manipuladores devem usar luvas.`,D:`Incorreto. Interage com estrógenos e GnRH em protocolos reprodutivos.`,E:`Incorreto. Não é aprovado para uso em bovinos no Brasil.`},referencias:[{autores:`McKinnon AO et al.`,titulo:`Equine Reproduction`,ano:2011},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-134`,banca:`AOCP`,ano:2022,prova:`AOCP — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`farmacos_reprodutivos`,subtopico:`Dinoprost em bovinos`,dificuldade:`facil`,enunciado:`A dinoprost (PGF2α natural) é utilizada em programas reprodutivos de bovinos. Assinale a CORRETA:`,alternativas:[`A dinoprost promove luteólise, sendo utilizada para sincronização de estros e tratamento de retenção de placenta.`,`A dinoprost não possui efeito sobre a musculatura uterina.`,`É contraindicada em vacas gestantes em qualquer fase.`,`Não apresenta efeitos colaterais como sudorese.`,`Não pode ser associada a outros hormônios em protocolos de IATF.`],resposta_correta:`A`,explicacao:`Dinoprost é luteolítica natural, promovendo regressão do corpo lúteo em bovinos.`,explicacoes_alternativas:{A:`Correto. Luteolítica natural para sincronização, luteoma cístico, retenção de placenta.`,B:`Incorreto. Estimula contração da musculatura lisa uterina.`,C:`Incorreto. É abortiva após formação do corpo lúteo gestacional, mas segura sem CL gestacional.`,D:`Incorreto. Pode causar sudoreta, taquicardia e desconforto abdominal.`,E:`Incorreto. É componente essencial de protocolos de IATF.`},referencias:[{autores:`Pursley JR`,titulo:`Reproductive Management of Dairy Cattle`,ano:2018},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-135`,banca:`FUNDATEC`,ano:2023,prova:`FUNDATEC — Veterinário RS 2023`,tipo:`concurso`,topico:`farmacos_reprodutivos`,subtopico:`Ocitocina e distócias`,dificuldade:`medio`,enunciado:`Sobre ocitocina e análogos na indução de parto, assinale a alternativa INCORRETA:`,alternativas:[`A ocitocina induz contrações uterinas rítmicas e promove ejeção do leite.`,`A ocitocina é contraindicada em obstrução mecânica do canal de parto.`,`A desmopressina (DDAVP) é análogo da ocitocina utilizado para indução de parto.`,`A dose de ocitocina para indução deve ser crescente e fracionada.`,`A ocitocina é degradada por ocitocinases plasmáticas, com meia-vida curta.`],resposta_correta:`C`,explicacao:`Alternativa C é INCORRETA. Desmopressina é análogo da vasopressina (ADH), não da ocitocina.`,explicacoes_alternativas:{A:`Correto. Ocitocina estimula contração do miométrio e ejeção do leite.`,B:`Correto. Contraindicada em obstrução por risco de hipertonia e ruptura uterina.`,C:`Incorreto. Desmopressina é análogo da vasopressina (ADH), usada em diabetes insipidus.`,D:`Correto. Doses crescentes e fracionadas para evitar tetania uterina.`,E:`Correto. Meia-vida muito curta (3-5 minutos).`},referencias:[{autores:`Roberts SJ`,titulo:`Veterinary Obstetrics and Genital Diseases`,ano:2017},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-136`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário MAPA 2023`,tipo:`concurso`,topico:`imunofarmacologia`,subtopico:`Ciclosporina`,dificuldade:`dificil`,enunciado:`A ciclosporina é um imunossupressor. Sobre seu mecanismo de ação, assinale a CORRETA:`,alternativas:[`A ciclosporina liga-se à ciclofilina, formando complexo que inibe a calcineurina, bloqueando a transcrição de IL-2.`,`A ciclosporina inibe a síntese de purinas, bloqueando a proliferação de linfócitos B e T.`,`Não apresenta nefrotoxicidade.`,`Não interage com outros fármacos.`,`É exclusivamente utilizada para transplantes de órgãos.`],resposta_correta:`A`,explicacao:`Ciclosporina liga-se à ciclofilina, inibe calcineurina, bloqueando transcrição de IL-2 e ativação de linfócitos T.`,explicacoes_alternativas:{A:`Correto. Mecanismo: ciclosporina → ciclofilina → inibe calcineurina → NFAT não se transloca → IL-2 bloqueada.`,B:`Incorreto. Inibição de purinas é mecanismo da azatioprina.`,C:`Incorreto. É nefrotóxica dose-dependente.`,D:`Incorreto. Interage com azóis e macrolídeos (inibidores CYP3A4).`,E:`Incorreto. Amplamente utilizada em dermatologia veterinária.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Trepanier LA`,titulo:`Immunosuppressive Therapy in Veterinary Medicine`,ano:2019}]},{id:`farm-137`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`imunofarmacologia`,subtopico:`Azatioprina`,dificuldade:`medio`,enunciado:`A azatioprina é um imunossupressor antimetabólito. Sobre seu uso, é CORRETO:`,alternativas:[`A azatioprina é metabolizada em 6-mercaptopurina, que inibe a síntese de purinas.`,`É segura para uso em gatos.`,`Não causa mielossupressão.`,`Não interage com alopurinol.`,`Possui início de ação rápido (24-48 horas).`],resposta_correta:`A`,explicacao:`Azatioprina é pró-fármaco convertido em 6-mercaptopurina, que inibe síntese de purinas.`,explicacoes_alternativas:{A:`Correto. Azatioprina → 6-mercaptopurina → inibe síntese de purinas.`,B:`Incorreto. CONTRAINDICADA em gatos por mielossupressão grave e fatal.`,C:`Incorreto. Mielossupressão é efeito adverso mais significativo.`,D:`Incorreto. Alopurinol inibe xantina oxidase, aumentando toxicidade.`,E:`Incorreto. Início lento (2-6 semanas).`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Trepanier LA`,titulo:`Immunosuppressive Therapy in Veterinary Medicine`,ano:2019}]},{id:`farm-138`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`imunofarmacologia`,subtopico:`Leflunomida`,dificuldade:`medio`,enunciado:`A leflunomida é um imunossupressor. Sobre suas características, assinale a CORRETA:`,alternativas:[`A leflunomida inibe a diidroorotato desidrogenase (DHODH), bloqueando a síntese de pirimidinas.`,`Inibe a síntese de purinas, sendo antagonista do ácido fólico.`,`Não apresenta hepatotoxicidade.`,`É contraindicada em cães por causar insuficiência renal aguda.`,`Tem início de ação rápido (24-48 horas).`],resposta_correta:`A`,explicacao:`Leflunomida inibe DHODH, bloqueando síntese de pirimidinas necessária para proliferação de linfócitos ativados.`,explicacoes_alternativas:{A:`Correto. Inibe DHODH, bloqueando síntese de novo de UMP.`,B:`Incorreto. Inibe pirimidinas, não purinas.`,C:`Incorreto. Pode causar hepatotoxicidade; monitoramento hepático é recomendado.`,D:`Incorreto. Utilizada em cães para doenças imunomediadas.`,E:`Incorreto. Início lento (4-8 semanas).`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Trepanier LA`,titulo:`Immunosuppressive Therapy in Veterinary Medicine`,ano:2019}]},{id:`farm-139`,banca:`AOCP`,ano:2023,prova:`AOCP — Veterinário SUS 2023`,tipo:`concurso`,topico:`imunofarmacologia`,subtopico:`Interferons`,dificuldade:`medio`,enunciado:`O interferon omega (IFN-ω) recombinante é utilizado na Medicina Veterinária. Sobre seu uso, é CORRETO:`,alternativas:[`O IFN-ω possui atividade antiviral, imunomoduladora e antiproliferativa, sendo utilizado em doenças virais.`,`Não apresenta efeitos adversos significativos.`,`É aprovado exclusivamente para equinos.`,`Atua exclusivamente sobre células NK.`,`Não pode ser associado a outros antivirais.`],resposta_correta:`A`,explicacao:`IFN-ω induz estado antiviral, ativa células NK e macrófagos, e modula resposta imune.`,explicacoes_alternativas:{A:`Correto. IFN-ω induz proteínas antivirais, ativa células NK e modula resposta Th1/Th2.`,B:`Incorreto. Pode causar febre, mialgia e leucopenia em doses elevadas.`,C:`Incorreto. Utilizado em cães (parvovirose) e gatos (FIV, FeLV, PIF).`,D:`Incorreto. Atua sobre múltiplos tipos celulares.`,E:`Incorreto. Pode ser associado a antivirais.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Day MJ`,titulo:`Clinical Immunology of the Dog and Cat`,ano:2012}]},{id:`farm-140`,banca:`IBFC`,ano:2022,prova:`IBFC — Analista Agropecuário 2022`,tipo:`concurso`,topico:`imunofarmacologia`,subtopico:`Terapia imunomoduladora`,dificuldade:`facil`,enunciado:`Sobre imunoterapia em Medicina Veterinária, analise as afirmativas e assinale a CORRETA:`,alternativas:[`Vacinas autógenas podem ser utilizadas como imunoterapia específica em condições alérgicas em cães.`,`Os imunossupressores não podem ser associados, pois seus efeitos são sempre antagônicos.`,`A terapia com IVIG não possui indicação na Medicina Veterinária.`,`Os imunomoduladores não devem ser utilizados em doenças autoimunes.`,`A imunoterapia com células dendríticas não é utilizada em oncologia veterinária.`],resposta_correta:`A`,explicacao:`Vacinas autógenas com alérgenos específicos podem ser usadas em imunoterapia (dessensibilização) para dermatite atópica.`,explicacoes_alternativas:{A:`Correto. Imunoterapia alérgeno-específica utiliza vacinas com alérgenos identificados.`,B:`Incorreto. Imunossupressores frequentemente são associados em protocolos combinados.`,C:`Incorreto. IVIG é utilizada em doenças imunomediadas graves.`,D:`Incorreto. Imunomoduladores são pilares do tratamento de doenças autoimunes.`,E:`Incorreto. Vacinas de células dendríticas estão em uso na oncologia veterinária.`},referencias:[{autores:`Day MJ`,titulo:`Clinical Immunology of the Dog and Cat`,ano:2012},{autores:`Olivry T`,titulo:`Atopic Dermatitis in Dogs`,ano:2020}]},{id:`farm-141`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`antineoplasicos`,subtopico:`Antraciclinas`,dificuldade:`dificil`,enunciado:`A doxorrubicina é um quimioterápico antineoplásico. Sobre seu mecanismo e toxicidade, assinale a CORRETA:`,alternativas:[`A doxorrubicina atua por intercalação no DNA, inibição da topoisomerase II e geração de radicais livres. Seu principal efeito adverso é a cardiotoxicidade.`,`Não apresenta cardiotoxicidade cumulativa.`,`É administrada exclusivamente por via oral.`,`Não causa imunossupressão.`,`Não causa alopecia em cães.`],resposta_correta:`A`,explicacao:`Doxorrubicina intercala no DNA, inibe topoisomerase II e gera radicais livres. Cardiotoxicidade é dose-limitante.`,explicacoes_alternativas:{A:`Correto. Mecanismo triplo; cardiotoxicidade é dose-dependente e cumulativa.`,B:`Incorreto. Cardiotoxicidade cumulativa com limite de dose (~240 mg/m²).`,C:`Incorreto. Administrada exclusivamente por via endovenosa.`,D:`Incorreto. Causa mielossupressão significativa (nadir 7-14 dias).`,E:`Incorreto. Alopecia é frequente em cães.`},referencias:[{autores:`Withrow SJ, Vail DM, Page RL`,titulo:`Small Animal Clinical Oncology`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-142`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`antineoplasicos`,subtopico:`Alquilantes`,dificuldade:`medio`,enunciado:`A ciclofosfamida é um agente alquilante. Sobre suas características, assinale a alternativa INCORRETA:`,alternativas:[`É pró-fármaco ativado no fígado pelo CYP450, gerando fosforamida mostarda e acroleína.`,`A cistite hemorrágica é causada pela acroleína, prevenível com hiper-hidratação.`,`É utilizada em protocolos para linfoma, leucemia e mastocitoma.`,`Não causa mielossupressão, sendo segura em pacientes com função medular comprometida.`,`Pode ser administrada por via oral ou endovenosa.`],resposta_correta:`D`,explicacao:`Alternativa D é INCORRETA. Ciclofosfamida causa mielossupressão significativa.`,explicacoes_alternativas:{A:`Correto. Pró-fármaco ativado no fígado.`,B:`Correto. Acroleína causa cistite hemorrágica; hiper-hidratação previne.`,C:`Correto. Componente de protocolos COP, CHOP.`,D:`Incorreto. Causa mielossupressão dose-dependente (nadir 7-10 dias).`,E:`Correto. Formulações oral e IV disponíveis.`},referencias:[{autores:`Withrow SJ, Vail DM`,titulo:`Small Animal Clinical Oncology`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-143`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Analista CEASA 2023`,tipo:`concurso`,topico:`antineoplasicos`,subtopico:`Alcaloides da vinca`,dificuldade:`medio`,enunciado:`A vincristina é um alcaloide da vinca rosa. Sobre seu mecanismo, assinale a CORRETA:`,alternativas:[`A vincristina liga-se à tubulina, impedindo a polimerização dos microtúbulos e bloqueando a célula na metáfase.`,`Inibe a topoisomerase I, impedindo a replicação do DNA.`,`Não causa neurotoxicidade periférica.`,`É administrada exclusivamente por via intratecal.`,`É um antimetabólito que inibe a diidrofolato redutase.`],resposta_correta:`A`,explicacao:`Vincristina liga-se à β-tubulina, impedindo polimerização dos microtúbulos, bloqueando células em metáfase.`,explicacoes_alternativas:{A:`Correto. Liga-se ao sítio da tubulina, impedindo montagem do fuso mitótico.`,B:`Incorreto. Inibidores de topoisomerase I são as camptotecinas.`,C:`Incorreto. Neurotoxicidade periférica é efeito dose-limitante.`,D:`Incorreto. Administrada IV; intratecal é FATAL e CONTRAINDICADA.`,E:`Incorreto. É alcaloide da vinca, não antimetabólito.`},referencias:[{autores:`Withrow SJ, Vail DM`,titulo:`Small Animal Clinical Oncology`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-144`,banca:`CONSULPLAN`,ano:2023,prova:`CONSULPLAN — Técnico MAPA 2023`,tipo:`concurso`,topico:`antineoplasicos`,subtopico:`Nitrosuréias`,dificuldade:`dificil`,enunciado:`A lomustina (CCNU) é uma nitrosuréia. Sobre suas características, é CORRETO:`,alternativas:[`A lomustina é lipofílica e atravessa a BHE, sendo utilizada para tumores do SNC em cães.`,`Não causa hepatotoxicidade.`,`Mielossupressão não é cumulativa.`,`É administrada exclusivamente por via endovenosa.`,`Não pode ser associada a outros quimioterápicos.`],resposta_correta:`A`,explicacao:`Lomustina é altamente lipofílica, atravessa a BHE, sendo opção para tumores do SNC.`,explicacoes_alternativas:{A:`Correto. Lipofílica, atinge concentrações terapêuticas no SNC.`,B:`Incorreto. Hepatotoxicidade é efeito adverso significativo.`,C:`Incorreto. Mielossupressão é cumulativa e dose-limitante.`,D:`Incorreto. Disponível em cápsulas orais.`,E:`Incorreto. Frequentemente associada a outros agentes.`},referencias:[{autores:`Withrow SJ, Vail DM`,titulo:`Small Animal Clinical Oncology`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-145`,banca:`AOCP`,ano:2022,prova:`AOCP — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`antineoplasicos`,subtopico:`Protocolos quimioterápicos`,dificuldade:`facil`,enunciado:`Sobre protocolos de quimioterapia em oncologia veterinária, assinale a CORRETA:`,alternativas:[`O protocolo COP (ciclofosfamida, vincristina, prednisona) é utilizado para linfoma multicêntrico em cães.`,`As doses veterinárias são idências às doses humanas.`,`A quimioterapia tem como objetivo cura completa em todos os casos.`,`Não requer monitoramento hematológico prévio.`,`Protocolos não podem ser adaptados individualmente.`],resposta_correta:`A`,explicacao:`COP é protocolo clássico para linfoma canino.`,explicacoes_alternativas:{A:`Correto. COP é protocolo clássico; outros incluem CHOP e CCNU.`,B:`Incorreto. Veterinários usam doses reduzidas para minimizar efeitos adversos.`,C:`Incorreto. Objetivo principal é qualidade de vida e sobrevida.`,D:`Incorreto. Hemograma é obrigatório antes de cada ciclo.`,E:`Incorreto. Doses e protocolos são adaptados conforme resposta.`},referencias:[{autores:`Withrow SJ, Vail DM`,titulo:`Small Animal Clinical Oncology`,ano:2019},{autores:`Vail DM`,titulo:`Veterinary Medical Oncology`,ano:2020}]},{id:`farm-146`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário MAPA 2023`,tipo:`concurso`,topico:`hematologicos`,subtopico:`Eritropoetina`,dificuldade:`medio`,enunciado:`A eritropoetina recombinante (rHuEPO) é utilizada para anemias. Sobre seu uso, assinale a CORRETA:`,alternativas:[`A eritropoetina estimula a eritropoiese por ligação a receptores EPO em progenitores eritróides, sendo utilizada na anemia de DRC.`,`Não apresenta efeitos adversos significativos.`,`Não induz formação de anticorpos anti-EPO.`,`É contraindicada em cães e gatos.`,`Não necessita de reposição de ferro.`],resposta_correta:`A`,explicacao:`EPO liga-se a receptores em progenitores eritróides, estimulando eritropoiese. Utilizada na anemia de DRC.`,explicacoes_alternativas:{A:`Correto. Ativa via JAK-STAT nos progenitores eritróides.`,B:`Incorreto. Pode causar hipertensão e formação de anticorpos.`,C:`Incorreto. Anticorpos anti-EPO podem se desenvolver.`,D:`Incorreto. Utilizada em cães e gatos com DRC.`,E:`Incorreto. Reposição de ferro é essencial.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Polzin DJ`,titulo:`Chronic Kidney Disease in Small Animals`,ano:2020}]},{id:`farm-147`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBGE 2022`,tipo:`concurso`,topico:`hematologicos`,subtopico:`Anticoagulantes — heparinas`,dificuldade:`dificil`,enunciado:`A heparina sódica e a enoxaparina são anticoagulantes. Sobre seus mecanismos, assinale a CORRETA:`,alternativas:[`A heparina potencializa a antitrombina III, inativando trombina (IIa) e fator Xa.`,`A heparina inibe diretamente a vitamina K epóxido redutase.`,`A enoxaparina inibe apenas o fator Xa, sem efeito sobre trombina.`,`A heparina não apresenta risco de sangramento.`,`Heparina e enoxaparina são administradas exclusivamente por via endovenosa.`],resposta_correta:`A`,explicacao:`Heparina potencializa AT-III, que inativa serino-proteases da cascata (principalmente IIa e Xa).`,explicacoes_alternativas:{A:`Correto. Heparina liga-se à AT-III, acelerando 1000x a inativação de IIa e Xa.`,B:`Incorreto. Inibição de vitamina K epóxido redutase é mecanismo da varfarina.`,C:`Parcialmente correto, mas A é mais completo. HBPM inibe predominantemente Xa.`,D:`Incorreto. Apresenta risco significativo de sangramento.`,E:`Incorreto. Enoxaparina é SC; heparina pode ser IV ou SC.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Brooks MB`,titulo:`Hemostatic Disorders in Small Animals`,ano:2019}]},{id:`farm-148`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`hematologicos`,subtopico:`Anticoagulantes orais`,dificuldade:`medio`,enunciado:`A varfarina é antagonista da vitamina K. Sobre seu mecanismo, assinale a CORRETA:`,alternativas:[`A varfarina inibe a vitamina K epóxido redutase, impedindo a regeneração da vitamina K ativa.`,`Atua potencializando a antitrombina III.`,`Tem início de ação rápido (2-4 horas).`,`Não interage com outros fármacos ou alimentos.`,`O efeito é revertido com protamina sulfato.`],resposta_correta:`A`,explicacao:`Varfarina inibe VKORC1, impedindo regeneração da vitamina K ativa necessária para carboxilação dos fatores II, VII, IX, X.`,explicacoes_alternativas:{A:`Correto. Inibe VKORC1, bloqueando conversão de vitamina K epóxido em forma ativa.`,B:`Incorreto. Potencialização de AT-III é mecanismo das heparinas.`,C:`Incorreto. Início lento (3-5 dias).`,D:`Incorreto. Interage com AINEs, antimicrobianos, anticonvulsivantes e alimentos ricos em vitamina K.`,E:`Incorreto. Antídoto é vitamina K1 (fitomenadiona). Protamina reverte heparina.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Brooks MB`,titulo:`Hemostatic Disorders in Small Animals`,ano:2019}]},{id:`farm-149`,banca:`AOCP`,ano:2023,prova:`AOCP — Veterinário SUS 2023`,tipo:`concurso`,topico:`hematologicos`,subtopico:`Antifibrinolíticos`,dificuldade:`medio`,enunciado:`O ácido tranexâmico é um antifibrinolítico. Sobre seu mecanismo, é CORRETO:`,alternativas:[`Inibe competitivamente a ativação do plasminogênio em plasmina, prevenindo degradação de fibrina.`,`Atua como agonista do plasminogênio, acelerando a fibrinólise.`,`Não é eficaz para hemorragias perioperatórias em cães.`,`Não pode ser associado ao ácido aminocaproico.`,`É contraindicado em CID.`],resposta_correta:`A`,explicacao:`Ácido tranexâmico é análogo da lisina que liga-se ao plasminogênio, impedindo conversão em plasmina.`,explicacoes_alternativas:{A:`Correto. Compete pelo sítio de ligação à lisina do plasminogênio.`,B:`Incorreto. É inibidor, não agonista.`,C:`Incorreto. Eficaz em hemorragias perioperatórias.`,D:`Incorreto. Pode ser associado.`,E:`Incorreto. Em CID com hiperfibrinólise pode ser considerado.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Brooks MB`,titulo:`Hemostatic Disorders in Small Animals`,ano:2019}]},{id:`farm-150`,banca:`IBFC`,ano:2022,prova:`IBFC — Analista Agropecuário 2022`,tipo:`concurso`,topico:`hematologicos`,subtopico:`Terapia transfusional`,dificuldade:`facil`,enunciado:`Sobre produtos hemáticos e terapia transfusional, assinale a CORRETA:`,alternativas:[`O sangue total contém glóbulos vermelhos, plaquetas, fatores de coagulação e proteínas plasmáticas.`,`Concentrado de hemácias não é indicado para anemias sem hipoproteinemia.`,`Cães não possuem sistemas de grupos sanguíneos.`,`Gatos possuem apenas um sistema de grupo sanguíneo (A e B).`,`Reações transfusionais são sempre imediatas.`],resposta_correta:`A`,explicacao:`Sangue total contém todos os componentes sanguíneos, indicado para anemia com hipoproteinemia ou coagulopatia.`,explicacoes_alternativas:{A:`Correto. Contém eritrócitos, leucócitos, plaquetas, fatores de coagulação e proteínas plasmáticas.`,B:`Incorreto. Concentrado de hemácias é indicado para anemias sem hipoproteinemia.`,C:`Incorreto. Cães possuem sistema DEA com múltiplos tipos.`,D:`Incorreto. Gatos possuem sistema AB com tipos A, B e AB.`,E:`Incorreto. Reações podem ser imediatas ou tardias (3-14 dias).`},referencias:[{autores:`Wardrop KJ`,titulo:`Transfusion Medicine in Small Animals`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-151`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`dermatologicos`,subtopico:`Ciclosporina tópica`,dificuldade:`medio`,enunciado:`A ciclosporina tópica é utilizada em dermatologia veterinária. Sobre seu uso, assinale a CORRETA:`,alternativas:[`A ciclosporina tópica inibe a calcineurina localmente, reduzindo citocinas inflamatórias, sendo usada para ceratoconjuntivite seca e dermatite atópica.`,`Não possui efeito anti-inflamatório.`,`Não pode ser associada a corticosteroides tópicos.`,`Não apresenta efeitos adversos locais.`,`É contraindicada em gatos por causar glaucoma.`],resposta_correta:`A`,explicacao:`Ciclosporina tópica inibe calcineurina local, reduzindo IL-2 e citocinas pró-inflamatórias.`,explicacoes_alternativas:{A:`Correto. Inibe calcineurina localmente, reduzindo inflamação e ativação de mastócitos.`,B:`Incorreto. Tem potente ação anti-inflamatória.`,C:`Incorreto. Pode ser associada a corticosteroides.`,D:`Incorreto. Pode causar irritação local.`,E:`Incorreto. Utilizada em cães e gatos para KCS.`},referencias:[{autores:`Olivry T`,titulo:`Atopic Dermatitis in Dogs`,ano:2020},{autores:`Gelatt KN`,titulo:`Veterinary Ophthalmology`,ano:2021}]},{id:`farm-152`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`dermatologicos`,subtopico:`Antifúngicos azólicos`,dificuldade:`medio`,enunciado:`Miconazol e cetoconazol são antifúngicos azólicos. Sobre seu mecanismo, assinale a CORRETA:`,alternativas:[`Inibem a 14-α-desmetilase (CYP51), bloqueando conversão de lanosterol em ergosterol.`,`Inibem a síntese de β-1,3-glucano na parede celular fúngica.`,`Não possuem atividade contra leveduras.`,`Cetoconazol oral não apresenta hepatotoxicidade.`,`Miconazol não interage com outros fármacos.`],resposta_correta:`A`,explicacao:`Azólicos inibem CYP51, bloqueando síntese de ergosterol e alterando permeabilidade da membrana fúngica.`,explicacoes_alternativas:{A:`Correto. Inibição de CYP51 impede síntese de ergosterol.`,B:`Incorreto. Inibição de β-glucano é das equinocandinas.`,C:`Incorreto. Azólicos têm amplo espectro: dermatófitos, leveduras, fungos dimórficos.`,D:`Incorreto. Cetoconazol oral é hepatotóxico.`,E:`Incorreto. Interage com ciclosporina, varfarina e outros via CYP450.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Moriello KA`,titulo:`Dermatophytosis in Small Animals`,ano:2019}]},{id:`farm-153`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`dermatologicos`,subtopico:`Terbinafina`,dificuldade:`medio`,enunciado:`A terbinafina é um antifúngico alilamínico. Sobre seu mecanismo, é CORRETO:`,alternativas:[`Inibe a esqualeno epoxidase, bloqueando síntese de ergosterol e causando acúmulo de esqualeno citotóxico.`,`Não possui atividade contra dermatófitos.`,`Não apresenta hepatotoxicidade.`,`É contraindicada em gatos.`,`Não pode ser associada a azólicos.`],resposta_correta:`A`,explicacao:`Terbinafina inibe esqualeno epoxidase, bloqueando síntese de ergosterol e causando acúmulo de esqualeno (fungicida).`,explicacoes_alternativas:{A:`Correto. Inibe esqualeno epoxidase, causando acúmulo de esqualeno citotóxico.`,B:`Incorreto. É primeira escolha para dermatófitos.`,C:`Incorreto. Pode causar hepatotoxicidade.`,D:`Incorreto. Segura e eficaz em gatos.`,E:`Incorreto. Pode ser associada a azólicos.`},referencias:[{autores:`Moriello KA`,titulo:`Dermatophytosis in Small Animals`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-154`,banca:`CONSULPLAN`,ano:2022,prova:`CONSULPLAN — Técnico MAPA 2022`,tipo:`concurso`,topico:`dermatologicos`,subtopico:`Tratamento de Malassezia`,dificuldade:`facil`,enunciado:`Sobre tratamento da dermatite por Malassezia, é CORRETO:`,alternativas:[`Cetoconazol e itraconazol são azólicos eficazes no tratamento sistêmico da dermatite por Malassezia.`,`Malassezia não é responsiva a nenhum antifúngico.`,`Miconazol tópico não é eficaz contra Malassezia.`,`Terbinafina não possui atividade contra Malassezia.`,`Dermatite por Malassezia não pode ser tratada com antifúngicos sistêmicos.`],resposta_correta:`A`,explicacao:`Itraconazol e cetoconazol são primeira escolha para Malassezia sistêmica.`,explicacoes_alternativas:{A:`Correto. Itraconazol e cetoconazol são primeira escolha.`,B:`Incorreto. Malassezia é sensível a múltiplos antifúngicos.`,C:`Incorreto. Miconazol tópico é eficaz.`,D:`Incorreto. Terbinafina tem atividade contra Malassezia.`,E:`Incorreto. Recorrente ou generalizada requer tratamento sistêmico.`},referencias:[{autores:`Morris DO`,titulo:`Malassezia Dermatitis in Dogs`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-155`,banca:`AOCP`,ano:2023,prova:`AOCP — Veterinário SUS 2023`,tipo:`concurso`,topico:`dermatologicos`,subtopico:`Antifúngicos tópicos`,dificuldade:`facil`,enunciado:`Sobre antifúngicos tópicos em dermatologia veterinária, assinale a CORRETA:`,alternativas:[`A nistatina é poliênico que se liga ao ergosterol, formando poros que aumentam a permeabilidade celular.`,`A nistatina é absorvida sistemicamente após aplicação tópica.`,`A griseofulvina é antifúngico tópico de primeira escolha.`,`O clotrimazol não possui atividade contra dermatófitos.`,`A anfotericina B tópica é amplamente utilizada.`],resposta_correta:`A`,explicacao:`Nistatina liga-se ao ergosterol, formando poros transmembrânicos que causam morte fúngica.`,explicacoes_alternativas:{A:`Correto. Liga-se ao ergosterol, formando canais iônicos que aumentam permeabilidade.`,B:`Incorreto. Não é absorvida por pele ou mucosas intactas.`,C:`Incorreto. Griseofulvina é administrada por via oral (sistêmica).`,D:`Incorreto. Clotrimazol tem amplo espectro.`,E:`Incorreto. Anfotericina B é administrada IV.`},referencias:[{autores:`Moriello KA`,titulo:`Dermatophytosis in Small Animals`,ano:2019},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-156`,banca:`CESPE`,ano:2023,prova:`CESPE — Veterinário MAPA 2023`,tipo:`concurso`,topico:`oftalmicos`,subtopico:`Antiglaucomatosos betabloqueadores`,dificuldade:`medio`,enunciado:`O timolol é betabloqueador não seletivo para glaucoma. Sobre seu uso, assinale a CORRETA:`,alternativas:[`O timolol reduz a PIO por diminuição da produção de humor aquoso, via bloqueio beta-2 nos processos ciliares.`,`Não apresenta efeitos sistêmicos significativos.`,`É contraindicado em todos os animais com glaucoma.`,`Não pode ser associado à dorzolamida.`,`Aumenta a drenagem do humor aquoso via malha trabecular.`],resposta_correta:`A`,explicacao:`Timolol reduz PIO por diminuição da produção de humor aquoso via bloqueio beta-2 nos processos ciliares.`,explicacoes_alternativas:{A:`Correto. Bloqueia receptores beta-2, reduzindo produção de humor aquoso.`,B:`Incorreto. Pode causar bradicardia e broncoespasmo por absorção sistêmica.`,C:`Incorreto. Indicado para glaucoma canino e felino.`,D:`Incorreto. Combinação timolol + dorzolamida é frequentemente utilizada.`,E:`Incorreto. Reduz produção, não drenagem.`},referencias:[{autores:`Gelatt KN`,titulo:`Veterinary Ophthalmology`,ano:2021},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-157`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBGE 2022`,tipo:`concurso`,topico:`oftalmicos`,subtopico:`Inibidores da anidrase carbônica tópicos`,dificuldade:`medio`,enunciado:`A dorzolamida é inibidor da anidrase carbônica tópica para glaucoma. Sobre seu mecanismo, assinale a CORRETA:`,alternativas:[`Inibe a anidrase carbônica nos processos ciliares, reduzindo secreção de bicarbonato e produção de humor aquoso.`,`Aumenta a drenagem do humor aquoso via malha trabecular.`,`Não apresenta efeitos adversos oculares.`,`Não pode ser associada ao timolol.`,`É contraindicada em cães por causar uveíte.`],resposta_correta:`A`,explicacao:`Dorzolamida inibe CA-II nos processos ciliares, reduzindo produção de HCO3- e secreção de humor aquoso.`,explicacoes_alternativas:{A:`Correto. Inibe CA-II, reduzindo produção de bicarbonato e humor aquoso em ~20%.`,B:`Incorreto. Reduz produção, não drenagem.`,C:`Incorreto. Pode causar ardência e hiperemia.`,D:`Incorreto. Combinação dorzolamida + timolol (Cosopt®) é amplamente utilizada.`,E:`Incorreto. Segura e indicada para glaucoma em cães e gatos.`},referencias:[{autores:`Gelatt KN`,titulo:`Veterinary Ophthalmology`,ano:2021},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-158`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Analista CEASA 2023`,tipo:`concurso`,topico:`oftalmicos`,subtopico:`Midriáticos e mióticos`,dificuldade:`dificil`,enunciado:`A pilocarpina e a atropina possuem ações opostas. Sobre seus mecanismos, é CORRETO:`,alternativas:[`A pilocarpina é agonista muscarínico que causa miose e facilita drenagem do humor aquoso, sendo utilizada no glaucoma.`,`A atropina é agonista muscarínico que causa midríase e cicloplegia.`,`A pilocarpina não apresenta efeitos sistêmicos significativos.`,`A atropina oftálmica não causa efeitos sistêmicos anticolinérgicos.`,`Pilocarpina e atropina podem ser utilizadas concomitantemente.`],resposta_correta:`A`,explicacao:`Pilocarpina é agonista muscarínico que causa miose, abrindo o ângulo iridocorneano e facilitando drenagem.`,explicacoes_alternativas:{A:`Correto. Ativa M3 no esfíncter pupilar, causando miose e facilitando drenagem.`,B:`Incorreto. Atropina é antagonista muscarínico (não agonista).`,C:`Incorreto. Pode causar sialorreia, bradicardia e diarreia por absorção sistêmica.`,D:`Incorreto. Pode ser absorvida sistemicamente.`,E:`Incorreto. São antagônicas e não devem ser usadas concomitantemente.`},referencias:[{autores:`Gelatt KN`,titulo:`Veterinary Ophthalmology`,ano:2021},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-159`,banca:`AOCP`,ano:2022,prova:`AOCP — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`oftalmicos`,subtopico:`Análogos de prostaglandinas`,dificuldade:`medio`,enunciado:`Os análogos de prostaglandinas (latanoprosta, travoprosta) são utilizados no glaucoma. Sobre seu mecanismo, assinale a CORRETA:`,alternativas:[`Aumentam a drenagem do humor aquoso via uveoescleral, sendo de primeira escolha para glaucoma em cães.`,`Reduzem a produção de humor aquoso nos processos ciliares.`,`Não apresentam efeitos adversos oculares.`,`São contraindicados em gatos.`,`Não podem ser associados a outros antiglaucomatosos.`],resposta_correta:`A`,explicacao:`Análogos de PGF2α aumentam drenagem pela via uveoescleral, sendo primeira escolha para glaucoma canino.`,explicacoes_alternativas:{A:`Correto. Aumentam saída de humor aquoso pela via uveoescleral, reduzindo PIO em 25-35%.`,B:`Incorreto. Aumentam drenagem, não reduzem produção.`,C:`Incorreto. Causam hiperemia e melanose da íris.`,D:`Incorreto. Seguras em gatos.`,E:`Incorreto. Podem ser associados a timolol e dorzolamida.`},referencias:[{autores:`Gelatt KN`,titulo:`Veterinary Ophthalmology`,ano:2021},{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023}]},{id:`farm-160`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`farmacologia_dor`,subtopico:`Anticonvulsivantes na dor neuropática`,dificuldade:`medio`,enunciado:`A gabapentina e a pregabalina são usadas na dor neuropática. Sobre seus mecanismos, assinale a CORRETA:`,alternativas:[`Ligam-se à subunidade α2δ dos canais de cálcio voltagem-dependentes, reduzindo liberação de neurotransmissores excitatórios.`,`São agonistas dos receptores GABA-A e GABA-B.`,`A gabapentina não apresenta efeitos como sedação e ataxia.`,`A pregabalina não é eficaz para dor neuropática.`,`Possuem farmacocinética linear com aumento proporcional.`],resposta_correta:`A`,explicacao:`Gabapentina e pregabalina ligam-se à subunidade α2δ dos canais de cálcio, reduzindo liberação de neurotransmissores excitatórios.`,explicacoes_alternativas:{A:`Correto. Ligação à subunidade α2δ reduz influxo de cálcio e liberação de glutamato.`,B:`Incorreto. NÃO atuam em receptores GABA. O mecanismo é via canais de cálcio.`,C:`Incorreto. Pode causar sedação e ataxia.`,D:`Incorreto. Pregabalina é eficaz para dor neuropática.`,E:`Incorreto. Gabapentina apresenta farmacocinética não linear em humanos.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Mathews KA`,titulo:`Pain Management in Veterinary Patients`,ano:2019}]},{id:`farm-161`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`farmacologia_dor`,subtopico:`NMDA antagonistas`,dificuldade:`dificil`,enunciado:`A amantadina é antagonista de receptores NMDA. Sobre seu uso, é CORRETO:`,alternativas:[`Bloqueia receptores NMDA no corno dorsal medular, reduzindo sensibilização central associada à dor crônica.`,`É agonista dos receptores NMDA.`,`Não apresenta efeitos como excitação e tremores.`,`Não pode ser associada a AINEs ou opioides.`,`Não é eficaz para dor neuropática.`],resposta_correta:`A`,explicacao:`Amantadiana antagoniza receptores NMDA no corno dorsal, reduzindo sensibilização central (wind-up).`,explicacoes_alternativas:{A:`Correto. Bloqueia canal iônico NMDA, reduzindo sensibilização central.`,B:`Incorreto. É antagonista, não agonista.`,C:`Incorreto. Pode causar excitação do SNC e ataxia.`,D:`Incorreto. Componente do manejo multimodal.`,E:`Incorreto. Eficaz para dor neuropática e crônica.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Mathews KA`,titulo:`Pain Management in Veterinary Patients`,ano:2019}]},{id:`farm-162`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura SP 2022`,tipo:`concurso`,topico:`farmacologia_dor`,subtopico:`Opioides — tramadol`,dificuldade:`medio`,enunciado:`O tramadol é analgésico opioide de ação central. Sobre seu mecanismo, assinale a CORRETA:`,alternativas:[`O tramadol é pró-fármaco convertido em O-desmetiltramadol (M1), que possui alta afinidade por receptores mu-opioides, além de inibir recaptação de serotonina e noradrenalina.`,`Não apresenta efeitos sobre recaptação de monoaminas.`,`Não causa depressão respiratória em doses terapêuticas.`,`É contraindicado em cães por causar convulsões.`,`O metabólito M1 não é ativo.`],resposta_correta:`A`,explicacao:`Tramadol é pró-fármaco; M1 tem alta afinidade por receptores mu. Tramadol inibe recaptação de 5-HT e NE.`,explicacoes_alternativas:{A:`Correto. M1 é ativo com afinidade 200x maior pelo receptor mu. Inibição de 5-HT/NE contribui.`,B:`Incorreto. Inibe recaptação de serotonina e noradrenalina.`,C:`Incorreto. Pode causar depressão respiratória dose-dependente.`,D:`Incorreto. Seguro e amplamente utilizado em cães.`,E:`Incorreto. M1 é farmacologicamente ativo.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Mathews KA`,titulo:`Pain Management in Veterinary Patients`,ano:2019}]},{id:`farm-163`,banca:`AOCP`,ano:2023,prova:`AOCP — Veterinário SUS 2023`,tipo:`concurso`,topico:`farmacologia_dor`,subtopico:`Manejo multimodal da dor`,dificuldade:`facil`,enunciado:`Sobre o manejo multimodal da dor, assinale a CORRETA:`,alternativas:[`Utiliza combinações de fármacos com diferentes mecanismos (AINEs, opioides, anestésicos locais, gabapentinoides) para analgesia sinérgica com menores doses.`,`É contraindicada na Medicina Veterinária.`,`O uso de um único analgésico em dose máxima é sempre preferível.`,`AINEs e opioides não podem ser associados.`,`Não inclui técnicas não farmacológicas.`],resposta_correta:`A`,explicacao:`Manejo multimodal combina fármacos com diferentes mecanismos, obtendo analgesia sinérgica com doses reduzidas.`,explicacoes_alternativas:{A:`Correto. Recomendado por todas as diretrizes de analgesia veterinária.`,B:`Incorreto. Amplamente recomendado e utilizado.`,C:`Incorreto. Monoterapia em dose máxima aumenta efeitos adversos.`,D:`Incorreto. AINEs e opioides são frequentemente associados.`,E:`Incorreto. Inclui técnicas farmacológicas e não farmacológicas.`},referencias:[{autores:`Mathews KA`,titulo:`Pain Management in Veterinary Patients`,ano:2019},{autores:`Epstein ME`,titulo:`AAHA Pain Management Guidelines`,ano:2018}]},{id:`farm-164`,banca:`IBFC`,ano:2022,prova:`IBFC — Analista Agropecuário 2022`,tipo:`concurso`,topico:`farmacologia_dor`,subtopico:`Anestésicos locais`,dificuldade:`dificil`,enunciado:`Sobre a lidocaína como anestésico local e analgésico sistêmico, assinale a CORRETA:`,alternativas:[`A lidocaína bloqueia canais de sódio voltagem-dependentes, impedindo propagação do impulso nervoso.`,`Não apresenta efeito antiarrítmico.`,`A infusão IV não é eficaz para analgesia em cavalos com cólica.`,`Não apresenta efeitos adversos sobre o SNC.`,`Não pode ser associada a outros anestésicos.`],resposta_correta:`A`,explicacao:`Lidocaína bloqueia canais de sódio, impedindo despolarização e condução do potencial de ação.`,explicacoes_alternativas:{A:`Correto. Liga-se ao sítio intracelular dos canais de Na+, impedindo despolarização.`,B:`Incorreto. É antiarrítmica classe IB.`,C:`Incorreto. É eficaz IV em cavalos e cães.`,D:`Incorreto. Pode causar convulsões e depressão respiratória.`,E:`Incorreto. Frequentemente associada a bupivacaína e opioides.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Skarda RT`,titulo:`Local and Regional Anesthesia in Animals`,ano:2018}]},{id:`farm-165`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`farmacologia_aves`,subtopico:`Fármacos proibidos em aves de produção`,dificuldade:`medio`,enunciado:`Sobre uso de antimicrobianos em aves de produção, é CORRETO:`,alternativas:[`Os nitrofuranos são proibidos em aves de produção no Brasil devido ao potencial carcinogênico.`,`O cloranfenicol é aprovado para uso em aves de produção.`,`Os promotores de crescimento não possuem restrições no Brasil.`,`As fluoroquinolonas são aprovadas para aves de postura sem restrições.`,`As polimixinas não possuem importância clínica para a Medicina Humana.`],resposta_correta:`A`,explicacao:`Nitrofuranos são proibidos em aves de produção devido ao potencial carcinogênico e mutagênico.`,explicacoes_alternativas:{A:`Correto. Nitrofuranos e metabólitos são proibidos por serem potencialmente carcinogênicos.`,B:`Incorreto. Cloranfenicol é proibido em animais de abate.`,C:`Incorreto. Promotores de crescimento são restritos (IN MAPA 77/2018).`,D:`Incorreto. Fluoroquinolonas são altamente restritas.`,E:`Incorreto. Polimixinas são de importância crítica (OMS).`},referencias:[{autores:`MAPA — IN 77/2018`,titulo:`Planos Nacionais de Controle de Resíduos`,ano:2018},{autores:`Palermo-Neto J`,titulo:`Farmacologia Aplicada à Avicultura`,ano:2016}]},{id:`farm-166`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBGE 2022`,tipo:`concurso`,topico:`farmacologia_aves`,subtopico:`Dosagens e vias de administração em aves`,dificuldade:`medio`,enunciado:`Sobre particularidades da farmacologia em aves, assinale a CORRETA:`,alternativas:[`As aves possuem metabolismo mais rápido que mamíferos, necessitando doses proporcionalmente maiores e intervalos mais curtos.`,`As aves não metabolizam fármacos no fígado.`,`A via oral não é utilizada em aves.`,`Os AINEs são seguros em aves sem risco de nefrotoxicidade.`,`As aves possuem vesícula biliar funcional.`],resposta_correta:`A`,explicacao:`Aves possuem metabolismo mais rápido, com meias-vidas mais curtas para muitos fármacos.`,explicacoes_alternativas:{A:`Correto. Metabolismo mais rápido resulta em meias-vidas mais curtas.`,B:`Incorreto. Metabolizam fármacos no fígado.`,C:`Incorreto. Via oral é amplamente utilizada.`,D:`Incorreto. AINEs podem ser nefrotóxicos em aves.`,E:`Incorreto. Maioria das aves não possui vesícula biliar funcional.`},referencias:[{autores:`Carpenter JW`,titulo:`Exotic Animal Formulary`,ano:2023},{autores:`Samour J`,titulo:`Avian Medicine`,ano:2016}]},{id:`farm-167`,banca:`AOCP`,ano:2022,prova:`AOCP — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`farmacologia_aves`,subtopico:`Toxicidade em aves`,dificuldade:`dificil`,enunciado:`Sobre toxicidade de fármacos em aves, analise as afirmativas e assinale a CORRETA:`,alternativas:[`Chumbo e zinco são altamente tóxicos para aves, causando intoxicação por ingestão de objetos metálicos. O tratamento inclui EDTA cálcico-dissódico.`,`Os AINEs são seguros para uso em aves.`,`O abacate não é tóxico para aves.`,`O acetaminofeno não apresenta hepatotoxicidade em aves.`,`Os organofosforados não são tóxicos para aves.`],resposta_correta:`A`,explicacao:`Chumbo e zinco são extremamente tóxicos para aves. EDTA CaNa2 é quelante de escolha.`,explicacoes_alternativas:{A:`Correto. Intoxicação por chumbo e zinco é comum; EDTA CaNa2 é tratamento de escolha.`,B:`Incorreto. AINEs são potencialmente nefrotóxicos em aves.`,C:`Incorreto. Abacate contém persina, tóxica para psitacídeos.`,D:`Incorreto. Paracetamol é hepatotóxico em aves.`,E:`Incorreto. Organofosforados são extremamente tóxicos para aves.`},referencias:[{autores:`Carpenter JW`,titulo:`Exotic Animal Formulary`,ano:2023},{autores:`Lightfoot TL, Yeager JM`,titulo:`Avian Toxicology`,ano:2019}]},{id:`farm-168`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`farmacologia_suinos`,subtopico:`Restrições de antimicrobianos em suínos`,dificuldade:`medio`,enunciado:`Sobre uso de antimicrobianos em suínos de produção, é CORRETO:`,alternativas:[`Os antimicrobianos de importância crítica devem ser utilizados com restrições, seguindo o conceito de uso prudente.`,`O uso de colistina como promotor de crescimento é amplamente recomendado pelo MAPA.`,`As fluoroquinolonas são primeira escolha para infecções respiratórias não complicadas.`,`O uso de carbapenêmicos é aprovado para uso rotineiro em suínos.`,`A gentamicina pode ser utilizada como promotor de crescimento sem restrições.`],resposta_correta:`A`,explicacao:`O uso de antimicrobianos de importância crítica em suínos deve seguir princípios de uso prudente.`,explicacoes_alternativas:{A:`Correto. Conceito One Health e diretrizes MAPA/OMS recomendam uso prudente.`,B:`Incorreto. Colistina é restrita como promotor de crescimento.`,C:`Incorreto. Fluoroquinolonas são antimicrobianos de importância crítica.`,D:`Incorreto. Carbapenêmicos não são aprovados para animais de produção.`,E:`Incorreto. Gentamicina não é promotor de crescimento.`},referencias:[{autores:`MAPA — IN 77/2018`,titulo:`Planos Nacionais de Controle de Resíduos`,ano:2018},{autores:`Giguère S, Prescott JF`,titulo:`Antimicrobial Therapy in Veterinary Medicine`,ano:2013}]},{id:`farm-169`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário IBAMA 2023`,tipo:`concurso`,topico:`farmacologia_suinos`,subtopico:`Ajuste de doses em suínos`,dificuldade:`medio`,enunciado:`Sobre ajuste de doses de fármacos em suínos, assinale a CORRETA:`,alternativas:[`A dose deve considerar peso vivo, via de administração, gravidade da infecção e período de carência.`,`As doses em suínos são idênticas às doses em bovinos.`,`O período de carência não é regulamentado no Brasil.`,`Suínos não metabolizam fármacos de forma diferente de outras espécies.`,`Água medicada não é via eficaz para administração.`],resposta_correta:`A`,explicacao:`O ajuste de doses em suínos deve considerar múltiplos fatores.`,explicacoes_alternativas:{A:`Correto. Cálculo de dose é multifatorial.`,B:`Incorreto. Diferem de bovinos.`,C:`Incorreto. Período de carência é regulamentado pelo MAPA.`,D:`Incorreto. Farmacocinética é específica.`,E:`Incorreto. Água medicada é via muito utilizada.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2023},{autores:`Maes D et al.`,titulo:`Diseases of Swine`,ano:2019}]},{id:`farm-170`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Analista CEASA 2023`,tipo:`concurso`,topico:`farmacologia_suinos`,subtopico:`Resistência antimicrobiana em suínos`,dificuldade:`dificil`,enunciado:`Sobre resistência antimicrobiana em suínos e saúde única (One Health), é CORRETO:`,alternativas:[`O uso inadequado de antimicrobianos em suínos pode selecionar bactérias resistentes que transferem genes de resistência para patógenos humanos.`,`A resistência em suínos não afeta a saúde humana.`,`Programas de vigilância não são necessários.`,`Probióticos como alternativa não possuem evidência científica.`,`A resistência em suínos é exclusivamente por mutações espontâneas.`],resposta_correta:`A`,explicacao:`Uso inadequado seleciona bactérias resistentes que podem transferir genes de resistência para patógenos humanos.`,explicacoes_alternativas:{A:`Correto. Transferência de resistência entre animais e humanos é documentada.`,B:`Incorreto. Bactérias resistentes podem causar infecções em humanos.`,C:`Incorreto. Programas de vigilância são essenciais.`,D:`Incorreto. Probióticos possuem evidências como alternativas.`,E:`Incorreto. Transferência horizontal é o principal mecanismo.`},referencias:[{autores:`WHO`,titulo:`Global Action Plan on Antimicrobial Resistance`,ano:2015},{autores:`MAPA`,titulo:`Plano de Ação Nacional de Resistência aos Antimicrobianos`,ano:2021}]},{id:`farm-171`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`concurso`,topico:`farmacoveterinaria_historia`,subtopico:`Marcos históricos`,dificuldade:`facil`,enunciado:`Sobre os marcos históricos da farmacologia veterinária, assinale a alternativa correta.`,alternativas:[`A) O primeiro antibiótico utilizado em medicina veterinária foi a penicilina, na década de 1930.`,`B) A descoberta da vacina antirrábica por Louis Pasteur, em 1885, é considerada um dos primeiros marcos da imunologia veterinária aplicada.`,`C) A ivermectina foi descoberta em 1960 e revolucionou o controle de parasitas.`,`D) A insulina sintética foi o primeiro hormônio produzido por engenharia genética para uso veterinário exclusivo.`,`E) A anestesia inalatória com éter foi introduzida na medicina veterinária antes de ser utilizada em medicina humana.`],resposta_correta:`B`,explicacao:`Louis Pasteur desenvolveu a vacina antirrábica em 1885, marco fundamental da imunologia veterinária aplicada.`,explicacoes_alternativas:{A:`A penicilina foi descoberta em 1928 e utilizada em humanos na década de 1940.`,B:`Correta. Pasteur desenvolveu a vacina antirrábica em 1885.`,C:`A ivermectina foi descoberta em 1975 por Ōmura e Campbell.`,D:`A insulina recombinante foi desenvolvida primariamente para uso humano.`,E:`A anestesia com éter foi primeiro utilizada em medicina humana (1846).`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-172`,banca:`VUNESP`,ano:2019,prova:`VUNESP — Concurso 2019`,tipo:`concurso`,topico:`farmacoveterinaria_historia`,subtopico:`Desenvolvimento de fármacos`,dificuldade:`medio`,enunciado:`Claude Bernard, no século XIX, contribuiu significativamente para a farmacologia veterinária. Assinale a alternativa correta:`,alternativas:[`A) Claude Bernard demonstrou o mecanismo de ação do curare na junção neuromuscular.`,`B) Alexander Fleming descobriu a penicilina em 1940 para uso veterinário.`,`C) Paul Ehrlich desenvolveu o salvarsan exclusivamente para uso veterinário.`,`D) Robert Koch descobriu a tuberculina exclusivamente para animais.`,`E) Rudolf Virchow formulou a teoria celular apenas para patologia humana.`],resposta_correta:`A`,explicacao:`Claude Bernard demonstrou o efeito do curare na placa motora terminal, contribuindo para o desenvolvimento dos bloqueadores neuromusculares.`,explicacoes_alternativas:{A:`Correta. Claude Bernard demonstrou o mecanismo de ação do curare.`,B:`Fleming descobriu a penicilina em 1928.`,C:`O salvarsan foi para sífilis em humanos.`,D:`A tuberculina tem aplicação humana e veterinária.`,E:`Virchow contribuiu para patologia comparada.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-173`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`farmacoveterinaria_historia`,subtopico:`Farmacovigilância veterinária`,dificuldade:`medio`,enunciado:`Sobre a farmacovigilância veterinária, é correto afirmar:`,alternativas:[`A) Teve início no Brasil na década de 1990 sem relação internacional.`,`B) O VICH foi criado para harmonizar requisitos regulatórios de medicamentos veterinários entre diferentes países.`,`C) No Brasil, é coordenada exclusivamente pelo Ministério da Saúde.`,`D) A notificação é obrigatória apenas para médicos humanos.`,`E) O conceito de TGI não faz parte dos protocolos.`],resposta_correta:`B`,explicacao:`O VICH (1996) harmoniza requisitos regulatórios para medicamentos veterinários entre UE, Japão e EUA.`,explicacoes_alternativas:{A:`Influenciada por movimentos internacionais.`,B:`Correta. VICH harmoniza requisitos regulatórios.`,C:`Envolve MAPA e ANVISA.`,D:`Responsabilidade dos médicos-veterinários.`,E:`TGI é fundamental na farmacovigilância.`},referencias:[{autores:`VICH Secretariat`,titulo:`History of the VICH Process`,ano:2018}]},{id:`farm-174`,banca:`CESPE/CEBRASPE`,ano:2018,prova:`CESPE — Concurso MAPA 2018`,tipo:`concurso`,topico:`farmacoveterinaria_historia`,subtopico:`Regulamentação`,dificuldade:`dificil`,enunciado:`Analise as afirmativas sobre regulamentação de medicamentos veterinários no Brasil:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,explicacao:`Afirmativa I é VERDADEIRA (Lei 5.991/1973), II é FALSA (MAPA mantém competência), III é VERDADEIRA (Decreto 8.077/2013). Resultado: V-F-V.`,explicacoes_alternativas:{A:`Sequência correta é V-F-V.`,B:`Incorreta.`,C:`Incorreta.`,D:`Incorreta.`,E:`Incorreta.`},referencias:[{autores:`Brasil`,titulo:`Lei Federal nº 5.991/1973`,ano:1973}],vf:!0,vf_texto:`( ) A Lei 5.991/1973 é marco regulatório para medicamentos veterinários no Brasil.
( ) A ANVISA substituiu integralmente o MAPA no registro de medicamentos veterinários.
( ) O Decreto 8.077/2013 regulamenta atividades de promoção e comercialização de medicamentos veterinários.`},{id:`farm-175`,banca:`UNESP`,ano:2017,prova:`UNESP — Prova de Título 2017`,tipo:`prova_titular`,topico:`farmacoveterinaria_historia`,subtopico:`Farmacopeia veterinária`,dificuldade:`medio`,enunciado:`Sobre a Farmacopeia Veterinária Brasileira, assinale a alternativa correta:`,alternativas:[`A) Inclui monografias exclusivamente de uso humano.`,`B) A primeira edição foi publicada em 2002, estabelecendo padrões de qualidade para medicamentos veterinários.`,`C) Não contempla métodos analíticos para controle de qualidade.`,`D) É publicada exclusivamente pela ANVISA.`,`E) A harmonização é coordenada exclusivamente pela OMS.`],resposta_correta:`B`,explicacao:`A Farmacopeia Veterinária Brasileira foi publicada em 2002.`,explicacoes_alternativas:{A:`Contempla medicamentos humanos e veterinários.`,B:`Correta. Primeira edição de 2002.`,C:`Inclui métodos analíticos.`,D:`Publicada pelo MAPA.`,E:`Envolve PDG e VICH.`},referencias:[{autores:`Farmacopeia Veterinária Brasileira`,titulo:`Farmacopeia Veterinária Brasileira — 1ª Edição`,ano:2002}]},{id:`farm-176`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`farmacos_autonomos`,subtopico:`Colinérgicos`,dificuldade:`medio`,enunciado:`A neostigmina é um inibidor da acetilcolinesterase. Sobre seu mecanismo de ação, é correto afirmar:`,alternativas:[`A) É inibidor irreversível da AChE.`,`B) Inibe reversivelmente a AChE, aumentando acetilcolina na fenda sináptica, utilizada para reverter bloqueios neuromusculares não-despolarizantes.`,`C) Atravessa facilmente a BHE.`,`D) Possui ação exclusivamente muscarínica.`,`E) É contraindicada em íleo paralítico.`],resposta_correta:`B`,explicacao:`Neostigmina é inibidor reversível da AChE, usada para reverter bloqueios neuromusculares não-despolarizantes.`,explicacoes_alternativas:{A:`É inibidora reversível.`,B:`Correta. Inibe reversivelmente a AChE.`,C:`Possui carga quaternária, não atravessa BHE.`,D:`Possui efeitos muscarínicos e nicotínicos.`,E:`Estimula motilidade GI.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-177`,banca:`CESPE/CEBRASPE`,ano:2020,prova:`CESPE — Concurso 2020`,tipo:`concurso`,topico:`farmacos_autonomos`,subtopico:`Anticolinérgicos`,dificuldade:`medio`,enunciado:`A atropina é antagonista competitivo dos receptores muscarínicos. Sobre seus efeitos, é correto afirmar:`,alternativas:[`A) É agonista competitivo muscarínico.`,`B) É antagonista competitivo muscarínico, causando midríase, taquicardia, redução das secreções e broncodilatação.`,`C) Bloqueia seletivamente receptores nicotínicos.`,`D) Estimula a acetilcolinesterase.`,`E) Possui efeito exclusivo sobre o SNC.`],resposta_correta:`B`,explicacao:`Atropina é antagonista competitivo muscarínico com efeitos midriático, cronotrópico positivo, antissialagogo e broncodilatador.`,explicacoes_alternativas:{A:`É antagonista, não agonista.`,B:`Correta. Antagonista competitivo muscarínico.`,C:`Bloqueia muscarínicos, não nicotínicos.`,D:`Não estimula AChE.`,E:`Possui efeitos periféricos significativos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-178`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso 2022`,tipo:`concurso`,topico:`farmacos_autonomos`,subtopico:`Adrenérgicos`,dificuldade:`dificil`,enunciado:`A epinefrina é um fármaco adrenérgico. Sobre sua farmacologia, é INCORRETO afirmar:`,alternativas:[`A) É agonista não-seletivo alfa/beta.`,`B) É primeira escolha na anafilaxia.`,`C) Em doses baixas, predomina ativação beta-1.`,`D) Administrada IV, possui meia-vida plasmática longa (acima de 30 minutos).`,`E) É utilizada como adjuvante em anestésicos locais.`],resposta_correta:`D`,explicacao:`A epinefrina IV possui meia-vida muito curta (1-3 minutos).`,explicacoes_alternativas:{A:`Correta. Agonista não-seletiva.`,B:`Correta. Primeira escolha na anafilaxia.`,C:`Correta. Em doses baixas predominam beta.`,D:`INCORRETA. Meia-vida de 1-3 minutos.`,E:`Correta. Adjuvante em anestésicos locais.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-179`,banca:`FCC`,ano:2019,prova:`FCC — Concurso 2019`,tipo:`concurso`,topico:`farmacos_autonomos`,subtopico:`Adrenérgicos`,dificuldade:`medio`,enunciado:`A norepinefrina difere da epinefrina. Assinale a alternativa correta:`,alternativas:[`A) É agonista seletivo beta-2.`,`B) Possui afinidade predominante pelos receptores alfa-1, causando vasoconstrição intensa.`,`C) Possui o mesmo perfil que a epinefrina.`,`D) É primeira escolha na anafilaxia.`,`E) Não interfere na pressão diastólica.`],resposta_correta:`B`,explicacao:`Norepinefrina é predominantemente alfa-1 agonista, causando vasoconstrição intensa.`,explicacoes_alternativas:{A:`É predominantemente alfa-1.`,B:`Correta. Predominantemente alfa-1.`,C:`Diferem significativamente.`,D:`Epinefrina é primeira escolha.`,E:`Aumenta sistólica e diastólica.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-180`,banca:`UFRGS`,ano:2020,prova:`UFRGS — Residência 2020`,tipo:`residencia`,topico:`farmacos_autonomos`,subtopico:`Anticolinérgicos`,dificuldade:`dificil`,enunciado:`Em relação à atropina como pré-anestésico, analise as afirmativas:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,explicacao:`Todas as afirmativas são verdadeiras.`,explicacoes_alternativas:{A:`Correta. Todas verdadeiras.`,B:`Incorreta.`,C:`Incorreta.`,D:`Incorreta.`,E:`Incorreta.`},referencias:[{autores:`Thurmon JC et al.`,titulo:`Lumb & Jones' Veterinary Anesthesia`,ano:2015}],vf:!0,vf_texto:`( ) Reduz secreções e previne bradicardia vagal.
( ) Em gatos, pode causar taquicardia mais intensa que em cães.
( ) É contraindicada em glaucoma de ângulo fechado.`},{id:`farm-181`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`concurso`,topico:`farmacos_snc`,subtopico:`Benzodiazepínicos`,dificuldade:`medio`,enunciado:`O diazepam se liga ao sítio das benzodiazepinas no GABA-A. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É agonista direto do GABA-A.`,`B) Aumenta a frequência de abertura do canal de cloreto, potencializando o GABA.`,`C) Bloqueia receptores NMDA.`,`D) Inibe recaptação de GABA.`,`E) Antagoniza receptores de glicina.`],resposta_correta:`B`,explicacao:`Diazepam aumenta frequência de abertura do canal de cloreto via potenciação do GABA.`,explicacoes_alternativas:{A:`Potencializa GABA, não o substitui.`,B:`Correta. Aumenta frequência de abertura do canal.`,C:`Não atua em NMDA.`,D:`Não inibe recaptação de GABA.`,E:`Não atua em glicina.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-182`,banca:`CESPE/CEBRASPE`,ano:2021,prova:`CESPE — Concurso 2021`,tipo:`concurso`,topico:`farmacos_snc`,subtopico:`Barbitúricos`,dificuldade:`medio`,enunciado:`O fenobarbital potencializa o GABA-A prolongando o tempo de abertura do canal de cloreto. Sobre sua farmacologia, é correto afirmar:`,alternativas:[`A) É barbitúrico de ação ultracurta.`,`B) Possui longa meia-vida em cães (40-90 horas).`,`C) É metabolizado exclusivamente por conjugação.`,`D) Não apresenta efeitos hepáticos em uso crônico.`,`E) É contraindicado em gatos em todas as doses.`],resposta_correta:`B`,explicacao:`Fenobarbital tem meia-vida longa em cães (40-90 horas), permitindo BID.`,explicacoes_alternativas:{A:`É de ação longa.`,B:`Correta. Meia-vida 40-90 horas em cães.`,C:`Metabolizado via CYP450.`,D:`Pode causar hepatotoxicidade crônica.`,E:`Pode ser usado em gatos com cautela.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-183`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso 2020`,tipo:`concurso`,topico:`farmacos_snc`,subtopico:`Antiepilépticos`,dificuldade:`dificil`,enunciado:`Fenitoína e valproato possuem mecanismos distintos. Assinale a correta:`,alternativas:[`A) Ambos atuam exclusivamente como potencializadores do GABA-A.`,`B) Fenitoína bloqueia canais de Na⁺; valproato tem múltiplos mecanismos incluindo bloqueio de Na⁺, potenciação GABA e antagonismo NMDA.`,`C) Valproato é primeira escolha em cães.`,`D) Fenitoína é extensamente utilizada na veterinária.`,`E) Não interagem com outros medicamentos.`],resposta_correta:`B`,explicacao:`Fenitoína bloqueia Na⁺ voltagem-dependentes; valproato tem múltiplos mecanismos.`,explicacoes_alternativas:{A:`Fenitoína não potencializa GABA-A.`,B:`Correta. Mecanismos distintos descritos corretamente.`,C:`Fenobarbital é primeira escolha.`,D:`Fenitoína tem biodisponibilidade variável em cães.`,E:`Ambos têm interações hepáticas.`},referencias:[{autores:`Dewey CW`,titulo:`A Practical Guide to Canine and Feline Neurology`,ano:2016}]},{id:`farm-184`,banca:`FCC`,ano:2022,prova:`FCC — Concurso 2022`,tipo:`concurso`,topico:`farmacos_snc`,subtopico:`Antiepilépticos`,dificuldade:`medio`,enunciado:`A carbamazepina raramente é utilizada em cães e gatos. Qual o motivo?`,alternativas:[`A) É primeira escolha em cães.`,`B) Possui meia-vida extremamente curta (1-4 horas), exigindo doses muito frequentes.`,`C) É utilizada rotineiramente em cavalos.`,`D) Não apresenta indução enzimática.`,`E) É escolha para epilepsia felina.`],resposta_correta:`B`,explicacao:`Meia-vida muito curta inviabiliza uso clínico em cães e gatos.`,explicacoes_alternativas:{A:`Fenobarbital e brometo são primeira escolha.`,B:`Correta. Meia-vida curta inviabiliza uso.`,C:`Não é usada rotineiramente em cavalos.`,D:`É potente indutora enzimática.`,E:`Fenobarbital é primeira escolha em gatos.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2018}]},{id:`farm-185`,banca:`UFMG`,ano:2019,prova:`UFMG — Residência 2019`,tipo:`residencia`,topico:`farmacos_snc`,subtopico:`Benzodiazepínicos`,dificuldade:`facil`,enunciado:`O diazepam pode causar necrose hepática idiossincrática em gatos. Sobre esse risco, é correto afirmar:`,alternativas:[`A) É contraindicado por causar insuficiência renal.`,`B) Pode causar necrose hepática fulminante idiossincrática, mesmo em doses terapêuticas.`,`C) É metabolizado mais lentamente em gatos.`,`D) Não apresenta efeito estimulante de apetite.`,`E) É seguro para uso tópico crônico sem riscos.`],resposta_correta:`B`,explicacao:`Diazepam pode causar necrose hepática idiossincrática em gatos, raro porém potencialmente fatal.`,explicacoes_alternativas:{A:`O risco é hepático, não renal.`,B:`Correta. Necrose hepática idiossincrática.`,C:`Farmacocinética não exige necessariamente doses menores.`,D:`Possui efeito estimulante de apetite.`,E:`Uso tópico pode causar absorção sistêmica.`},referencias:[{autores:`Center SA et al.`,titulo:`Fatal hepatic necrosis with diazepam in cats`,ano:1996}]},{id:`farm-186`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`farmacos_antipruriginosos`,subtopico:`Inibidores de Janus quinase`,dificuldade:`medio`,enunciado:`O oclacitinib (Apoquel®) é inibidor seletivo de JAK1/JAK2. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É inibidor da calcineurina.`,`B) Bloqueia sinalização de citocinas como IL-31, principal citocina pruritogênica na dermatite atópica canina.`,`C) É antagonista H1.`,`D) É corticosteroide de última geração.`,`E) Inibe seletivamente COX-2.`],resposta_correta:`B`,explicacao:`Oclacitinib inibe JAK1/JAK2, bloqueando IL-31 e outras citocinas dependentes de JAK.`,explicacoes_alternativas:{A:`Inibidores de calcineurina são tacrolimo/pimecrolima.`,B:`Correta. Inibe JAK1/JAK2, bloqueando IL-31.`,C:`Não é anti-histamínico.`,D:`Não é corticosteroide.`,E:`Não inibe COX-2.`},referencias:[{autores:`Gonzales AJ et al.`,titulo:`Oclacitinib is a novel JAK inhibitor`,ano:2014}]},{id:`farm-187`,banca:`CESPE/CEBRASPE`,ano:2023,prova:`CESPE — Concurso 2023`,tipo:`concurso`,topico:`farmacos_antipruriginosos`,subtopico:`Terapia biológica`,dificuldade:`medio`,enunciado:`O lokivetmab (Cytopoint®) é anticorpo monoclonal anti-IL-31. Sobre esse fármaco, é correto afirmar:`,alternativas:[`A) Bloqueia receptor de IL-31, via oral.`,`B) É anticorpo monoclonal caninizado que neutraliza IL-31 canina, SC a cada 4-8 semanas.`,`C) É inibidor de JAK com mecanismo idêntico ao oclacitinib.`,`D) É corticosteroide de ação prolongada.`,`E) Bloqueia seletivamente histamina.`],resposta_correta:`B`,explicacao:`Lokivetmab é anticorpo monoclonal caninizado anti-IL-31, SC a cada 4-8 semanas.`,explicacoes_alternativas:{A:`Neutraliza IL-31 (ligante), não receptor.`,B:`Correta. Anticorpo monoclonal caninizado anti-IL-31.`,C:`Não é inibidor de JAK.`,D:`Não é corticosteroide.`,E:`Não bloqueia histamina.`},referencias:[{autores:`Gonzales AJ et al.`,titulo:`Anti-IL-31 antibody treatment`,ano:2016}]},{id:`farm-188`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`farmacos_antipruriginosos`,subtopico:`Anti-histamínicos`,dificuldade:`facil`,enunciado:`A difenidramina é antagonista H1 de primeira geração. Sobre suas características, é correto afirmar:`,alternativas:[`A) É anti-histamínico de segunda geração sem sedação.`,`B) É antagonista H1 de primeira geração com efeito sedativo significativo.`,`C) É contraindicada em cães por hepatotoxicidade.`,`D) Possui meia-vida de 48 horas.`,`E) É agonista H2.`],resposta_correta:`B`,explicacao:`Difenidramina é antagonista H1 de primeira geração com sedação significativa.`,explicacoes_alternativas:{A:`É de primeira geração com sedação.`,B:`Correta. Antagonista H1 de primeira geração com sedação.`,C:`É geralmente segura em cães.`,D:`Meia-vida de 4-8 horas.`,E:`É antagonista H1.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2018}]},{id:`farm-189`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`farmacos_anticancer`,subtopico:`Inibidores de tirosina quinase`,dificuldade:`medio`,enunciado:`O toceranib (Palladia®) é inibidor multiquinase (VEGFR, PDGFR, KIT). Sobre seu uso, é correto afirmar:`,alternativas:[`A) Inibe seletivamente diidrofolato redutase.`,`B) É indicado para mastocitoma cutâneo em cães.`,`C) É agente alquilante.`,`D) É indicado exclusivamente para neoplasias mamárias.`,`E) Não apresenta efeitos adversos GI.`],resposta_correta:`B`,explicacao:`Toceranib é inibidor multiquinase aprovado para mastocitoma em cães.`,explicacoes_alternativas:{A:`Não é antimetabólito.`,B:`Correta. Indicado para mastocitoma.`,C:`Não é alquilante.`,D:`Indicação principal é mastocitoma.`,E:`Pode causar efeitos GI significativos.`},referencias:[{autores:`London CA et al.`,titulo:`Phase I study of toceranib`,ano:2009}]},{id:`farm-190`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso 2020`,tipo:`concurso`,topico:`farmacos_anticancer`,subtopico:`AINEs em oncologia`,dificuldade:`medio`,enunciado:`O piroxicam possui atividade antitumoral via inibição de COX-2. Sobre essa aplicação, é correto afirmar:`,alternativas:[`A) É primeira linha para todos os tipos de neoplasias.`,`B) COX-2 é superexpressa em diversos tumores, incluindo carcinoma de células transicionais da bexiga.`,`C) Atua por intercalação no DNA.`,`D) Não pode ser associado a outros quimioterápicos.`,`E) É contraindicado em neoplasias por imunossupressão.`],resposta_correta:`B`,explicacao:`Piroxicam inibe COX-2 superexpressa em neoplasias, com atividade em TCC e carcinoma oral.`,explicacoes_alternativas:{A:`Não é primeira linha universal.`,B:`Correta. COX-2 superexpressa em tumores.`,C:`Não intercala DNA.`,D:`Pode ser associado.`,E:`Não causa imunossupressão grave.`},referencias:[{autores:`Knapp DW et al.`,titulo:`Piroxicam in dogs with TCC`,ano:1994}]},{id:`farm-191`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`farmacos_anticancer`,subtopico:`Antiprotozoários em oncologia`,dificuldade:`medio`,enunciado:`O metronidazol possui atividade citotóxica em ambientes hipóxicos. Sobre essa aplicação oncológica, é correto afirmar:`,alternativas:[`A) É quimioterápico exclusivo para linfoma.`,`B) Em hipóxia, é reduzido a metabólitos tóxicos que danificam DNA, atuando como radiosensibilizador.`,`C) Atua como inibidor de topoisomerase II.`,`D) É contraindicado em oncologia por neurotoxicidade irreversível.`,`E) Não possui aplicação oncológica.`],resposta_correta:`B`,explicacao:`Metronidazol é seletivamente tóxico em hipóxia, atuando como radiosensibilizador.`,explicacoes_alternativas:{A:`Não é exclusivo para linfoma.`,B:`Correta. Radiosensibilizador em hipóxia.`,C:`Não é inibidor de topoisomerase II.`,D:`Neurotoxicidade é reversível.`,E:`Possui aplicações oncológicas.`},referencias:[{autores:`Withrow SJ et al.`,titulo:`Small Animal Clinical Oncology`,ano:2013}]},{id:`farm-192`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`concurso`,topico:`farmacos_cardio_avancos`,subtopico:`Inodilatadores`,dificuldade:`medio`,enunciado:`O pimobendan possui mecanismo de ação duplo. Assinale a correta:`,alternativas:[`A) É exclusivamente vasodilatador.`,`B) Possui ação inotrópica positiva por sensibilização ao Ca²⁺ e vasodilatação por inibição de PDE3.`,`C) É betabloqueador seletivo.`,`D) É inibidor da ECA.`,`E) Bloqueia canais de cálcio tipo L.`],resposta_correta:`B`,explicacao:`Pimobendan: sensibilização ao Ca²⁺ (inotropismo) + inibição PDE3 (vasodilatação).`,explicacoes_alternativas:{A:`Também tem efeito inotrópico.`,B:`Correta. Mecanismo duplo.`,C:`Não é betabloqueador.`,D:`Não é IECA.`,E:`Não bloqueia canais de Ca²⁺.`},referencias:[{autores:`Ljungvall I et al.`,titulo:`Effects of pimobendan`,ano:2014}]},{id:`farm-193`,banca:`CESPE/CEBRASPE`,ano:2021,prova:`CESPE — Concurso 2021`,tipo:`concurso`,topico:`farmacos_cardio_avancos`,subtopico:`Inibidores da ECA`,dificuldade:`medio`,enunciado:`O benazepril é IECA utilizado em cardiologia e nefrologia. Sobre suas características, é correto afirmar:`,alternativas:[`A) É pró-fármaco convertido em benazeprilato, usado em ICC e DRC.`,`B) Inibe diretamente receptores AT1.`,`C) Não interfere no SRAA.`,`D) É contraindicado em ICC.`,`E) É metabolizado exclusivamente pelos rins.`],resposta_correta:`A`,explicacao:`Benazepril é pró-fármaco → benazeprilato, usado em ICC e DRC.`,explicacoes_alternativas:{A:`Correta. Pró-fármaco para ICC e DRC.`,B:`BRA inibem AT1, não IECA.`,C:`Inibe o SRAA.`,D:`É indicado na ICC.`,E:`Eliminação dupla hepática/renal.`},referencias:[{autores:`Atkins CE et al.`,titulo:`Efficacy of benazepril in CHF`,ano:2007}]},{id:`farm-194`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso 2022`,tipo:`concurso`,topico:`farmacos_cardio_avancos`,subtopico:`Antiplaquetários`,dificuldade:`dificil`,enunciado:`O clopidogrel é pró-fármaco antiplaquetário. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) Inibe diretamente a trombina.`,`B) Após metabolização pelo CYP2C19, seu metabólito se liga irreversivelmente ao receptor P2Y12 de ADP.`,`C) Inibe COX-1 plaquetária.`,`D) É antagonista de GPIIb/IIIa.`,`E) Inibe fosfodiesterase plaquetária.`],resposta_correta:`B`,explicacao:`Clopidogrel: pró-fármaco → CYP2C19 → bloqueio irreversível P2Y12.`,explicacoes_alternativas:{A:`Inibidores de trombina são argatraban/dabigatrana.`,B:`Correta. Pró-fármaco → bloqueio P2Y12.`,C:`Inibição de COX-1 é da aspirina.`,D:`Antagonistas GPIIb/IIIa incluem abciximabe.`,E:`Inibidores de PDE incluem dipiridamol.`},referencias:[{autores:`Hogan DF et al.`,titulo:`Antiplatelet effects of clopidogrel in cats`,ano:2010}]},{id:`farm-195`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`concurso`,topico:`farmacos_respiratorios_avancos`,subtopico:`Broncodilatadores`,dificuldade:`medio`,enunciado:`A terbutalina é agonista seletivo beta-2. Sobre seu perfil, é correto afirmar:`,alternativas:[`A) É agonista seletivo beta-1.`,`B) Promove broncodilatação, relaxamento uterino e vasodilatação periférica.`,`C) É antagonista beta-2.`,`D) É anticolinérgico.`,`E) É inibidor de fosfodiesterase.`],resposta_correta:`B`,explicacao:`Terbutalina: agonista seletivo beta-2 com efeitos broncodilatador, tocolítico e vasodilatador.`,explicacoes_alternativas:{A:`É seletiva beta-2.`,B:`Correta. Agonista seletivo beta-2.`,C:`É agonista, não antagonista.`,D:`Não é anticolinérgica.`,E:`Não é inibidora de PDE.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-196`,banca:`CESPE/CEBRASPE`,ano:2020,prova:`CESPE — Concurso 2020`,tipo:`concurso`,topico:`farmacos_respiratorios_avancos`,subtopico:`Analepticos respiratórios`,dificuldade:`medio`,enunciado:`O doxapram estimula quimiorreceptores carotídeos e centro respiratório medular. É utilizado para:`,alternativas:[`A) Depressor do centro respiratório.`,`B) Antagonizar depressão respiratória por anestésicos.`,`C) Bloqueio neuromuscular.`,`D) Antagonismo opioide.`,`E) É contraindicado em neonatos.`],resposta_correta:`B`,explicacao:`Doxapram é estimulante respiratório usado para reverter depressão por anestésicos.`,explicacoes_alternativas:{A:`É estimulante, não depressor.`,B:`Correta. Antagoniza depressão respiratória.`,C:`Não é bloqueador neuromuscular.`,D:`Naloxona antagoniza opioides.`,E:`É usado em neonatos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-197`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`farmacos_respiratorios_avancos`,subtopico:`Mucolíticos`,dificuldade:`medio`,enunciado:`A acetilcisteína rompe ligações dissulfeto do muco. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) Inibe produção de muco.`,`B) Rompe ligações dissulfeto das glicoproteínas do muco, reduzindo viscosidade. É precursora de glutationa.`,`C) É surfactante exógeno.`,`D) É broncodilatadora.`,`E) É contraindicada em gatos.`],resposta_correta:`B`,explicacao:`Acetilcisteína rompe dissulfeto do muco e é precursora de GSH.`,explicacoes_alternativas:{A:`Não inibe produção — liquefaz.`,B:`Correta. Rompe dissulfeto e precursora de GSH.`,C:`Não é surfactante.`,D:`Não é broncodilatadora.`,E:`Pode ser usada em gatos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-198`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`farmacos_antiemeticos_avancos`,subtopico:`Antagonistas NK1`,dificuldade:`medio`,enunciado:`O maropitant (Cerenia®) é antagonista seletivo NK1 da substância P. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É antagonista H2.`,`B) É antagonista seletivo NK1 da substância P no centro do vômito e CTZ.`,`C) É antagonista D2.`,`D) É inibidor da bomba de prótons.`,`E) É agonista 5-HT3.`],resposta_correta:`B`,explicacao:`Maropitant: antagonista NK1 da substância P no centro do vômito e CTZ.`,explicacoes_alternativas:{A:`Antagonistas H2 incluem ranitidina.`,B:`Correta. Antagonista NK1.`,C:`Antagonistas D2 incluem metoclopramida.`,D:`IBP incluem omeprazol.`,E:`Antagonistas 5-HT3 incluem ondansetrona.`},referencias:[{autores:`de la Puente-Redondo VA et al.`,titulo:`Efficacy of maropitant`,ano:2007}]},{id:`farm-199`,banca:`CESPE/CEBRASPE`,ano:2019,prova:`CESPE — Concurso 2019`,tipo:`concurso`,topico:`farmacos_antiemeticos_avancos`,subtopico:`Procinéticos`,dificuldade:`medio`,enunciado:`A metoclopramida é procinética e antiemética. Sobre suas características, é INCORRETO afirmar:`,alternativas:[`A) É antagonista D2.`,`B) Possui ação procinética no trato GI superior.`,`C) É antagonista 5-HT3 em altas doses.`,`D) Pode causar efeitos extrapiramidais.`,`E) É contraindicada em obstrução GI.`],resposta_correta:`C`,explicacao:`Metoclopramida é antagonista D2 e 5-HT4 (não 5-HT3) em altas doses.`,explicacoes_alternativas:{A:`Correta. Antagonista D2.`,B:`Correta. Ação procinética.`,C:`INCORRETA. É 5-HT4, não 5-HT3.`,D:`Correta. Efeitos extrapiramidais.`,E:`Correta. Contraindicada em obstrução GI.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-200`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso 2020`,tipo:`concurso`,topico:`farmacos_antiemeticos_avancos`,subtopico:`Fenotiazínicos`,dificuldade:`medio`,enunciado:`A clorpromazina é antagonista D2 com perfil farmacológico amplo. Sobre seu uso, é correto afirmar:`,alternativas:[`A) É antagonista seletivo 5-HT3.`,`B) É antagonista D2 com efeito antiemético, sedativo, antipsicótico e hipotensor (bloqueio alfa-1).`,`C) É agonista dopaminérgico.`,`D) É contraindicada em cães por convulsões.`,`E) Não apresenta efeitos sedativos.`],resposta_correta:`B`,explicacao:`Clorpromazina: antagonista D2 com efeitos antiemético, sedativo, antipsicótico e hipotensor.`,explicacoes_alternativas:{A:`Não é antagonista 5-HT3.`,B:`Correta. Perfil farmacológico amplo.`,C:`É antagonista, não agonista.`,D:`É utilizada em cães.`,E:`Possui sedação significativa.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-201`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`concurso`,topico:`farmacos_laxantes`,subtopico:`Osmóticos`,dificuldade:`medio`,enunciado:`A lactulose é fermentada por bactérias colônicas em ácidos orgânicos. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É dissacarídeo sintético com efeito osmótico via fermentação bacteriana.`,`B) É laxante estimulante.`,`C) É emoliente fecal.`,`D) É lubrificante.`,`E) Não tem papel em encefalopatia hepática.`],resposta_correta:`A`,explicacao:`Lactulose: fermentada em ácidos orgânicos → acidificação + efeito osmótico.`,explicacoes_alternativas:{A:`Correta. Efeito osmótico via fermentação.`,B:`Não é estimulante.`,C:`Não é emoliente.`,D:`Não é lubrificante.`,E:`Indicada em encefalopatia hepática.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-202`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso 2022`,tipo:`concurso`,topico:`farmacos_laxantes`,subtopico:`Estimulantes`,dificuldade:`medio`,enunciado:`O bisacodil é pró-fármaco laxante estimulante. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É laxante osmótico.`,`B) É pró-fármaco hidrolisado no intestino, estimulando nervos mioentéricos do cólon.`,`C) É emoliente fecal.`,`D) É agente formador de volume.`,`E) Atua exclusivamente no intestino delgado.`],resposta_correta:`B`,explicacao:`Bisacodil: pró-fármaco → estimulação mioentérica colônica.`,explicacoes_alternativas:{A:`Não é osmótico.`,B:`Correta. Pró-fármaco estimulante mioentérico.`,C:`Não é emoliente.`,D:`Não é formador de volume.`,E:`Atua primariamente no cólon.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-203`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`farmacos_laxantes`,subtopico:`Formadores de volume`,dificuldade:`facil`,enunciado:`O psyllium é fibra solúvel que forma gel hidrofílico. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É laxante estimulante.`,`B) Forma gel hidrofílico, aumentando volume e hidratação das fezes.`,`C) É lubrificante.`,`D) É osmótico.`,`E) Não é recomendado para felinos.`],resposta_correta:`B`,explicacao:`Psyllium: fibra solúvel → gel → aumento de volume fecal.`,explicacoes_alternativas:{A:`Não é estimulante.`,B:`Correta. Fibra solúvel que forma gel.`,C:`Não é lubrificante.`,D:`Não é primariamente osmótico.`,E:`Pode ser usado em felinos.`},referencias:[{autores:`Riviere JE, Papich MG`,titulo:`Veterinary Pharmacology and Therapeutics`,ano:2018}]},{id:`farm-204`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`farmacos_oftalmicos_avancos`,subtopico:`Imunomoduladores oculares`,dificuldade:`medio`,enunciado:`O tacrolimo é inibidor da calcineurina via FKBP-12. Sobre seu uso ocular, é correto afirmar:`,alternativas:[`A) É corticosteroide tópico.`,`B) Inibe calcineurina via FKBP-12, reduzindo produção de IL-2 e ativação de linfócitos T.`,`C) É antibiótico tópico.`,`D) Tem mecanismo idêntico à ciclosporina.`,`E) Atua como lacrimomimético.`],resposta_correta:`B`,explicacao:`Tacrolimo: inibe calcineurina via FKBP-12 → reduz IL-2 e ativação de linfócitos T.`,explicacoes_alternativas:{A:`Não é corticosteroide.`,B:`Correta. Inibe calcineurina via FKBP-12.`,C:`Não é antibiótico.`,D:`Tacrolimo é mais potente que ciclosporina.`,E:`Não é lacrimomimético.`},referencias:[{autores:`Berdoulay A et al.`,titulo:`Tacrolimus in dogs with KCS`,ano:2016}]},{id:`farm-205`,banca:`CESPE/CEBRASPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`farmacos_oftalmicos_avancos`,subtopico:`Antiglaucomatosos`,dificuldade:`medio`,enunciado:`A latanoprosta é análogo de PGF2-alfa que reduz PIO. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) Inibe produção de humor aquoso.`,`B) Agonista FP que aumenta escoamento uveoescleral.`,`C) É betabloqueador tópico.`,`D) É inibidor de anidrase carbônica.`,`E) É contraindicada em glaucoma.`],resposta_correta:`B`,explicacao:`Latanoprosta: agonista FP → aumento de escoamento uveoescleral → redução de PIO.`,explicacoes_alternativas:{A:`Não inibe produção — aumenta escoamento.`,B:`Correta. Agonista FP via uveoescleral.`,C:`Betabloqueadores incluem timolol.`,D:`Inibidores de anidrase incluem dorzolamida.`,E:`É indicada em glaucoma.`},referencias:[{autores:`Studer ME et al.`,titulo:`Latanoprost for glaucoma in dogs`,ano:2e3}]},{id:`farm-206`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso 2020`,tipo:`concurso`,topico:`farmacos_oftalmicos_avancos`,subtopico:`AINEs oculares`,dificuldade:`facil`,enunciado:`O diclofenaco ocular inibe COX-1 e COX-2. Sobre suas indicações oftálmicas, é correto afirmar:`,alternativas:[`A) Inibe seletivamente COX-2.`,`B) Utilizado para inflamação pós-cirúrgica, dor ocular e prevenção de miose intraoperatória.`,`C) É corticosteroide tópico.`,`D) Inibe seletivamente COX-1.`,`E) Atua como midriático.`],resposta_correta:`B`,explicacao:`Diclofenaco ocular: AINE não-seletivo para inflamação, dor e prevenção de miose.`,explicacoes_alternativas:{A:`Não é seletivo COX-2.`,B:`Correta. Múltiplas indicações oftálmicas.`,C:`Não é corticosteroide.`,D:`Não é seletivo COX-1.`,E:`Previne miose, não é midriático.`},referencias:[{autores:`Maggs DJ`,titulo:`Slatter's Fundamentals of Veterinary Ophthalmology`,ano:2017}]},{id:`farm-207`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`concurso`,topico:`farmacos_dermatologicos_avancos`,subtopico:`Antibióticos dermatológicos`,dificuldade:`medio`,enunciado:`A cefovecina (Convenia®) é cefalosporina 3ª geração SC de longa ação. Sobre suas características, é correto afirmar:`,alternativas:[`A) É administrada por via oral.`,`B) SC com meia-vida ~13 dias em cães, eficaz contra gram-positivos e gram-negativos.`,`C) Possui cobertura anaeróbica completa.`,`D) É contraindicada em gatos.`,`E) É macrolídeo.`],resposta_correta:`B`,explicacao:`Cefovecina: SC, meia-vida ~13 dias, cefalosporina 3ª geração.`,explicacoes_alternativas:{A:`É SC, não oral.`,B:`Correta. SC, meia-vida prolongada.`,C:`Não tem cobertura anaeróbica completa.`,D:`É segura em gatos.`,E:`É cefalosporina.`},referencias:[{autores:`Stegemann MR et al.`,titulo:`Pharmacokinetics of cefovecin`,ano:2006}]},{id:`farm-208`,banca:`CESPE/CEBRASPE`,ano:2021,prova:`CESPE — Concurso 2021`,tipo:`concurso`,topico:`farmacos_dermatologicos_avancos`,subtopico:`Antibióticos dermatológicos`,dificuldade:`medio`,enunciado:`O cefadroxil (Simplicef®) é cefalosporina 1ª geração oral. Sobre suas características, é correto afirmar:`,alternativas:[`A) É cefalosporina 3ª geração SC.`,`B) É cefalosporina 1ª geração oral com boa biodisponibilidade para infecções de pele.`,`C) É aminopenicilina com inibidor de beta-lactamase.`,`D) Não é absorvido por via oral.`,`E) Possui atividade antifúngica.`],resposta_correta:`B`,explicacao:`Cefadroxil: cefalosporina 1ª geração oral para infecções cutâneas.`,explicacoes_alternativas:{A:`É 1ª geração oral.`,B:`Correta. Cefalosporina 1ª geração oral.`,C:`É cefalosporina pura.`,D:`Tem boa absorção oral.`,E:`Não tem atividade antifúngica.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2018}]},{id:`farm-209`,banca:`FCC`,ano:2022,prova:`FCC — Concurso 2022`,tipo:`concurso`,topico:`farmacos_dermatologicos_avancos`,subtopico:`Inibidores de JAK`,dificuldade:`dificil`,enunciado:`O oclacitinib possui efeitos anti-inflamatórios além do antipruriginoso. Analise as afirmativas:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,explicacao:`Todas as afirmativas são verdadeiras.`,explicacoes_alternativas:{A:`Correta. Todas verdadeiras.`,B:`Incorreta.`,C:`Incorreta.`,D:`Incorreta.`,E:`Incorreta.`},referencias:[{autores:`Cosgrove SB et al.`,titulo:`Efficacy of oclacitinib`,ano:2013}],vf:!0,vf_texto:`( ) Inibe JAK1/JAK2 e também JAK3/TYK2 em concentrações mais elevadas.
( ) É aprovado para cães a partir de 12 meses e peso mínimo de 3 kg.
( ) Efeitos adversos incluem gastroenterite, apatia e infecções cutâneas secundárias.`},{id:`farm-210`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`concurso`,topico:`farmacologia_renal_avancos`,subtopico:`Nefroproteção`,dificuldade:`medio`,enunciado:`O benazepril é nefroprotetor por vasodilatação preferencial da arteríola eferente. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) Causa vasoconstrição da arteríola aferente.`,`B) Inibe ECA, reduzindo angiotensina II e promovendo vasodilatação eferente.`,`C) Aumenta filtração glomerular.`,`D) Não possui efeitos renais.`,`E) É contraindicado em proteinúria.`],resposta_correta:`B`,explicacao:`Benazepril: inibe ECA → vasodilatação eferente → redução de pressão glomerular e proteinúria.`,explicacoes_alternativas:{A:`Dilata eferente, não contrai aferente.`,B:`Correta. Vasodilatação eferente.`,C:`Reduz pressão intraglomerular.`,D:`Tem efeitos renais significativos.`,E:`É indicado para reduzir proteinúria.`},referencias:[{autores:`King JN et al.`,titulo:`Benazepril in cats with CKD`,ano:2006}]},{id:`farm-211`,banca:`CESPE/CEBRASPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`farmacologia_renal_avancos`,subtopico:`BRA nefroproteção`,dificuldade:`medio`,enunciado:`O telmisartan é BRA seletivo AT1. Sobre suas características, é correto afirmar:`,alternativas:[`A) É IECA.`,`B) É antagonista seletivo AT1, reduzindo proteinúria sem acúmulo de bradicinina.`,`C) Causa vasoconstrição renal.`,`D) Não pode ser associado a IECA.`,`E) É antagonista AT2.`],resposta_correta:`B`,explicacao:`Telmisartan: BRA seletivo AT1, reduz proteinúria sem acúmulo de bradicinina.`,explicacoes_alternativas:{A:`Não é IECA, é BRA.`,B:`Correta. BRA seletivo AT1.`,C:`Promove vasodilatação.`,D:`Pode ser associado com monitoramento.`,E:`É antagonista AT1, não AT2.`},referencias:[{autores:`Sent U et al.`,titulo:`Telmisartan in cats with CKD`,ano:2017}]},{id:`farm-212`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso 2020`,tipo:`concurso`,topico:`farmacologia_renal_avancos`,subtopico:`Pimobendan renal`,dificuldade:`dificil`,enunciado:`O pimobendan tem sido estudado em DRC associada a cardiopatias. Analise as afirmativas:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,explicacao:`Sequência V-F-V.`,explicacoes_alternativas:{A:`Correta. V-F-V.`,B:`Incorreta.`,C:`Incorreta.`,D:`Incorreta.`,E:`Incorreta.`},referencias:[{autores:`Haggstrom J et al.`,titulo:`Long-term use of pimobendan`,ano:2008}],vf:!0,vf_texto:`( ) Pode melhorar perfusão renal por efeito vasodilatador.
( ) É contraindicado em todos os pacientes com DRC.
( ) Pode ter efeito nefroprotetor em alguns cenários.`},{id:`farm-213`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`concurso`,topico:`farmacologia_hepatica`,subtopico:`Hepatoprotetores`,dificuldade:`medio`,enunciado:`A silimarina possui ação antioxidante, anti-inflamatória e hepatoprotetora. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É antibiótico de amplo espectro.`,`B) Possui ação antioxidante, anti-inflamatória (inibe NF-kB) e hepatoprotetora.`,`C) É corticosteroide sintético.`,`D) Atua exclusivamente como colerético.`,`E) É contraindicada em hepatopatias.`],resposta_correta:`B`,explicacao:`Silimarina: antioxidante + anti-inflamatória + estabilizadora de membranas hepatocelulares.`,explicacoes_alternativas:{A:`Não é antibiótico.`,B:`Correta. Múltiplas ações hepatoprotetoras.`,C:`Não é corticosteroide.`,D:`Tem efeitos antioxidantes além de colerese.`,E:`É indicada em hepatopatias.`},referencias:[{autores:`Saller R et al.`,titulo:`Silymarin in liver diseases`,ano:2001}]},{id:`farm-214`,banca:`CESPE/CEBRASPE`,ano:2021,prova:`CESPE — Concurso 2021`,tipo:`concurso`,topico:`farmacologia_hepatica`,subtopico:`Hepatoprotetores`,dificuldade:`medio`,enunciado:`O ursodiol é ácido biliar hidrofílico. Sobre suas ações, é correto afirmar:`,alternativas:[`A) É ácido biliar hidrofóbico tóxico.`,`B) Substitui ácidos biliares citotóxicos, com ação colerética, hepatoprotetora e imunomoduladora.`,`C) É antibiótico.`,`D) Não afeta metabolismo do colesterol.`,`E) É contraindicado em hepatopatias.`],resposta_correta:`B`,explicacao:`Ursodiol: ácido biliar hidrofílico com ações colerética, hepatoprotetora e imunomoduladora.`,explicacoes_alternativas:{A:`É hidrofílico e não-tóxico.`,B:`Correta. Múltiplas ações hepatoprotetoras.`,C:`Não é antibiótico.`,D:`Afeta metabolismo do colesterol.`,E:`É indicado em hepatopatias.`},referencias:[{autores:`Plumb DC`,titulo:`Plumb's Veterinary Drug Handbook`,ano:2018}]},{id:`farm-215`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso 2022`,tipo:`concurso`,topico:`farmacologia_hepatica`,subtopico:`Hepatoprotetores`,dificuldade:`medio`,enunciado:`A SAMe é doador de metil e precursor de glutationa. Sobre seu mecanismo, é correto afirmar:`,alternativas:[`A) É antibiótico de amplo espectro.`,`B) É doador de grupos metil e precursor de glutationa (GSH), principal antioxidante hepático.`,`C) É ácido biliar sintético.`,`D) É corticosteroide natural.`,`E) É contraindicada em hepatopatias.`],resposta_correta:`B`,explicacao:`SAMe: doador de metil + precursor de GSH → proteção hepatocelular.`,explicacoes_alternativas:{A:`Não é antibiótico.`,B:`Correta. Doador de metil e precursor de GSH.`,C:`Não é ácido biliar.`,D:`Não é corticosteroide.`,E:`É indicada em hepatopatias.`},referencias:[{autores:`Webb CB et al.`,titulo:`SAMe in cats with liver disease`,ano:2009}]},{id:`farm-216`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`concurso`,topico:`farmacologia_nutricional`,subtopico:`Suplementos minerais`,dificuldade:`medio`,enunciado:`O zinco é cofator de mais de 300 enzimas. Sobre suas aplicações dermatológicas, é correto afirmar:`,alternativas:[`A) Não participa de processos enzimáticos.`,`B) É essencial para síntese de queratina, função imune, cicatrização e metabolismo de ácidos graxos.`,`C) É contraindicado em dermatite.`,`D) Impede suplementação de ferro.`,`E) Não interage com outros minerais.`],resposta_correta:`B`,explicacao:`Zinco: cofator de 300+ enzimas, essencial para queratina, imunidade e cicatrização.`,explicacoes_alternativas:{A:`É cofator de centenas de enzimas.`,B:`Correta. Essencial para múltiplos processos.`,C:`É indicado em dermatopatias.`,D:`Interação existe mas não impede suplementação.`,E:`Interage com cálcio e cobre.`},referencias:[{autores:`Scott DW et al.`,titulo:`Muller and Kirk's Small Animal Dermatology`,ano:2013}]},{id:`farm-217`,banca:`CESPE/CEBRASPE`,ano:2020,prova:`CESPE — Concurso 2020`,tipo:`concurso`,topico:`farmacologia_nutricional`,subtopico:`Vitaminas`,dificuldade:`medio`,enunciado:`A vitamina E é o principal antioxidante lipossolúvel. Sobre suas funções, é correto afirmar:`,alternativas:[`A) É hidrossolúvel.`,`B) Protege membranas celulares contra peroxidação lipídica.`,`C) Não possui ação antioxidante.`,`D) É contraindicada em miopatias.`,`E) Pode ser administrada em doses ilimitadas.`],resposta_correta:`B`,explicacao:`Vitamina E: antioxidante lipossolúvel que protege membranas contra peroxidação.`,explicacoes_alternativas:{A:`É lipossolúvel.`,B:`Correta. Antioxidante lipossolúvel.`,C:`Possui potente ação antioxidante.`,D:`É indicada em miopatias.`,E:`Excesso interfere em outras vitaminas lipossolúveis.`},referencias:[{autores:`Hand MS et al.`,titulo:`Small Animal Clinical Nutrition`,ano:2010}]},{id:`farm-218`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso 2021`,tipo:`concurso`,topico:`farmacologia_nutricional`,subtopico:`Suplementos`,dificuldade:`medio`,enunciado:`Os ômega-3 (EPA e DHA) competem com ácido araquidônico. Sobre suas ações, é correto afirmar:`,alternativas:[`A) São utilizados apenas como fonte calórica.`,`B) Competem com AA, reduzindo eicosanoides pró-inflamatórios e produzindo resolvinas e protectinas.`,`C) Possuem ação pró-inflamatória.`,`D) Não são absorvidos por via oral.`,`E) Não possuem base científica.`],resposta_correta:`B`,explicacao:`Ômega-3: competem com AA → reduzem PGE2/LTB4 → produzem resolvinas/protectinas.`,explicacoes_alternativas:{A:`Têm ação anti-inflamatória.`,B:`Correta. Competem com AA e produzem mediadores anti-inflamatórios.`,C:`São anti-inflamatórios.`,D:`São absorvidos por via oral.`,E:`Possuem forte base científica.`},referencias:[{autores:`Logas D et al.`,titulo:`Omega-3 in dogs with atopic dermatitis`,ano:2014}]},{id:`farm-219`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`concurso`,topico:`farmacologia_ergogenica`,subtopico:`Doping em cavalos`,dificuldade:`dificil`,enunciado:`O doping em cavalos de corrida é preocupação regulatória mundial. Sobre as substâncias proibidas, é correto afirmar:`,alternativas:[`A) A FEI permite AINEs sem restrições.`,`B) A fenilbutazona é uma das substâncias mais frequentemente detectadas em testes antidoping.`,`C) Corticosteroides não são proibidos em competições eqüestres.`,`D) O teste antidoping utiliza apenas urina.`,`E) A EPO nunca foi detectada em cavalos.`],resposta_correta:`B`,explicacao:`Fenilbutazona é um dos AINEs mais detectados no doping eqüino.`,explicacoes_alternativas:{A:`Muitos AINEs são proibidos.`,B:`Correta. Fenilbutazona frequentemente detectada.`,C:`Corticosteroides são proibidos/restritos.`,D:`Testes usam sangue, urina e cabelo.`,E:`EPO já foi detectada.`},referencias:[{autores:`Tobin T`,titulo:`Drugs and the Performance Horse`,ano:1981}]},{id:`farm-220`,banca:`CESPE/CEBRASPE`,ano:2021,prova:`CESPE — Concurso 2021`,tipo:`concurso`,topico:`farmacologia_ergogenica`,subtopico:`Substâncias proibidas`,dificuldade:`medio`,enunciado:`Diversas classes são proibidas em competições eqüestres. Assinale a correta:`,alternativas:[`A) Vitaminas B são proibidas em todas as competições.`,`B) Agentes anabolizantes (estanazolol, boldenona, nandrolona) são proibidos por efeitos ergogênicos.`,`C) Antibióticos tópicos são universalmente proibidos.`,`D) Probióticos são substâncias proibidas.`,`E) Água destilada é substância proibida.`],resposta_correta:`B`,explicacao:`Anabolizantes são proibidos por promoverem aumento de massa muscular e desempenho.`,explicacoes_alternativas:{A:`Vitaminas B não são proibidas.`,B:`Correta. Anabolizantes são proibidos.`,C:`Antibióticos tópicos não são universalmente proibidos.`,D:`Probióticos não são proibidos.`,E:`Água destilada não é proibida.`},referencias:[{autores:`FEI`,titulo:`Equine Anti-Doping Regulations`,ano:2022}]}],i={totalQuestoes:r.length,porBanca:Object.entries(r.reduce((e,t)=>(e[t.banca]=(e[t.banca]||0)+1,e),{})).map(([t,n])=>({banca:t,total:n,...e[t]})),porAno:Object.entries(r.reduce((e,t)=>(e[t.ano]=(e[t.ano]||0)+1,e),{})).map(([e,t])=>({ano:Number(e),total:t})).sort((e,t)=>t.ano-e.ano),porTopico:Object.entries(r.reduce((e,t)=>(e[t.topico]=(e[t.topico]||0)+1,e),{})).map(([e,t])=>({topico:e,nome:n[e]?.nome,total:t})),porDificuldade:Object.entries(r.reduce((e,t)=>(e[t.dificuldade]=(e[t.dificuldade]||0)+1,e),{})).map(([e,t])=>({dificuldade:e,total:t}))};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_FARMACOLOGIA,t as TIPOS_PROVA,n as TOPICOS_FARMACOLOGIA};